-- ClanBridge — all applicable migrations, in order, as one transaction.
--
-- GENERATED by `npm run migrations:bundle`. Do not edit; edit the files in
-- supabase/migrations/ instead.
--
-- Paste this whole file into the Supabase SQL editor and run it once.
-- BEGIN/COMMIT means a failure anywhere rolls the entire thing back, so you
-- cannot end up with a half-applied schema.
--
-- Includes: 001_core.sql, 002_cwl.sql, 003_war.sql, 004_features.sql, 005_operational.sql, 006_rls.sql, 007_member_snapshots.sql, 008_player_left_at.sql, 010_polls.sql, 011_cwl_rosters.sql, 013_user_status.sql, 014_service_role_grants.sql, 015_platform_admin.sql, 016_player_verification.sql, 017_approval_grants_membership.sql, 018_admin_may_approve_clanless.sql, 019_cwl_war_members.sql, 020_clan_details.sql, 021_announcements.sql, 022_cwl_bonus_awards.sql, 023_notifications.sql, 024_war.sql, 025_war_target_claim.sql, 026_war_opponent.sql, 027_raid_detail.sql, 028_base_layouts.sql, 030_account_credentials.sql, 031_own_players_policy.sql, 032_link_verified_player_v2.sql, 033_player_nicknames.sql, 034_user_avatar.sql, 036_player_progress.sql, 037_family_cwl_history.sql, 038_family_directory.sql, 039_account_administration.sql
--
-- Two numbers are absent, retired rather than reused so that apply order
-- stays equal to numeric order: 009 (cwl_signups, superseded by Phase 4B)
-- and 012 (war_lineups, delivered by 024 instead). 012's file remains on
-- disk as a comment-only tombstone and applies nothing.

begin;

-- ========================================================================
-- 001_core.sql
-- ========================================================================

-- T1.4 — Core tables: clans, users, players, clan_roles.
--
-- Apply in the Supabase SQL editor, in numeric order. Once applied, never edit
-- this file — fix forward with a new migration (section 4).
--
-- Conventions: snake_case, plural names, uuid primary keys, created_at on every
-- table, deleted_at on every table (R4 — nothing is ever deleted).

-- ---------------------------------------------------------------------------
-- Shared helper: keep updated_at honest without relying on every caller.
-- ---------------------------------------------------------------------------
create or replace function set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;


-- ---------------------------------------------------------------------------
-- clans — the three clans. Seeded by supabase/seed.sql (T1.10).
-- ---------------------------------------------------------------------------
create table clans (
  id          uuid primary key default gen_random_uuid(),
  tag         text not null unique,
  name        text not null,
  badge_url   text,
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz,
  deleted_at  timestamptz,

  -- Section 4: tags are stored with the hash and uppercased on write.
  -- Enforced here so a bad write fails loudly instead of producing a 404 later.
  --
  -- The pattern is Supercell's actual tag alphabet. Note the characters that are
  -- absent: I, O, S and most digits. Checking only case and the leading hash
  -- would accept '#REPLACE1', which lib/tags.ts rejects — the database and the
  -- parser must agree, or a placeholder survives into production.
  constraint clans_tag_format check (tag ~ '^#[0289PYLQGRJCUV]{3,12}$')
);

create trigger clans_set_updated_at
  before update on clans
  for each row execute function set_updated_at();


-- ---------------------------------------------------------------------------
-- users — application profile, one per Supabase auth user.
--
-- Architecture.md 7.1 puts the auth user above the profile, so id IS the auth
-- user id rather than a separate key. on delete restrict, never cascade: R4
-- means a row is never removed as a side effect of something else.
-- ---------------------------------------------------------------------------
create table users (
  id            uuid primary key references auth.users (id) on delete restrict,
  email         text not null,
  display_name  text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz,
  deleted_at    timestamptz
);

create trigger users_set_updated_at
  before update on users
  for each row execute function set_updated_at();


-- ---------------------------------------------------------------------------
-- players — one row per Clash of Clans account.
--
-- Written by scripts/sync/clans.ts from the clan member list (R11: game fact).
-- user_id is NULLABLE and stays null until the player verifies at T3.3 — sync
-- creates these rows long before anyone claims them.
-- ---------------------------------------------------------------------------
create table players (
  id            uuid primary key default gen_random_uuid(),
  clan_id       uuid references clans (id) on delete restrict,
  user_id       uuid references users (id) on delete restrict,
  tag           text not null unique,          -- T1.4: the idempotency key for sync
  name          text not null,
  th_level      smallint,
  verified      boolean not null default false,
  -- NOT named current_role: that is a reserved keyword in PostgreSQL and the
  -- create table fails outright with a syntax error. proposal_idea.md section
  -- 10.1 sketches it as current_role; this is the corrected name.
  clan_role     text check (clan_role in ('leader', 'co-leader', 'elder', 'member')),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz,
  deleted_at    timestamptz,

  -- Supercell's tag alphabet, not merely "uppercase with a hash". This rejects
  -- a tag containing the letter O, which is the most common transcription error
  -- and would otherwise sit in the database producing 404s against the API.
  constraint players_tag_format check (tag ~ '^#[0289PYLQGRJCUV]{3,12}$')
);

create trigger players_set_updated_at
  before update on players
  for each row execute function set_updated_at();

-- Partial indexes: every read filters deleted_at is null, so the dead rows are
-- not worth indexing.
create index players_clan_id_idx on players (clan_id) where deleted_at is null;
create index players_user_id_idx on players (user_id) where deleted_at is null;


-- ---------------------------------------------------------------------------
-- clan_roles — a user's role within one clan.
--
-- Roles are PER CLAN, not global: co-leader of clan A is an ordinary member of
-- clan B. This table is also what auth_clan_ids() reads in 006_rls.sql, which
-- makes it the root of the whole authorisation model.
-- ---------------------------------------------------------------------------
create table clan_roles (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references users (id) on delete restrict,
  clan_id     uuid not null references clans (id) on delete restrict,
  role        text not null check (role in ('leader', 'co-leader', 'elder', 'member')),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz,
  deleted_at  timestamptz,

  unique (user_id, clan_id)
);

create trigger clan_roles_set_updated_at
  before update on clan_roles
  for each row execute function set_updated_at();

create index clan_roles_user_id_idx on clan_roles (user_id) where deleted_at is null;
create index clan_roles_clan_id_idx on clan_roles (clan_id) where deleted_at is null;

-- ========================================================================
-- 002_cwl.sql
-- ========================================================================

-- T1.5 — Clan War League tables.
--
-- This is the data the whole project exists to capture. Supercell deletes CWL
-- data when the season ends and it cannot ever be re-fetched, so every table
-- here is append-only in practice (R5) and never hard-deleted (R4).

-- ---------------------------------------------------------------------------
-- cwl_seasons — one row per clan per monthly league season.
-- ---------------------------------------------------------------------------
create table cwl_seasons (
  id          uuid primary key default gen_random_uuid(),
  clan_id     uuid not null references clans (id) on delete restrict,
  season      text not null,                  -- 'YYYY-MM', as the API reports it
  league      text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz,
  deleted_at  timestamptz,

  -- Natural key. Re-running the sync finds this row instead of making a second.
  unique (clan_id, season)
);

create trigger cwl_seasons_set_updated_at
  before update on cwl_seasons
  for each row execute function set_updated_at();


-- ---------------------------------------------------------------------------
-- cwl_wars — one war day within a season.
--
-- war_tag is Supercell's own identifier and the real idempotency key: the same
-- war appears under the same tag on every poll for the whole week.
-- ---------------------------------------------------------------------------
create table cwl_wars (
  id                  uuid primary key default gen_random_uuid(),
  season_id           uuid not null references cwl_seasons (id) on delete restrict,
  war_tag             text not null unique,
  day_number          smallint,
  opponent_tag        text,
  opponent_name       text,
  team_size           smallint,
  state               text check (state in ('preparation', 'inWar', 'warEnded')),
  our_stars           smallint,
  their_stars         smallint,
  our_destruction     numeric(5, 2),
  their_destruction   numeric(5, 2),
  result              text check (result in ('win', 'lose', 'tie')),
  start_time          timestamptz,
  end_time            timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz,
  deleted_at          timestamptz,

  constraint cwl_wars_tag_format check (war_tag = upper(war_tag) and war_tag like '#%')
);

create trigger cwl_wars_set_updated_at
  before update on cwl_wars
  for each row execute function set_updated_at();

create index cwl_wars_season_id_idx on cwl_wars (season_id) where deleted_at is null;


-- ---------------------------------------------------------------------------
-- cwl_attacks — the record everything else is built on.
--
-- THE UNIQUE CONSTRAINT BELOW IS THE MOST IMPORTANT LINE IN THIS FILE.
-- It is what makes ON CONFLICT DO NOTHING work (R5). Without it the clause
-- matches nothing, silently, and every sync run duplicates every attack — with
-- no error to notice.
--
-- CWL allows one attack per player per war, so attack_order is always 1 today.
-- It is kept anyway: T1.5 mandates it, and it keeps this table the same shape
-- as war_attacks, where multiple attacks are real.
--
-- Missed attacks are NOT stored. The API simply returns no attack for a player
-- who did not attack; the missed list is derived from roster minus attacks
-- (T4.3). Never insert a zero-star placeholder row to represent a miss.
-- ---------------------------------------------------------------------------
create table cwl_attacks (
  id                 uuid primary key default gen_random_uuid(),
  war_id             uuid not null references cwl_wars (id) on delete restrict,
  player_id          uuid not null references players (id) on delete restrict,
  attack_order       smallint not null default 1,
  stars              smallint not null check (stars between 0 and 3),
  destruction        numeric(5, 2) not null check (destruction between 0 and 100),
  defender_tag       text,
  defender_position  smallint,
  attacked_at        timestamptz,
  created_at         timestamptz not null default now(),
  deleted_at         timestamptz,

  unique (war_id, player_id, attack_order)
);

create index cwl_attacks_war_id_idx on cwl_attacks (war_id) where deleted_at is null;
create index cwl_attacks_player_id_idx on cwl_attacks (player_id) where deleted_at is null;


-- ---------------------------------------------------------------------------
-- cwl_bonuses — who received a bonus medal, and why.
--
-- R11: HUMAN DECISION DATA. No sync job may ever write here. The API does not
-- report bonus medal allocation at all — this exists nowhere but in our system,
-- which is exactly why it needs awarded_by and a note (T4.7).
-- ---------------------------------------------------------------------------
create table cwl_bonuses (
  id          uuid primary key default gen_random_uuid(),
  season_id   uuid not null references cwl_seasons (id) on delete restrict,
  player_id   uuid not null references players (id) on delete restrict,
  awarded_by  uuid not null references users (id) on delete restrict,
  awarded_at  timestamptz not null default now(),
  note        text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz,
  deleted_at  timestamptz,

  unique (season_id, player_id)
);

create trigger cwl_bonuses_set_updated_at
  before update on cwl_bonuses
  for each row execute function set_updated_at();


-- QA: foreign keys are not indexed automatically by PostgreSQL. Every one of
-- these columns is joined on by the CWL pages and the player profile (T3B.4).
create index cwl_bonuses_season_id_idx on cwl_bonuses (season_id) where deleted_at is null;
create index cwl_bonuses_player_id_idx on cwl_bonuses (player_id) where deleted_at is null;

-- ========================================================================
-- 003_war.sql
-- ========================================================================

-- T1.6 — Regular clan war tables.
--
-- R12 — war_targets is THE PLAN. war_attacks is WHAT HAPPENED.
-- They are separate tables and must stay that way. Never write a result into
-- war_targets: showing the gap between the two is the point (T6.5).

-- ---------------------------------------------------------------------------
-- wars — one row per war.
--
-- The API has no war id, so (clan_id, start_time) is the natural key: a clan
-- cannot be in two wars starting at the same instant.
-- ---------------------------------------------------------------------------
create table wars (
  id                 uuid primary key default gen_random_uuid(),
  clan_id            uuid not null references clans (id) on delete restrict,
  opponent_tag       text,
  opponent_name      text,
  team_size          smallint,
  state              text check (state in ('preparation', 'inWar', 'warEnded')),
  our_stars          smallint,
  their_stars        smallint,
  our_destruction    numeric(5, 2),
  their_destruction  numeric(5, 2),
  result             text check (result in ('win', 'lose', 'tie')),
  start_time         timestamptz not null,
  end_time           timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz,
  deleted_at         timestamptz,

  unique (clan_id, start_time)
);

create trigger wars_set_updated_at
  before update on wars
  for each row execute function set_updated_at();

create index wars_clan_id_idx on wars (clan_id) where deleted_at is null;


-- ---------------------------------------------------------------------------
-- war_targets — THE PLAN. Who was told to attack what.
--
-- R11: HUMAN DECISION DATA. scripts/sync/war.ts must never write here.
-- Leadership assigns targets; a member may claim an unassigned one (T6.4).
-- ---------------------------------------------------------------------------
create table war_targets (
  id               uuid primary key default gen_random_uuid(),
  war_id           uuid not null references wars (id) on delete restrict,
  player_id        uuid not null references players (id) on delete restrict,
  target_position  smallint not null,
  note             text,
  assigned_by      uuid references users (id) on delete restrict,
  assigned_at      timestamptz not null default now(),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz,
  deleted_at       timestamptz,

  -- One assignment per player per war. Reassigning updates this row; the change
  -- is recorded in audit_log rather than by inserting a second target.
  unique (war_id, player_id)
);

create trigger war_targets_set_updated_at
  before update on war_targets
  for each row execute function set_updated_at();

create index war_targets_war_id_idx on war_targets (war_id) where deleted_at is null;


-- ---------------------------------------------------------------------------
-- war_attacks — WHAT HAPPENED. Written only by scripts/sync/war.ts (R11).
--
-- Same idempotency constraint as cwl_attacks. Here attack_order genuinely
-- varies: a regular war gives each player two attacks.
-- ---------------------------------------------------------------------------
create table war_attacks (
  id                 uuid primary key default gen_random_uuid(),
  war_id             uuid not null references wars (id) on delete restrict,
  player_id          uuid not null references players (id) on delete restrict,
  attack_order       smallint not null,
  stars              smallint not null check (stars between 0 and 3),
  destruction        numeric(5, 2) not null check (destruction between 0 and 100),
  defender_tag       text,
  defender_position  smallint,
  attacked_at        timestamptz,
  created_at         timestamptz not null default now(),
  deleted_at         timestamptz,

  unique (war_id, player_id, attack_order)
);

create index war_attacks_war_id_idx on war_attacks (war_id) where deleted_at is null;
create index war_attacks_player_id_idx on war_attacks (player_id) where deleted_at is null;


-- QA: unindexed foreign key. The player profile (T3B.4) reads targets by player.
create index war_targets_player_id_idx on war_targets (player_id) where deleted_at is null;

-- ========================================================================
-- 004_features.sql
-- ========================================================================

-- T1.7 — Remaining feature tables: raids, clan games, layouts, announcements,
-- push subscriptions.

-- ---------------------------------------------------------------------------
-- raid_seasons / raid_participants — Clan Capital raid weekends.
--
-- Game facts (R11), written by scripts/sync/raids.ts. The API keeps recent
-- raid history, so unlike CWL a missed run here can still be backfilled.
-- ---------------------------------------------------------------------------
create table raid_seasons (
  id          uuid primary key default gen_random_uuid(),
  clan_id     uuid not null references clans (id) on delete restrict,
  start_time  timestamptz not null,
  end_time    timestamptz,
  total_loot  integer,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz,
  deleted_at  timestamptz,

  unique (clan_id, start_time)
);

create trigger raid_seasons_set_updated_at
  before update on raid_seasons
  for each row execute function set_updated_at();

create table raid_participants (
  id               uuid primary key default gen_random_uuid(),
  raid_season_id   uuid not null references raid_seasons (id) on delete restrict,
  player_id        uuid not null references players (id) on delete restrict,
  attacks_used     smallint,
  loot             integer,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz,
  deleted_at       timestamptz,

  unique (raid_season_id, player_id)
);

create trigger raid_participants_set_updated_at
  before update on raid_participants
  for each row execute function set_updated_at();


-- ---------------------------------------------------------------------------
-- clan_games / clan_games_scores — Clan Games participation.
--
-- The API exposes NO per-season score. points is derived at T7.4 by snapshotting
-- each player's "Games Champion" achievement value at the start and end of the
-- period and taking the difference. Miss the start snapshot and that season's
-- score cannot be reconstructed.
-- ---------------------------------------------------------------------------
create table clan_games (
  id          uuid primary key default gen_random_uuid(),
  clan_id     uuid not null references clans (id) on delete restrict,
  season      text not null,                  -- 'YYYY-MM'
  start_time  timestamptz,
  end_time    timestamptz,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz,
  deleted_at  timestamptz,

  unique (clan_id, season)
);

create trigger clan_games_set_updated_at
  before update on clan_games
  for each row execute function set_updated_at();

create table clan_games_scores (
  id             uuid primary key default gen_random_uuid(),
  clan_games_id  uuid not null references clan_games (id) on delete restrict,
  player_id      uuid not null references players (id) on delete restrict,
  points         integer,
  start_value    integer,                     -- achievement total at period start
  end_value      integer,                     -- and at period end; points is the difference
  created_at     timestamptz not null default now(),
  updated_at     timestamptz,
  deleted_at     timestamptz,

  unique (clan_games_id, player_id)
);

create trigger clan_games_scores_set_updated_at
  before update on clan_games_scores
  for each row execute function set_updated_at();


-- ---------------------------------------------------------------------------
-- base_layouts — the layout library (M7).
--
-- R11: human data. The API provides no layout information of any kind, so every
-- row here is member-supplied. image_url points at Supabase Storage; the file is
-- compressed in the browser before upload (T8.2) to stay inside the 1 GB tier.
-- ---------------------------------------------------------------------------
create table base_layouts (
  id           uuid primary key default gen_random_uuid(),
  clan_id      uuid not null references clans (id) on delete restrict,
  uploaded_by  uuid not null references users (id) on delete restrict,
  th_level     smallint not null,
  layout_type  text not null check (layout_type in ('war', 'farming', 'trophy')),
  copy_link    text not null,
  image_url    text,
  description  text,
  votes        integer not null default 0,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz,
  deleted_at   timestamptz
);

create trigger base_layouts_set_updated_at
  before update on base_layouts
  for each row execute function set_updated_at();

create index base_layouts_clan_id_idx on base_layouts (clan_id) where deleted_at is null;
create index base_layouts_filter_idx on base_layouts (clan_id, th_level, layout_type)
  where deleted_at is null;


-- ---------------------------------------------------------------------------
-- announcements — the notice board (M8).
--
-- body is stored as plain text or restricted markdown and rendered safely.
-- Raw HTML is never rendered (T5.2) — anyone with posting rights would
-- otherwise be able to inject script into every member's browser.
-- ---------------------------------------------------------------------------
create table announcements (
  id          uuid primary key default gen_random_uuid(),
  clan_id     uuid not null references clans (id) on delete restrict,
  author_id   uuid not null references users (id) on delete restrict,
  title       text not null,
  body        text not null,
  pinned      boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz,
  deleted_at  timestamptz
);

create trigger announcements_set_updated_at
  before update on announcements
  for each row execute function set_updated_at();

create index announcements_clan_id_idx on announcements (clan_id, pinned, created_at desc)
  where deleted_at is null;


-- ---------------------------------------------------------------------------
-- push_subscriptions — Web Push endpoints (T5.5).
--
-- endpoint is unique: the browser issues one per installed app per device.
-- When the push service later returns 410 Gone the row is SOFT deleted (R4),
-- never removed.
-- ---------------------------------------------------------------------------
create table push_subscriptions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references users (id) on delete restrict,
  endpoint    text not null unique,
  p256dh      text not null,
  auth        text not null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz,
  deleted_at  timestamptz
);

create trigger push_subscriptions_set_updated_at
  before update on push_subscriptions
  for each row execute function set_updated_at();

create index push_subscriptions_user_id_idx on push_subscriptions (user_id)
  where deleted_at is null;


-- QA: unindexed foreign keys. All of these are read per player or per author by
-- the profile page (T3B.4) and the layout library (T8.4).
create index raid_participants_player_id_idx on raid_participants (player_id) where deleted_at is null;
create index clan_games_scores_player_id_idx on clan_games_scores (player_id) where deleted_at is null;
create index announcements_author_id_idx on announcements (author_id) where deleted_at is null;
create index base_layouts_uploaded_by_idx on base_layouts (uploaded_by) where deleted_at is null;

-- ========================================================================
-- 005_operational.sql
-- ========================================================================

-- T1.8 — Operational tables: sync_log, audit_log.
--
-- Neither table holds game data, but between them they are what stops the two
-- unrecoverable failures: a sync job dying unnoticed during CWL, and nobody
-- being able to say who changed what.

-- ---------------------------------------------------------------------------
-- sync_log — R9. Every job writes here at start and finish.
--
-- Drives the freshness indicator on every page (T4.8) and the failure push
-- alert (T5.8). A job that fails silently during CWL costs a season of data
-- that cannot be re-fetched from anywhere.
--
-- NOTE THE 'skipped' STATUS. R10: notInWar, warEnded, preparation and a missing
-- CWL group are ordinary conditions for most of the month, not failures. They
-- must be recorded as skipped, never as failed — a job that reports failure
-- three weeks out of four trains you to ignore the alerts that matter.
-- ---------------------------------------------------------------------------
create table sync_log (
  id               uuid primary key default gen_random_uuid(),
  job_type         text not null check (job_type in ('clans', 'cwl', 'war', 'raids', 'clan-games', 'backup')),
  clan_id          uuid references clans (id) on delete restrict,  -- null for family-wide jobs
  started_at       timestamptz not null default now(),
  finished_at      timestamptz,
  status           text not null check (status in ('running', 'success', 'skipped', 'failed')),
  skip_reason      text,          -- 'notInWar', 'noCwlGroup', ... when status = 'skipped'
  error            text,          -- R8: never put a player API token in here
  records_written  integer,
  created_at       timestamptz not null default now(),
  deleted_at       timestamptz
);

-- The freshness query is "latest successful run of job X for clan Y", so index
-- for that shape directly.
create index sync_log_freshness_idx
  on sync_log (job_type, clan_id, finished_at desc)
  where status = 'success';

create index sync_log_started_at_idx on sync_log (started_at desc);


-- ---------------------------------------------------------------------------
-- audit_log — R4. Every write is recorded: who, what, when.
--
-- Read by the viewer at T9.6. Without that page this record exists but is
-- invisible, and the protection against a departing member is theoretical.
--
-- before/after are jsonb snapshots of the changed row. Keep them small — store
-- the changed fields, not the entire entity.
--
-- deleted_at is present for consistency with section 4, but NOTHING SHOULD EVER
-- SET IT. An audit log you can quietly remove entries from is not an audit log.
-- ---------------------------------------------------------------------------
create table audit_log (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid references users (id) on delete restrict,
  clan_id     uuid references clans (id) on delete restrict,
  action      text not null,          -- 'create' | 'update' | 'delete' | 'publish' | ...
  entity      text not null,          -- table name, e.g. 'cwl_bonuses'
  entity_id   uuid,
  before      jsonb,
  after       jsonb,
  created_at  timestamptz not null default now(),
  deleted_at  timestamptz
);

create index audit_log_clan_id_idx on audit_log (clan_id, created_at desc);
create index audit_log_user_id_idx on audit_log (user_id, created_at desc);
create index audit_log_entity_idx on audit_log (entity, entity_id);

-- ========================================================================
-- 006_rls.sql
-- ========================================================================

-- T1.9 — Row Level Security.
--
-- READ THIS FILE LINE BY LINE BEFORE APPLYING IT (section 8).
--
-- This is the single most important security control in the system. Three clans
-- share one database, and application code will sometimes forget the clan filter
-- (R3 calls that the most common AI-generated bug in this project). These
-- policies are what stops a forgotten filter becoming a data leak.
--
-- RLS is the safety net, NOT a substitute for filtering by clan in every query.
--
-- Done when: with the anon key and no session, every table returns zero rows.
--
-- A useful property falls out of this design for free: T3.8's approval gate is
-- already enforced. A newly signed-up user has no clan_roles row, so
-- auth_clan_ids() returns the empty set and every policy below matches nothing.
-- A stranger with a verified tag and a valid session sees an empty application,
-- not a populated one — before any application-level gate is written.


-- ---------------------------------------------------------------------------
-- Which clans does the current user belong to?
--
-- security definer is load-bearing. The function reads clan_roles, and
-- clan_roles itself has an RLS policy that calls this function. Running as the
-- definer bypasses RLS inside the function body, which is what stops that
-- becoming infinite recursion.
--
-- set search_path = '' with fully qualified names prevents a search_path
-- hijack, which a security definer function is otherwise exposed to.
-- ---------------------------------------------------------------------------
create or replace function auth_clan_ids()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select clan_id
  from public.clan_roles
  where user_id = auth.uid()
    and deleted_at is null
$$;

-- Same, restricted to clans where the user is the leader. Used by audit_log.
create or replace function auth_leader_clan_ids()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select clan_id
  from public.clan_roles
  where user_id = auth.uid()
    and role = 'leader'
    and deleted_at is null
$$;


-- ---------------------------------------------------------------------------
-- Enable RLS everywhere.
--
-- Enabling RLS with no policy denies everything. Each table below then gets
-- exactly one select policy. That default-deny is deliberate: a table added in
-- a later migration and forgotten here is invisible rather than public.
-- ---------------------------------------------------------------------------
alter table clans              enable row level security;
alter table users              enable row level security;
alter table players            enable row level security;
alter table clan_roles         enable row level security;
alter table cwl_seasons        enable row level security;
alter table cwl_wars           enable row level security;
alter table cwl_attacks        enable row level security;
alter table cwl_bonuses        enable row level security;
alter table wars               enable row level security;
alter table war_targets        enable row level security;
alter table war_attacks        enable row level security;
alter table raid_seasons       enable row level security;
alter table raid_participants  enable row level security;
alter table clan_games         enable row level security;
alter table clan_games_scores  enable row level security;
alter table base_layouts       enable row level security;
alter table announcements      enable row level security;
alter table push_subscriptions enable row level security;
alter table sync_log           enable row level security;
alter table audit_log          enable row level security;


-- ---------------------------------------------------------------------------
-- Direct clan ownership — the table carries clan_id itself.
--
-- Every policy is `to authenticated`, so the anon role matches nothing at all.
-- ---------------------------------------------------------------------------
create policy "read own clans" on clans
  for select to authenticated
  using (id in (select auth_clan_ids()));

create policy "read own clan players" on players
  for select to authenticated
  using (clan_id in (select auth_clan_ids()));

create policy "read own clan roles" on clan_roles
  for select to authenticated
  using (clan_id in (select auth_clan_ids()));

create policy "read own clan cwl seasons" on cwl_seasons
  for select to authenticated
  using (clan_id in (select auth_clan_ids()));

create policy "read own clan wars" on wars
  for select to authenticated
  using (clan_id in (select auth_clan_ids()));

create policy "read own clan raid seasons" on raid_seasons
  for select to authenticated
  using (clan_id in (select auth_clan_ids()));

create policy "read own clan games" on clan_games
  for select to authenticated
  using (clan_id in (select auth_clan_ids()));

create policy "read own clan layouts" on base_layouts
  for select to authenticated
  using (clan_id in (select auth_clan_ids()));

create policy "read own clan announcements" on announcements
  for select to authenticated
  using (clan_id in (select auth_clan_ids()));


-- ---------------------------------------------------------------------------
-- Own row only.
-- ---------------------------------------------------------------------------
-- Own row only, deliberately. Widening this to "anyone in my clan" would expose
-- every member's email address, which is a privacy decision for the clan leader
-- (T0.11), not a convenience for a query.
--
-- KNOWN CONSEQUENCE: pages that display who did something — the author of an
-- announcement (T5.1), who awarded a bonus (T4.7), who published a roster
-- (T4B.9) — cannot resolve that name through this table yet. Prefer joining to
-- players.name, which is the in-game name members recognise anyway and is
-- already readable clan-wide. If a users join really is needed, add a policy
-- exposing id and display_name only, never email.
create policy "read own profile" on users
  for select to authenticated
  using (id = auth.uid());

create policy "read own push subscriptions" on push_subscriptions
  for select to authenticated
  using (user_id = auth.uid());


-- ---------------------------------------------------------------------------
-- Indirect ownership — clan_id is reached through a parent.
--
-- The exists-join pattern from Architecture.md 7.3. Deliberately NOT solved by
-- denormalising clan_id onto every child table: a denormalised copy can drift
-- out of step with its parent, and a policy reading the stale copy would grant
-- access the parent no longer allows.
-- ---------------------------------------------------------------------------
create policy "read own clan cwl wars" on cwl_wars
  for select to authenticated
  using (
    exists (
      select 1 from cwl_seasons s
      where s.id = cwl_wars.season_id
        and s.clan_id in (select auth_clan_ids())
    )
  );

create policy "read own clan cwl attacks" on cwl_attacks
  for select to authenticated
  using (
    exists (
      select 1 from cwl_wars w
      join cwl_seasons s on s.id = w.season_id
      where w.id = cwl_attacks.war_id
        and s.clan_id in (select auth_clan_ids())
    )
  );

create policy "read own clan cwl bonuses" on cwl_bonuses
  for select to authenticated
  using (
    exists (
      select 1 from cwl_seasons s
      where s.id = cwl_bonuses.season_id
        and s.clan_id in (select auth_clan_ids())
    )
  );

create policy "read own clan war targets" on war_targets
  for select to authenticated
  using (
    exists (
      select 1 from wars w
      where w.id = war_targets.war_id
        and w.clan_id in (select auth_clan_ids())
    )
  );

create policy "read own clan war attacks" on war_attacks
  for select to authenticated
  using (
    exists (
      select 1 from wars w
      where w.id = war_attacks.war_id
        and w.clan_id in (select auth_clan_ids())
    )
  );

create policy "read own clan raid participants" on raid_participants
  for select to authenticated
  using (
    exists (
      select 1 from raid_seasons r
      where r.id = raid_participants.raid_season_id
        and r.clan_id in (select auth_clan_ids())
    )
  );

create policy "read own clan games scores" on clan_games_scores
  for select to authenticated
  using (
    exists (
      select 1 from clan_games g
      where g.id = clan_games_scores.clan_games_id
        and g.clan_id in (select auth_clan_ids())
    )
  );


-- ---------------------------------------------------------------------------
-- Operational tables.
-- ---------------------------------------------------------------------------

-- Members need this for the freshness indicator on every page (T4.8).
-- clan_id is null for family-wide jobs, which every authenticated user may see.
create policy "read own clan sync log" on sync_log
  for select to authenticated
  using (clan_id is null or clan_id in (select auth_clan_ids()));

-- T9.6 — the audit log viewer is leader-only. Enforced here as well as in the
-- application, because "who changed what" includes entries about the people
-- reading it.
create policy "leaders read own clan audit log" on audit_log
  for select to authenticated
  using (clan_id in (select auth_leader_clan_ids()));


-- ---------------------------------------------------------------------------
-- Explicit grants.
--
-- Supabase normally handles this through ALTER DEFAULT PRIVILEGES at project
-- creation, so these would usually be redundant. They are stated anyway because
-- the failure mode when they are absent is confusing: RLS policies never even
-- get evaluated, and every query fails with "permission denied for table"
-- rather than returning the empty result you would expect from a policy.
--
-- A grant is not access. RLS still decides which rows come back; this only
-- decides who may ask.
-- ---------------------------------------------------------------------------
grant usage on schema public to anon, authenticated;

grant select on all tables in schema public to anon, authenticated;

grant execute on function auth_clan_ids() to anon, authenticated;
grant execute on function auth_leader_clan_ids() to anon, authenticated;


-- ---------------------------------------------------------------------------
-- No insert, update or delete policies exist, on purpose.
--
-- Every write today comes from scripts/sync/, which uses the service role key
-- and bypasses RLS by design — those jobs act for no user.
--
-- Human writes arrive later (T4.7 bonuses, T5.1 announcements, T8.3 layouts,
-- and all of Phase 4B). Each of those tasks adds its own write policy in its own
-- migration, scoped to the role that is allowed to perform it. Granting a broad
-- write policy here to "save a migration later" would hand every member the
-- ability to edit every human-decision table in their clan.
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 007_member_snapshots.sql
-- ========================================================================

-- T2.9 — member_snapshots.
--
-- Supercell reports donations, trophies and war stars as CUMULATIVE totals that
-- reset monthly. A single reading is therefore meaningless on its own. Taking a
-- snapshot on every sync run and differencing across the season is the only way
-- to derive per-season figures (T3B.3) or to detect inactivity (T3B.5).
--
-- Without this table, the whole of Phase 3B has nothing to display.

create table member_snapshots (
  id                  uuid primary key default gen_random_uuid(),
  clan_id             uuid not null references clans (id) on delete restrict,
  player_id           uuid not null references players (id) on delete restrict,
  captured_at         timestamptz not null default now(),

  donations           integer,
  donations_received  integer,
  trophies            integer,
  war_stars           integer,
  th_level            smallint,
  role                text check (role in ('leader', 'co-leader', 'elder', 'member')),

  created_at          timestamptz not null default now(),
  deleted_at          timestamptz,

  -- ---------------------------------------------------------------------
  -- Resolving a conflict the spec leaves open.
  --
  -- T2.9 says "one row per player per run". R5 says running a job five times
  -- must change nothing after the first. Taken literally those disagree: with
  -- captured_at defaulting to now(), a re-run always inserts a second row.
  --
  -- Bucketing to the hour settles it. The hourly clans sync is idempotent
  -- within its hour, so a manual re-run, a retry, or one of GitHub's duplicate
  -- firings costs nothing.
  --
  -- It also bounds growth: at most 24 rows per player per day, roughly 1.3 M
  -- rows a year for 150 players, which is what keeps this inside the 500 MB
  -- free tier. Without the bucket, a 15-minute cadence would quadruple that.
  --
  -- The `at time zone 'UTC'` is required, not decorative. date_trunc() over a
  -- timestamptz depends on the session TimeZone, so it is not immutable and
  -- PostgreSQL rejects it outright in a generated column. Anchoring to UTC makes
  -- it immutable and gives a bucket that is stable no matter which timezone the
  -- connection happens to be in — which is also what section 4 asks for: stored
  -- UTC, converted only for display.
  -- ---------------------------------------------------------------------
  captured_hour       timestamp generated always as
                        (date_trunc('hour', captured_at at time zone 'UTC')) stored,

  unique (player_id, captured_hour)
);

-- Every profile and trend query is "this player, most recent first" (T3B.4).
create index member_snapshots_player_idx
  on member_snapshots (player_id, captured_at desc)
  where deleted_at is null;

-- The directory reads a whole clan at one point in time (T3B.2).
create index member_snapshots_clan_idx
  on member_snapshots (clan_id, captured_at desc)
  where deleted_at is null;


-- ---------------------------------------------------------------------------
-- RLS. A table added without this is invisible in the catalogue check but wide
-- open in production, so it goes in the same migration as the table itself.
-- ---------------------------------------------------------------------------
alter table member_snapshots enable row level security;

create policy "read own clan member snapshots" on member_snapshots
  for select to authenticated
  using (clan_id in (select auth_clan_ids()));

grant select on member_snapshots to anon, authenticated;

-- ========================================================================
-- 008_player_left_at.sql
-- ========================================================================

-- T3.9 — players.left_at.
--
-- Players move between the three clans, and some leave entirely. Neither event
-- may lose history: a member's CWL record belongs to the clan family regardless
-- of where they are now, and R4 means the row is never deleted.
--
-- Two distinct states, and conflating them is the bug to avoid:
--
--   moved between our clans  -> players.clan_id changes, left_at stays null.
--                               All history stays attached to the PLAYER, not
--                               the clan, so nothing needs rewriting.
--
--   left all three clans     -> left_at is set, clan_id is left as it was.
--                               The row and every attack, snapshot and bonus
--                               survive. Access is revoked by left_at, not by
--                               removing anything.
--
-- A returning member is simply left_at = null again, with their whole history
-- intact and their original row reused — which is why players.tag is unique.

alter table players
  add column left_at timestamptz;

comment on column players.left_at is
  'Set when the player is in none of the three clans. Never delete the row (R4) '
  '- their history is part of the clan family record. Null again if they return.';

-- The member directory and every sync read filters on "still here", so index for
-- that shape rather than the whole table.
create index players_active_idx
  on players (clan_id)
  where deleted_at is null and left_at is null;

-- T3B.5 needs the opposite view: who has gone, and when.
create index players_left_idx
  on players (left_at desc)
  where left_at is not null;

-- ========================================================================
-- 010_polls.sql
-- ========================================================================

-- T4B.1 — Poll tables
--
-- NOTE: 009 is intentionally absent. It held cwl_signups from the superseded
-- T4.9, which Phase 4B replaced with polls + rosters. Nothing was ever applied.
--
-- R11 — HUMAN DECISION DATA. Written only by people through the application.
-- No sync job may ever write to these tables. A 2 AM job that touches them
-- silently erases an hour of the leader's work, and R4 means there is no deleted
-- row to recover.
--
-- scripts/sync/shared.ts lists all three tables in its "MUST NEVER WRITE" block.


-- ---------------------------------------------------------------------------
-- Leadership, as a set of clan ids.
--
-- 006 gave us auth_clan_ids() (any role) and auth_leader_clan_ids() (leader
-- only). Polls need the band between them: a co-leader may open a poll and read
-- who answered, an elder may not. Adding it here rather than widening
-- auth_leader_clan_ids(), because that function guards audit_log and quietly
-- letting co-leaders read the audit trail would be a different decision made by
-- accident.
-- ---------------------------------------------------------------------------
create or replace function auth_leadership_clan_ids()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select clan_id
  from public.clan_roles
  where user_id = auth.uid()
    and role in ('leader', 'co-leader')
    and deleted_at is null
$$;

grant execute on function auth_leadership_clan_ids() to anon, authenticated;

comment on function auth_leadership_clan_ids() is
  'Clans where the caller is leader or co-leader. Distinct from '
  'auth_leader_clan_ids(), which guards audit_log and stays leader-only.';


-- ---------------------------------------------------------------------------
-- polls
--
-- `scope` is the whole reason this table is not just clan_id.
--
--   'clan'    one clan answers. War availability, a question for one roster.
--   'family'  every clan answers at once, and clan_id is NULL.
--
-- A CWL availability poll is 'family': the leader is choosing across all clans
-- together (T4B.7), so asking each clan separately would produce three lists
-- that have to be merged by hand — which is the spreadsheet this project exists
-- to delete.
-- ---------------------------------------------------------------------------
create table polls (
  id          uuid primary key default gen_random_uuid(),
  scope       text not null check (scope in ('clan', 'family')),
  clan_id     uuid references clans (id) on delete restrict,
  season      text,
  poll_type   text not null
              check (poll_type in ('cwl_availability', 'war_availability', 'general')),
  title       text not null,
  question    text,
  opens_at    timestamptz,
  closes_at   timestamptz,
  status      text not null default 'open'
              check (status in ('draft', 'open', 'closed')),
  created_by  uuid not null references users (id) on delete restrict,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz,
  deleted_at  timestamptz,

  -- The pairing that makes `scope` mean something. A 'clan' poll with no clan is
  -- unanswerable; a 'family' poll with one is a lie about who it is for, and
  -- both would slip past a policy that only reads clan_id.
  constraint polls_scope_clan check (
    (scope = 'clan'   and clan_id is not null) or
    (scope = 'family' and clan_id is null)
  )
);

create index polls_clan_id_idx on polls (clan_id, created_at desc) where deleted_at is null;
create index polls_open_idx on polls (status, closes_at) where deleted_at is null;

create trigger polls_set_updated_at
  before update on polls
  for each row execute function set_updated_at();


create table poll_options (
  id          uuid primary key default gen_random_uuid(),
  poll_id     uuid not null references polls (id) on delete restrict,
  label       text not null,
  sort_order  smallint not null default 0,
  created_at  timestamptz not null default now(),
  deleted_at  timestamptz,

  -- Two options reading "Maybe" on one poll is a data-entry slip that makes the
  -- result meaningless and cannot be spotted in a bar chart.
  unique (poll_id, label)
);

create index poll_options_poll_id_idx on poll_options (poll_id, sort_order)
  where deleted_at is null;


-- ---------------------------------------------------------------------------
-- poll_responses
--
-- Answers belong to a PLAYER, not a user. A member may own more than one Clash
-- account (Architecture.md 7.1), and CWL availability is a question about a
-- village — "can this account play" — not about a person.
--
-- updated_at is kept deliberately: a leader building a roster needs to see that
-- someone flipped from In to Out an hour before the deadline, which is invisible
-- if the edit overwrites silently (T4B.3).
-- ---------------------------------------------------------------------------
create table poll_responses (
  id            uuid primary key default gen_random_uuid(),
  poll_id       uuid not null references polls (id) on delete restrict,
  player_id     uuid not null references players (id) on delete restrict,
  option_id     uuid not null references poll_options (id) on delete restrict,
  note          text,
  responded_at  timestamptz not null default now(),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz,
  deleted_at    timestamptz,

  -- One answer per player, editable until the poll closes.
  unique (poll_id, player_id)
);

create index poll_responses_poll_id_idx on poll_responses (poll_id)
  where deleted_at is null;
create index poll_responses_player_id_idx on poll_responses (player_id)
  where deleted_at is null;

create trigger poll_responses_set_updated_at
  before update on poll_responses
  for each row execute function set_updated_at();


-- ---------------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------------
alter table polls          enable row level security;
alter table poll_options   enable row level security;
alter table poll_responses enable row level security;

-- A family poll is visible to anyone in any clan; a clan poll only to that clan.
create policy "read visible polls" on polls
  for select to authenticated
  using (
    (scope = 'family' and exists (select 1 from auth_clan_ids()))
    or clan_id in (select auth_clan_ids())
  );

create policy "leadership creates polls" on polls
  for insert to authenticated
  with check (
    created_by = auth.uid()
    and (
      (scope = 'clan' and clan_id in (select auth_leadership_clan_ids()))
      -- A family poll spans every clan, so leadership anywhere may open one.
      or (scope = 'family' and exists (select 1 from auth_leadership_clan_ids()))
    )
  );

create policy "leadership updates polls" on polls
  for update to authenticated
  using (
    (scope = 'clan' and clan_id in (select auth_leadership_clan_ids()))
    or (scope = 'family' and exists (select 1 from auth_leadership_clan_ids()))
  );

create policy "read options of visible polls" on poll_options
  for select to authenticated
  using (exists (select 1 from polls p where p.id = poll_options.poll_id));

create policy "leadership writes options" on poll_options
  for insert to authenticated
  with check (
    exists (
      select 1 from polls p
      where p.id = poll_options.poll_id
        and ((p.scope = 'clan' and p.clan_id in (select auth_leadership_clan_ids()))
             or (p.scope = 'family' and exists (select 1 from auth_leadership_clan_ids())))
    )
  );

-- ── The rule T4B.4 states: "Members see counts; leadership sees names." ──
--
-- Enforced here rather than by hiding a column in the UI, because a member with
-- the anon key and a REST client is not looking at the UI. A member reads their
-- OWN answers; leadership of the poll's clan reads everyone's. Counts for
-- everybody else come from poll_option_counts() below, which aggregates inside a
-- definer function and so never exposes a row.
create policy "read own or led responses" on poll_responses
  for select to authenticated
  using (
    player_id in (select id from players where user_id = auth.uid())
    or exists (
      select 1 from polls p
      where p.id = poll_responses.poll_id
        and ((p.scope = 'clan' and p.clan_id in (select auth_leadership_clan_ids()))
             or (p.scope = 'family' and exists (select 1 from auth_leadership_clan_ids())))
    )
  );

-- You answer for a player you have verified as yours, and only while the poll is
-- open. The closes_at check lives in the policy, not the form: a closed poll that
-- can still be edited by a crafted request is a poll whose result is not final.
create policy "answer for your own player" on poll_responses
  for insert to authenticated
  with check (
    player_id in (select id from players where user_id = auth.uid() and deleted_at is null)
    and exists (
      select 1 from polls p
      where p.id = poll_responses.poll_id
        and p.status = 'open'
        and (p.closes_at is null or p.closes_at > now())
    )
  );

create policy "change your own answer" on poll_responses
  for update to authenticated
  using (
    player_id in (select id from players where user_id = auth.uid() and deleted_at is null)
    and exists (
      select 1 from polls p
      where p.id = poll_responses.poll_id
        and p.status = 'open'
        and (p.closes_at is null or p.closes_at > now())
    )
  )
  with check (
    player_id in (select id from players where user_id = auth.uid() and deleted_at is null)
  );


-- ---------------------------------------------------------------------------
-- poll_option_counts — the aggregate a member is allowed to see.
--
-- Definer, so it reads past the row-level policy above and returns only totals.
-- The caller still has to be able to see the poll itself, checked explicitly:
-- without that this would happily count a poll belonging to a clan they are not
-- in, which is the shape of leak R3 exists to prevent.
-- ---------------------------------------------------------------------------
create or replace function poll_option_counts(p_poll uuid)
returns table (option_id uuid, label text, sort_order smallint, votes bigint)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.polls p
    where p.id = p_poll
      and p.deleted_at is null
      and ((p.scope = 'family' and exists (select 1 from public.auth_clan_ids()))
           or p.clan_id in (select public.auth_clan_ids()))
  ) then
    return;
  end if;

  return query
    select o.id, o.label, o.sort_order, count(r.id)
    from public.poll_options o
    left join public.poll_responses r
      on r.option_id = o.id and r.deleted_at is null
    where o.poll_id = p_poll
      and o.deleted_at is null
    group by o.id, o.label, o.sort_order
    order by o.sort_order, o.label;
end;
$$;

revoke execute on function poll_option_counts(uuid) from public;
grant execute on function poll_option_counts(uuid) to authenticated;


grant select on polls, poll_options, poll_responses to anon, authenticated;
grant insert, update on polls, poll_options, poll_responses to authenticated;
grant select, insert, update on polls, poll_options, poll_responses to service_role;

-- No delete grant, for anybody. R4.

-- ========================================================================
-- 011_cwl_rosters.sql
-- ========================================================================

-- T4B.6 — CWL roster tables. THE PLAN.
--
-- R12 — this is who the LEADER CHOSE. cwl_war_members (019) is who the API said
-- actually played. Both are kept, and the difference between them is T4B.11:
-- selected and played / selected but absent / played but never selected.
--
-- Never overwrite one with the other. The tempting "cleanup" — reconciling the
-- roster against what the API reported so there is one list instead of two —
-- deletes the only record of who was picked and did not show up, and R4 means
-- there is no deleted row to recover.
--
-- R11 — HUMAN DECISION DATA. scripts/sync/shared.ts lists both tables in its
-- "MUST NEVER WRITE" block. A sync job that touches these erases the leader's
-- work at 2 AM.


-- ---------------------------------------------------------------------------
-- cwl_rosters — one per clan per season.
--
-- Saved continuously as 'draft'. The leader will not finish this in one sitting:
-- they are cross-referencing poll answers, hero levels and last season's
-- performance for thirty-odd players, and an unsaved form that loses that to a
-- closed tab is a form nobody uses twice.
-- ---------------------------------------------------------------------------
create table cwl_rosters (
  id            uuid primary key default gen_random_uuid(),
  season        text not null,
  clan_id       uuid not null references clans (id) on delete restrict,
  status        text not null default 'draft' check (status in ('draft', 'published')),
  slot_count    smallint not null default 15 check (slot_count in (15, 30)),
  created_by    uuid not null references users (id) on delete restrict,
  published_at  timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz,
  deleted_at    timestamptz,

  unique (clan_id, season)
);

create index cwl_rosters_season_idx on cwl_rosters (season) where deleted_at is null;

create trigger cwl_rosters_set_updated_at
  before update on cwl_rosters
  for each row execute function set_updated_at();


create table cwl_roster_members (
  id         uuid primary key default gen_random_uuid(),
  roster_id  uuid not null references cwl_rosters (id) on delete restrict,
  player_id  uuid not null references players (id) on delete restrict,
  position   smallint,
  added_by   uuid not null references users (id) on delete restrict,
  added_at   timestamptz not null default now(),
  created_at timestamptz not null default now(),
  deleted_at timestamptz,

  unique (roster_id, player_id)
);

create index cwl_roster_members_roster_id_idx on cwl_roster_members (roster_id)
  where deleted_at is null;
create index cwl_roster_members_player_id_idx on cwl_roster_members (player_id)
  where deleted_at is null;


-- ---------------------------------------------------------------------------
-- THE CONSTRAINT THAT MATTERS: no player in two clans' rosters in one season.
--
-- The spec is explicit that this belongs in the database and not only in the
-- form: "otherwise the leader double-books someone and does not find out until
-- CWL has already started." By then the roster is locked in game and one of the
-- two clans is a player short for the whole week.
--
-- A unique constraint cannot express it, because the season lives on the parent
-- table — so it is a trigger. Deliberately NOT a unique index on a denormalised
-- season column copied onto the child: that column would then need keeping in
-- step with the parent forever, and the first UPDATE that forgot would silently
-- switch the guard off.
--
-- Soft-deleted rows are ignored, so removing a player from clan A's roster and
-- adding them to clan B's works exactly as the leader expects.
-- ---------------------------------------------------------------------------
create or replace function guard_one_roster_per_season()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_season   text;
  v_clash    text;
begin
  if new.deleted_at is not null then
    return new;
  end if;

  select season into v_season
  from public.cwl_rosters
  where id = new.roster_id;

  select c.name into v_clash
  from public.cwl_roster_members m
  join public.cwl_rosters r on r.id = m.roster_id
  join public.clans c on c.id = r.clan_id
  where m.player_id = new.player_id
    and m.deleted_at is null
    and r.deleted_at is null
    and r.season = v_season
    and m.roster_id <> new.roster_id
  limit 1;

  if v_clash is not null then
    raise exception
      'player is already in the % roster for season %', v_clash, v_season
      using errcode = 'unique_violation';
  end if;

  return new;
end;
$$;

create trigger cwl_roster_members_one_per_season
  before insert or update on cwl_roster_members
  for each row execute function guard_one_roster_per_season();


-- ---------------------------------------------------------------------------
-- RLS
--
-- Members may read a PUBLISHED roster (T4B.10) and nothing else. A draft is the
-- leader thinking out loud — half-built, with people on it who will be cut — and
-- showing that to the clan causes exactly the arguments publishing exists to
-- prevent.
-- ---------------------------------------------------------------------------
alter table cwl_rosters        enable row level security;
alter table cwl_roster_members enable row level security;

create policy "read published rosters, or drafts if leadership" on cwl_rosters
  for select to authenticated
  using (
    (status = 'published' and clan_id in (select auth_clan_ids()))
    or clan_id in (select auth_leadership_clan_ids())
  );

-- Cross-clan by design (T4B.7): the leader assigns players across all three
-- clans in one sitting, so leadership of ANY clan may build a roster for a clan
-- they lead. A leader of clan A cannot build clan B's roster unless they also
-- lead clan B.
create policy "leadership creates rosters" on cwl_rosters
  for insert to authenticated
  with check (
    created_by = auth.uid()
    and clan_id in (select auth_leadership_clan_ids())
  );

create policy "leadership updates rosters" on cwl_rosters
  for update to authenticated
  using (clan_id in (select auth_leadership_clan_ids()))
  with check (clan_id in (select auth_leadership_clan_ids()));

create policy "read members of visible rosters" on cwl_roster_members
  for select to authenticated
  using (exists (select 1 from cwl_rosters r where r.id = cwl_roster_members.roster_id));

create policy "leadership adds roster members" on cwl_roster_members
  for insert to authenticated
  with check (
    added_by = auth.uid()
    and exists (
      select 1 from cwl_rosters r
      where r.id = cwl_roster_members.roster_id
        and r.clan_id in (select auth_leadership_clan_ids())
    )
  );

-- Update rather than delete: dropping someone sets deleted_at (R4), so the fact
-- that they were once selected survives. Members ask when they were dropped, and
-- the answer should not depend on anyone's memory.
create policy "leadership changes roster members" on cwl_roster_members
  for update to authenticated
  using (
    exists (
      select 1 from cwl_rosters r
      where r.id = cwl_roster_members.roster_id
        and r.clan_id in (select auth_leadership_clan_ids())
    )
  );


grant select on cwl_rosters, cwl_roster_members to anon, authenticated;
grant insert, update on cwl_rosters, cwl_roster_members to authenticated;
grant select, insert, update on cwl_rosters, cwl_roster_members to service_role;

-- No delete grant, for anybody. R4.


-- ---------------------------------------------------------------------------
-- Verify:
--
--   -- the double-booking guard, which is the point of this file
--   insert into cwl_roster_members (roster_id, player_id, added_by)
--   values ('<clan B roster, same season>', '<player already in clan A>', '<you>');
--     -- expect: ERROR  player is already in the <Clan A> roster for season 2026-08
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 013_user_status.sql
-- ========================================================================

-- T3.8 — Account approval gate.
--
-- Magic-link signup means anyone with an email address can create an account.
-- Verification (T3.3) proves someone owns *a* Clash of Clans account, not that
-- they belong to *these three clans*. Those are different claims, and only the
-- second one should grant access.
--
-- Numbering: 009 is deliberately absent (it held cwl_signups from the superseded
-- T4.9), and 010-012 are taken by Phase 4B and T6.8. Hence 013.

alter table users
  add column status text not null default 'pending'
    check (status in ('pending', 'approved', 'rejected')),

  -- Which clan this person is asking to join.
  --
  -- Without this, T3.8's "a leader approves them manually" has no secure list to
  -- work from: a pending user has no clan_roles row, so there is no clan scope to
  -- filter on, and the only alternative is letting every leader read every
  -- pending account in the system. Set at verification time from the clan the
  -- verified player tag actually belongs to.
  add column requested_clan_id uuid references clans (id) on delete restrict,

  add column approved_by uuid references users (id) on delete restrict,
  add column approved_at timestamptz;

comment on column users.status is
  'pending until their verified player tag matches a current member of one of the '
  'three clans, or a leader approves them. Access is governed by clan_roles; this '
  'column is what the approval UI reads.';

create index users_pending_idx
  on users (requested_clan_id, created_at)
  where status = 'pending' and deleted_at is null;


-- ---------------------------------------------------------------------------
-- Leaders can see who is waiting for them — and only for their own clans.
--
-- The existing "read own profile" policy stays. This is additive: RLS combines
-- multiple SELECT policies with OR, so a user still reads their own row, and a
-- leader additionally reads pending applicants to clans they lead.
--
-- Scoped to auth_leader_clan_ids(), not auth_clan_ids(): an elder should not be
-- reading strangers' email addresses.
-- ---------------------------------------------------------------------------
create policy "leaders read pending applicants to their clans" on users
  for select to authenticated
  using (
    status = 'pending'
    and requested_clan_id in (select auth_leader_clan_ids())
  );


-- ---------------------------------------------------------------------------
-- Note on what is NOT here.
--
-- No UPDATE policy. Approval is a privileged write, and it happens through a
-- route handler that has already called requireRole(clanId, 'leader') and
-- written to audit_log (R4). Granting members a broad update on users would let
-- anyone approve themselves, which is the entire thing this migration prevents.
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 014_service_role_grants.sql
-- ========================================================================

-- Fix forward for a defect in 006_rls.sql.
--
-- 006 granted select to `anon` and `authenticated` but never granted anything to
-- `service_role`. Every sync job uses the service key, so `npm run sync:clans`
-- failed on its first contact with real Supabase:
--
--   42501  permission denied for table clans
--
-- 006 has been applied, so per section 4 it is not edited — this migration
-- corrects it.
--
-- Why PGlite never caught it: the test harness connects as superuser and only
-- switches role to `anon` or `authenticated` to exercise RLS. It never acted as
-- `service_role`, so the missing grant was invisible. That is the limitation of a
-- stand-in, stated plainly in test/pg-harness.ts, showing up in practice.

grant usage on schema public to service_role;


-- ---------------------------------------------------------------------------
-- SELECT, INSERT, UPDATE — and deliberately NOT DELETE.
--
-- R4 says nothing is ever deleted: no DELETE statements, soft delete only,
-- because destroyed CWL history cannot be re-fetched from anywhere. Withholding
-- the privilege turns that rule from a convention the code must remember into
-- something the database enforces.
--
-- If a sync job ever tries a hard delete it now fails loudly with a permission
-- error, which is exactly the outcome R4 wants. Should a genuine need for a hard
-- delete appear, it should require a deliberate new migration and a reason —
-- never be available by default to a job that runs unattended every hour.
-- ---------------------------------------------------------------------------
grant select, insert, update on all tables in schema public to service_role;

-- Tables added by later migrations must inherit the same privileges, or the next
-- feature reintroduces this exact bug.
alter default privileges in schema public
  grant select, insert, update on tables to service_role;

alter default privileges in schema public
  grant select on tables to anon, authenticated;


-- ---------------------------------------------------------------------------
-- Sanity check after applying. Run this and confirm delete is absent:
--
--   select grantee, string_agg(privilege_type, ', ' order by privilege_type)
--   from information_schema.role_table_grants
--   where table_schema = 'public' and table_name = 'clans'
--   group by grantee;
--
-- Expect service_role to show INSERT, SELECT, UPDATE — and no DELETE.
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 015_platform_admin.sql
-- ========================================================================

-- Leader-managed clans, replacing T1.10's hardcoded seed.
--
-- The spec treats clan tags as configuration: seed.sql inserts three rows, and a
-- fourth clan needs a migration. This makes them data the leader owns — added
-- through the admin UI, validated by lib/tags.ts, with sync filling in name,
-- badge and level afterwards.
--
-- That split respects R11: the leader supplies the TAG (a human decision, and one
-- no sync job may invent), while everything else about a clan is a game fact.
--
-- The bootstrap problem it creates:
--
--   seeing anything -> needs a clan_roles row
--   clan_roles      -> needs a clan to exist
--   a clan          -> needs a leader to add it
--   a leader        -> needs to see something
--
-- Clan-scoped roles cannot express "may create the first clan", so exactly one
-- platform-level capability is introduced. Deliberately one flag and nothing more:
-- every other permission in this system stays per clan.

alter table users
  add column is_platform_admin boolean not null default false;

comment on column users.is_platform_admin is
  'May add clans and approve accounts that belong to no clan yet. Exists only to '
  'break the bootstrap cycle - every other permission is per clan (T3.5).';

-- At most one platform admin. Not a technical requirement; it makes the blast
-- radius of this flag explicit, and a second one should be a deliberate act.
create unique index users_single_platform_admin
  on users ((true))
  where is_platform_admin and deleted_at is null;


-- ---------------------------------------------------------------------------
-- security definer, and for the usual reason: the policies below sit ON users,
-- so a policy reading users directly would recurse. Running as definer bypasses
-- RLS inside the body and breaks the cycle.
-- ---------------------------------------------------------------------------
create or replace function auth_is_platform_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select is_platform_admin
     from public.users
     where id = auth.uid() and deleted_at is null),
    false)
$$;

grant execute on function auth_is_platform_admin() to anon, authenticated;


-- ---------------------------------------------------------------------------
-- Ownership claim.
--
-- The bootstrap cannot be done from application code alone: promoting yourself
-- requires a write that no policy grants, and granting that policy would let
-- anyone promote themselves.
--
-- So it is a definer function with one condition that can only ever be true
-- once: it promotes the caller ONLY IF the platform currently has no admin. The
-- first person through the door can claim it; nobody after them can, and there
-- is no argument to tamper with.
--
-- The application adds a second, independent check — the caller's email must
-- match OWNER_EMAIL — so a stranger reaching the URL first still cannot claim it.
-- ---------------------------------------------------------------------------
create or replace function claim_platform_ownership()
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  existing integer;
begin
  if auth.uid() is null then
    return false;
  end if;

  select count(*) into existing
  from public.users
  where is_platform_admin and deleted_at is null;

  if existing > 0 then
    return false;
  end if;

  -- Signal the guard trigger that this write is the sanctioned bootstrap.
  --
  -- The trigger is `security invoker`, so inside this definer function it still
  -- runs as the calling user and would otherwise block the very write it exists
  -- to protect. A transaction-local GUC is the signal: `true` scopes it to this
  -- transaction, so it cannot leak into any later statement, and no client can
  -- set it usefully because reaching the update at all requires this function.
  perform set_config('clanbridge.bootstrap', 'on', true);

  update public.users
  set is_platform_admin = true,
      status = 'approved',
      approved_at = now()
  where id = auth.uid();

  insert into public.audit_log (user_id, action, entity, entity_id, after)
  values (auth.uid(), 'claim-ownership', 'users', auth.uid(),
          jsonb_build_object('is_platform_admin', true));

  return true;
end;
$$;

-- Postgres grants EXECUTE on new functions to PUBLIC by default, so granting to
-- `authenticated` alone would still leave anon able to call this. It would return
-- false for them (auth.uid() is null), but an unauthenticated caller should not
-- be able to reach the ownership claim at all.
revoke execute on function claim_platform_ownership() from public;
grant execute on function claim_platform_ownership() to authenticated;


-- ---------------------------------------------------------------------------
-- Privileges for the writes below.
--
-- A GRANT and a POLICY are different gates and both are required: the grant says
-- whether the role may attempt the statement at all, the policy says which rows
-- it may touch. 006 granted only SELECT to authenticated, so without this every
-- policy below would be unreachable behind "permission denied for table".
--
-- That is the same defect 014 fixed for service_role, in a different place. It
-- surfaced here only because these are the first write policies in the project.
--
-- Granted narrowly — three tables, no DELETE anywhere (R4). Each future feature
-- grants what it needs rather than inheriting a blanket permission.
-- ---------------------------------------------------------------------------
grant insert, update on clans      to authenticated;
grant insert, update on clan_roles to authenticated;
grant insert, update on users      to authenticated;


-- ---------------------------------------------------------------------------
-- Write policies.
--
-- 006 shipped select-only on purpose, so each feature adds its own writes scoped
-- to the role permitted to perform them. These are the first.
-- ---------------------------------------------------------------------------

-- Adding a clan. INSERT uses `with check`, not `using`.
create policy "platform admin adds clans" on clans
  for insert to authenticated
  with check (auth_is_platform_admin());

-- Renaming or deactivating a clan. Sync also updates clans, but it uses the
-- service key and bypasses RLS entirely.
create policy "platform admin updates clans" on clans
  for update to authenticated
  using (auth_is_platform_admin())
  with check (auth_is_platform_admin());

-- The platform admin must see every clan, including one just created before any
-- clan_roles row exists for it.
create policy "platform admin reads all clans" on clans
  for select to authenticated
  using (auth_is_platform_admin());

-- Granting a role: the platform admin, or a leader of that clan.
create policy "admin or leader grants roles" on clan_roles
  for insert to authenticated
  with check (
    auth_is_platform_admin()
    or clan_id in (select auth_leader_clan_ids())
  );

create policy "admin or leader changes roles" on clan_roles
  for update to authenticated
  using (
    auth_is_platform_admin()
    or clan_id in (select auth_leader_clan_ids())
  )
  with check (
    auth_is_platform_admin()
    or clan_id in (select auth_leader_clan_ids())
  );

create policy "platform admin reads all roles" on clan_roles
  for select to authenticated
  using (auth_is_platform_admin());

-- T3.8 — approving an account. A leader may approve applicants to their own clan;
-- the platform admin may approve anyone, including someone with no clan yet.
--
-- Note what this does NOT allow: promoting anyone to platform admin. That column
-- is only ever written by claim_platform_ownership(), which can fire once.
-- Approving an account is a FUNCTION, not a policy.
--
-- It was first written as an RLS update policy, and that was the wrong tool.
-- Approval is a privileged operation that must also write audit_log (R4), so
-- expressing it as "which rows may this role write" splits one indivisible act
-- into a permission check and a separate, forgettable audit insert.
--
-- As a definer function it is atomic, always audited, and the authority check
-- lives in one readable place instead of a WITH CHECK expression. It also
-- matches claim_platform_ownership() above, so every privileged write in this
-- schema works the same way.
--
-- Consequence: users has NO general update policy. A member may edit their own
-- row (below), and nothing else about a user is writable from a session.
create or replace function approve_account(target uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_clan   uuid;
  target_status text;
  allowed       boolean;
begin
  if auth.uid() is null or target is null then
    return false;
  end if;

  select requested_clan_id, status into target_clan, target_status
  from public.users
  where id = target and deleted_at is null;

  if not found or target_status <> 'pending' then
    return false;
  end if;

  -- Nobody approves themselves, regardless of rank.
  if target = auth.uid() then
    raise exception 'accounts cannot approve themselves';
  end if;

  allowed := public.auth_is_platform_admin()
    or (target_clan is not null
        and target_clan in (select public.auth_leader_clan_ids()));

  if not allowed then
    return false;
  end if;

  perform set_config('clanbridge.bootstrap', 'on', true);

  update public.users
  set status      = 'approved',
      approved_by = auth.uid(),
      approved_at = now()
  where id = target;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), target_clan, 'approve', 'users', target,
          jsonb_build_object('status', 'approved'));

  return true;
end;
$$;

revoke execute on function approve_account(uuid) from public;
grant execute on function approve_account(uuid) to authenticated;

-- The mirror image, so a rejection is recorded rather than left pending forever.
create or replace function reject_account(target uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_clan uuid;
  allowed     boolean;
begin
  if auth.uid() is null or target is null or target = auth.uid() then
    return false;
  end if;

  select requested_clan_id into target_clan
  from public.users where id = target and deleted_at is null;

  if not found then
    return false;
  end if;

  allowed := public.auth_is_platform_admin()
    or (target_clan is not null
        and target_clan in (select public.auth_leader_clan_ids()));

  if not allowed then
    return false;
  end if;

  perform set_config('clanbridge.bootstrap', 'on', true);

  update public.users set status = 'rejected' where id = target;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), target_clan, 'reject', 'users', target,
          jsonb_build_object('status', 'rejected'));

  return true;
end;
$$;

revoke execute on function reject_account(uuid) from public;
grant execute on function reject_account(uuid) to authenticated;

create policy "platform admin reads all users" on users
  for select to authenticated
  using (auth_is_platform_admin());

-- Everyone may create and maintain their own profile row on first sign-in.
create policy "own profile insert" on users
  for insert to authenticated
  with check (id = auth.uid());

-- Own row only, for a display name. Status and is_platform_admin are blocked by
-- the trigger below, so this cannot become a route to privilege.
create policy "own profile update" on users
  for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());


-- ---------------------------------------------------------------------------
-- Guard against the obvious escalation.
--
-- "own profile update" lets a member edit their own row, which would otherwise
-- let them set is_platform_admin or status themselves. A trigger blocks both
-- unless the write comes from a definer function or the service key.
-- ---------------------------------------------------------------------------
create or replace function guard_user_privilege_columns()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  -- Constrain END-USER SESSIONS only.
  --
  -- Deliberately an allow-list of the two untrusted roles rather than a
  -- deny-list of trusted ones. Everything else — service_role for sync jobs,
  -- postgres for migrations and admin tooling — is already privileged by other
  -- means, and an earlier version that tested `role = 'service_role'` blocked
  -- the migration runner itself.
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  -- The definer functions above set this transaction-locally before their
  -- update. Nothing else sets it, and each function checks the caller's
  -- authority before doing so.
  if current_setting('clanbridge.bootstrap', true) = 'on' then
    return new;
  end if;

  if new.is_platform_admin is distinct from old.is_platform_admin then
    raise exception 'is_platform_admin cannot be set directly';
  end if;

  -- status is only ever changed by approve_account() / reject_account(), which
  -- set the bootstrap GUC above. A direct session write is always refused,
  -- including a member trying to approve themselves.
  if new.status is distinct from old.status then
    raise exception 'status is set by approve_account()/reject_account(), not directly';
  end if;

  return new;
end;
$$;

create trigger users_guard_privilege_columns
  before update on users
  for each row execute function guard_user_privilege_columns();

-- ========================================================================
-- 016_player_verification.sql
-- ========================================================================

-- T3.3 — Player verification: link a verified Clash of Clans account to a user.
--
-- WHY THIS IS A FUNCTION AND NOT A POLICY
--
-- `players` has exactly one policy — "read own clan players" (006) — and exactly
-- one grant: select. 015 handed `insert, update` to authenticated on clans,
-- clan_roles and users, and deliberately not on players. That is correct and
-- stays correct: players is a GAME FACT table (R11), owned by scripts/sync/, and
-- a session must never be able to write a player's name, clan or town hall.
--
-- But verification has to write two columns of it. So the write happens here, in
-- a security definer function that is the ONLY path, rather than by opening the
-- table up with an update policy and trusting a WITH CHECK expression to keep a
-- session away from the other columns.
--
-- This is the same reasoning 015 records at lines 199-207 for approve_account(),
-- and the same shape: authority check, then the write, then audit_log, all in one
-- indivisible act that cannot be half-performed.
--
-- R8 — the member's in-game API token never reaches this file. It is verified
-- against Supercell in /api/verify and discarded there. Nothing about it is a
-- parameter here; by the time this runs, ownership is already proven.


-- ---------------------------------------------------------------------------
-- link_verified_player(p_tag)
--
-- Called by /api/verify AFTER Supercell's verifytoken endpoint returned ok.
--
-- Returns jsonb rather than boolean because the caller needs to tell three
-- different outcomes apart in the UI, and a bare false cannot:
--
--   {"ok": true,  "player_id": …, "clan_id": …}
--   {"ok": false, "reason": "no_session"}
--   {"ok": false, "reason": "not_a_member"}
--
-- A tag that belongs to no clan on this platform is refused and NO player row is
-- invented for it. Two reasons:
--
--   1. R11 — players is written by sync jobs. A row created here would have no
--      clan, would never be updated by any job, and would sit in the table
--      looking like a member forever.
--   2. It is what makes T3.8's done-when true by construction: "an account
--      created with a random email and a stranger's verified tag can see no clan
--      data". Such a tag never links, so requested_clan_id stays null, so no
--      leader ever sees them in a queue, so they stay pending forever.
--
-- Manual leader approval is the confirmed policy for this deployment: verifying
-- a tag NEVER approves an account. It proves ownership and routes the applicant
-- to the right leader. Approval remains approve_account() (015), by a human.
-- ---------------------------------------------------------------------------
create or replace function link_verified_player(p_tag text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player_id uuid;
  v_clan_id   uuid;
  v_owner     uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason', 'no_session');
  end if;

  if p_tag is null then
    return jsonb_build_object('ok', false, 'reason', 'not_a_member');
  end if;

  -- clan_id is not null, so a player kept for history after leaving all three
  -- clans (T3.9 sets left_at) cannot be used to gain access. left_at is checked
  -- too: a departed member must be re-approved rather than walking back in.
  select id, clan_id, user_id
    into v_player_id, v_clan_id, v_owner
  from public.players
  where tag = p_tag
    and deleted_at is null
    and left_at is null
    and clan_id is not null;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_a_member');
  end if;

  -- Tag theft. The token proved the CALLER owns this game account, so a row
  -- already pointing at somebody else means either an account changed hands or
  -- an attempt to take over a teammate's profile. Neither is resolvable here —
  -- it raises so /api/verify can surface it and a leader can look into it.
  if v_owner is not null and v_owner <> auth.uid() then
    raise exception 'player already linked to another account';
  end if;

  perform set_config('clanbridge.bootstrap', 'on', true);

  update public.players
  set verified = true,
      user_id  = auth.uid()
  where id = v_player_id;

  -- THIS is what puts the applicant in front of the right leader. 013's
  -- "leaders read pending applicants to their clans" policy filters on
  -- requested_clan_id, and the guard trigger below now refuses a direct write to
  -- it — so this function is the only way it can ever be set, and a member
  -- cannot nominate themselves into a clan they have no account in.
  update public.users
  set requested_clan_id = v_clan_id
  where id = auth.uid()
    and deleted_at is null;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), v_clan_id, 'verify', 'players', v_player_id,
          jsonb_build_object('verified', true, 'tag', p_tag));

  return jsonb_build_object(
    'ok', true,
    'player_id', v_player_id,
    'clan_id', v_clan_id);
end;
$$;

revoke execute on function link_verified_player(text) from public;
grant execute on function link_verified_player(text) to authenticated;

comment on function link_verified_player(text) is
  'T3.3 - links a verified player tag to auth.uid() and routes the account to '
  'that clan''s leader for approval. The only write path to players from a '
  'session; players is otherwise select-only for authenticated (R11).';


-- ---------------------------------------------------------------------------
-- Close the requested_clan_id escalation.
--
-- 015 added "own profile update" so a member could set their own display name,
-- and guarded the two columns that were obviously dangerous: is_platform_admin
-- and status. requested_clan_id was not guarded, and it should have been.
--
-- Without this, any signed-in user can run
--
--     update users set requested_clan_id = '<any clan uuid>' where id = auth.uid()
--
-- and appear in that clan leader's pending-applicant list, having verified
-- nothing. It is not a data leak — 013's policy only exposes the applicant's own
-- row to the leader, and approval is still a deliberate human act — but it lets
-- a stranger put themselves in front of a leader who may click approve out of
-- habit. The whole point of the pending queue is that everything in it arrived
-- by proving something.
--
-- Now the only writer is link_verified_player() above, which sets it to the clan
-- the verified tag actually plays in.
--
-- This is a `create or replace` of 015's function; the trigger it backs
-- (users_guard_privilege_columns) is unchanged and stays attached.
-- ---------------------------------------------------------------------------
create or replace function guard_user_privilege_columns()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  -- Constrain END-USER SESSIONS only.
  --
  -- Deliberately an allow-list of the two untrusted roles rather than a
  -- deny-list of trusted ones. Everything else — service_role for sync jobs,
  -- postgres for migrations and admin tooling — is already privileged by other
  -- means, and an earlier version that tested `role = 'service_role'` blocked
  -- the migration runner itself.
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  -- The definer functions set this transaction-locally before their update.
  -- Nothing else sets it, and each one checks the caller's authority first.
  if current_setting('clanbridge.bootstrap', true) = 'on' then
    return new;
  end if;

  if new.is_platform_admin is distinct from old.is_platform_admin then
    raise exception 'is_platform_admin cannot be set directly';
  end if;

  -- status is only ever changed by approve_account() / reject_account(), which
  -- set the bootstrap GUC above. A direct session write is always refused,
  -- including a member trying to approve themselves.
  if new.status is distinct from old.status then
    raise exception 'status is set by approve_account()/reject_account(), not directly';
  end if;

  -- New in 016. See the block comment above.
  if new.requested_clan_id is distinct from old.requested_clan_id then
    raise exception 'requested_clan_id is set by link_verified_player(), not directly';
  end if;

  return new;
end;
$$;


-- ---------------------------------------------------------------------------
-- Verify:
--
--   select proname, prosecdef from pg_proc where proname = 'link_verified_player';
--     -- expect one row, prosecdef = true
--
--   select has_table_privilege('authenticated', 'players', 'update');
--     -- expect FALSE. If this is ever true, the function above has been made
--     -- redundant by a grant and players is writable from a session.
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 017_approval_grants_membership.sql
-- ========================================================================

-- T3.8 — Approving an account must also grant membership of the clan.
--
-- THE DEFECT
--
-- 015's approve_account() sets users.status = 'approved' and stops. But status is
-- only half of the gate. The other half is clan_roles: auth_clan_ids() reads it,
-- every clan-scoped policy in 006 filters on it, and visibleClans() builds the
-- switcher from it.
--
-- So an approved account with no clan_roles row is approved and still sees
-- nothing — past the /pending redirect, into an application with no clans in it.
-- The leader has clicked Approve, the applicant has been told they are in, and
-- the screen is empty. Nothing reports an error, because nothing failed.
--
-- 006 (lines 272-283) describes the empty-clan_roles state as the thing that
-- protects a stranger from seeing data, which is right. It is not a state an
-- APPROVED member should ever be left in.
--
-- WHY THIS REPLACES THE FUNCTION RATHER THAN ADDING A SECOND STEP
--
-- The alternative is for the admin page to call approve_account() and then insert
-- clan_roles itself — two round trips, no transaction. A failure between them
-- leaves exactly the half-approved state described above, and the leader has no
-- way to tell it happened.
--
-- 015 argued this same point when it made approval a function instead of a
-- policy: one indivisible act, always audited, authority checked in one readable
-- place. Granting the role is part of that act.
--
-- Section 4 — 015 is applied and is not edited. This fixes forward by replacing
-- the function; every check in the original is preserved verbatim below.


create or replace function approve_account(target uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_clan   uuid;
  target_status text;
  allowed       boolean;
begin
  if auth.uid() is null or target is null then
    return false;
  end if;

  select requested_clan_id, status into target_clan, target_status
  from public.users
  where id = target and deleted_at is null;

  if not found or target_status <> 'pending' then
    return false;
  end if;

  -- Nobody approves themselves, regardless of rank.
  if target = auth.uid() then
    raise exception 'accounts cannot approve themselves';
  end if;

  allowed := public.auth_is_platform_admin()
    or (target_clan is not null
        and target_clan in (select public.auth_leader_clan_ids()));

  if not allowed then
    return false;
  end if;

  -- New in 017. An account with no clan to be approved INTO cannot be approved:
  -- there is no membership to grant, and letting it through produces the empty
  -- application described above. The applicant must verify a player tag first,
  -- which is what sets requested_clan_id (016).
  if target_clan is null then
    return false;
  end if;

  perform set_config('clanbridge.bootstrap', 'on', true);

  update public.users
  set status      = 'approved',
      approved_by = auth.uid(),
      approved_at = now()
  where id = target;

  -- The membership itself.
  --
  -- 'member' always, never the player's in-game rank. R11 — clan_roles is an
  -- application permission, and the in-game role is a game fact that sync owns.
  -- Copying one into the other would mean a promotion in game silently granted
  -- someone the ability to publish rosters and award bonuses here.
  --
  -- on conflict do nothing because unique (user_id, clan_id) already exists and a
  -- re-approval must not fail — and must not silently DOWNGRADE a leader back to
  -- member either, which an upsert would.
  insert into public.clan_roles (user_id, clan_id, role)
  values (target, target_clan, 'member')
  on conflict (user_id, clan_id) do nothing;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), target_clan, 'approve', 'users', target,
          jsonb_build_object('status', 'approved', 'role', 'member'));

  return true;
end;
$$;

revoke execute on function approve_account(uuid) from public;
grant execute on function approve_account(uuid) to authenticated;

comment on function approve_account(uuid) is
  'T3.8 - lifts the pending gate AND grants member of the requested clan, in one '
  'transaction. Approving without the clan_roles row leaves the account past the '
  '/pending redirect with no clans visible (017).';


-- ---------------------------------------------------------------------------
-- Verify:
--
--   -- after approving, the applicant must have BOTH
--   select status from users where id = '<applicant>';          -- 'approved'
--   select role from clan_roles where user_id = '<applicant>';  -- 'member'
--
-- If the second is empty, this migration did not take effect and the member is
-- looking at an empty application right now.
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 018_admin_may_approve_clanless.sql
-- ========================================================================

-- 017 was too strict, and broke a capability 015 deliberately created.
--
-- 015 documents is_platform_admin as: "May add clans and approve accounts that
-- belong to no clan yet. Exists only to break the bootstrap cycle."
--
-- 017 then refused every approval where requested_clan_id is null, to stop a
-- member being approved into an application with no clans in it. That reasoning
-- is right for a LEADER — a leader approving someone with no clan has nothing to
-- approve them into, and no way to give them a role afterwards.
--
-- It is wrong for the platform admin, who has both. Refusing them removes the
-- exact escape hatch that exists for when the normal path is unavailable: a
-- member whose tag has not synced yet, or an account that must be let in before
-- the clan it belongs to has been added.
--
-- So the rule becomes conditional on who is asking:
--
--   leader, no requested clan  -> refused. Nothing to approve into.
--   leader, requested clan     -> approved + granted member of that clan.
--   platform admin, no clan    -> approved, no role granted. Deliberate act by
--                                 the one person who can then grant one.
--   platform admin, with clan  -> approved + granted member of that clan.
--
-- The guarantee 017 was protecting survives where it matters: nobody reaches the
-- approved state with no clan role by accident. It now takes the platform admin
-- choosing to do it.
--
-- Section 4 — 017 is applied and is not edited. Fixed forward.

create or replace function approve_account(target uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_clan   uuid;
  target_status text;
  is_admin      boolean;
  allowed       boolean;
begin
  if auth.uid() is null or target is null then
    return false;
  end if;

  select requested_clan_id, status into target_clan, target_status
  from public.users
  where id = target and deleted_at is null;

  if not found or target_status <> 'pending' then
    return false;
  end if;

  -- Nobody approves themselves, regardless of rank.
  if target = auth.uid() then
    raise exception 'accounts cannot approve themselves';
  end if;

  is_admin := public.auth_is_platform_admin();

  allowed := is_admin
    or (target_clan is not null
        and target_clan in (select public.auth_leader_clan_ids()));

  if not allowed then
    return false;
  end if;

  -- 017's guarantee, narrowed to the case it was actually about. A leader
  -- approving a clanless account would leave them past the /pending redirect
  -- with nothing to see and no role the leader could grant.
  if target_clan is null and not is_admin then
    return false;
  end if;

  perform set_config('clanbridge.bootstrap', 'on', true);

  update public.users
  set status      = 'approved',
      approved_by = auth.uid(),
      approved_at = now()
  where id = target;

  -- 'member' always, never the player's in-game rank. R11 — clan_roles is an
  -- application permission and the in-game role is a game fact that sync owns.
  -- Copying one into the other would mean a promotion in game silently granted
  -- someone the ability to publish rosters and award bonuses here.
  --
  -- on conflict do nothing because unique (user_id, clan_id) already exists: a
  -- re-approval must not fail, and must not DOWNGRADE an existing leader back to
  -- member either, which an upsert would.
  if target_clan is not null then
    insert into public.clan_roles (user_id, clan_id, role)
    values (target, target_clan, 'member')
    on conflict (user_id, clan_id) do nothing;
  end if;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), target_clan, 'approve', 'users', target,
          jsonb_build_object(
            'status', 'approved',
            'role', case when target_clan is null then null else 'member' end));

  return true;
end;
$$;

revoke execute on function approve_account(uuid) from public;
grant execute on function approve_account(uuid) to authenticated;

comment on function approve_account(uuid) is
  'T3.8 - lifts the pending gate, and grants member of the requested clan when '
  'there is one. A leader cannot approve a clanless account (nothing to approve '
  'into); the platform admin can, as 015 intends (017, 018).';

-- ========================================================================
-- 019_cwl_war_members.sql
-- ========================================================================

-- T4.1/T4.3 — cwl_war_members: the roster the API reported for one CWL war.
--
-- WHY THIS TABLE HAS TO EXIST
--
-- 002_cwl.sql:76-78 forbids storing a miss:
--
--     "Missed attacks are NOT stored. The API simply returns no attack for a
--      player who did not attack; the missed list is derived from roster minus
--      attacks (T4.3). Never insert a zero-star placeholder row."
--
-- That rule is right — a placeholder row is indistinguishable from a real zero
-- star attack once it is in the table. But "roster minus attacks" needs a
-- roster, and until now nothing stored one. cwl_wars has 18 columns and not one
-- of them holds who was in the war, so T4.5's central feature ("a clear list of
-- who has not attacked") had no source at all.
--
-- The alternative considered was a jsonb column on cwl_wars. Rejected: every
-- missed-attack query would have to unpack JSON, and T4B.11's plan-versus-
-- reality comparison (leader's roster vs who actually played) becomes a join
-- against a real table or an unpleasant mess against a document.
--
--
-- R11 — THIS IS A GAME FACT, NOT A HUMAN DECISION.
--
-- This is who the API said was in the war. It is NOT cwl_rosters, which is who
-- the leader picked (T4B.6, still a stub). R12 exists precisely to keep those
-- two apart: showing the difference between them is the most useful thing this
-- system does, and it is destroyed the moment a sync job writes to the leader's
-- table or a form writes to this one.
--
-- Written only by scripts/sync/cwl.ts.


-- ---------------------------------------------------------------------------
-- Append-only, deliberately shaped like cwl_attacks rather than like cwl_wars:
-- no updated_at and no set_updated_at trigger.
--
-- A war roster is fixed once the war starts. If the API ever reports a
-- different roster for a war we have already recorded, that is a fact worth
-- noticing, not silently overwriting (R5). The unique constraint below makes
-- the re-insert a no-op instead.
-- ---------------------------------------------------------------------------
create table cwl_war_members (
  id            uuid primary key default gen_random_uuid(),
  war_id        uuid not null references cwl_wars (id) on delete restrict,
  player_id     uuid not null references players (id) on delete restrict,
  map_position  smallint,
  th_level      smallint,
  created_at    timestamptz not null default now(),
  deleted_at    timestamptz,

  -- The idempotency key. Same role as cwl_attacks' three-column constraint:
  -- without it ON CONFLICT DO NOTHING matches nothing and every run duplicates
  -- the entire roster, silently.
  unique (war_id, player_id)
);

create index cwl_war_members_war_id_idx
  on cwl_war_members (war_id) where deleted_at is null;
create index cwl_war_members_player_id_idx
  on cwl_war_members (player_id) where deleted_at is null;

comment on table cwl_war_members is
  'Who the API reported in a CWL war (a game fact, R11). Missed attacks are '
  'this minus cwl_attacks. Not to be confused with cwl_rosters, which is who '
  'the leader selected (R12).';


-- ---------------------------------------------------------------------------
-- RLS — the same two-level join cwl_attacks uses.
--
-- There is no clan_id on this table, exactly as there is none on cwl_wars or
-- cwl_attacks. Scoping runs cwl_war_members -> cwl_wars -> cwl_seasons.clan_id.
-- test/migrations.test.ts:308 calls the two-level join "the policy most likely
-- to be written wrongly", so this one is a deliberate copy of the shape already
-- proven there rather than a fresh attempt.
-- ---------------------------------------------------------------------------
alter table cwl_war_members enable row level security;

create policy "read own clan cwl war members" on cwl_war_members
  for select to authenticated
  using (
    exists (
      select 1
      from cwl_wars w
      join cwl_seasons s on s.id = w.season_id
      where w.id = cwl_war_members.war_id
        and s.clan_id in (select auth_clan_ids())
    )
  );

-- 006 grants select to anon/authenticated on all tables that existed then, and
-- 014's alter default privileges covers tables created afterwards. Granted
-- explicitly anyway: relying on a default privilege that was set in a different
-- migration is how 014 came to exist in the first place (every sync job failed
-- with 42501 because 006 forgot service_role).
grant select on cwl_war_members to anon, authenticated;
grant select, insert, update on cwl_war_members to service_role;

-- No delete grant, for anybody. R4.


-- ---------------------------------------------------------------------------
-- Verify:
--
--   select has_table_privilege('service_role', 'cwl_war_members', 'delete');
--     -- expect FALSE (R4)
--
--   select count(*) from pg_policies where tablename = 'cwl_war_members';
--     -- expect 1
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 020_clan_details.sql
-- ========================================================================

-- T3B.0 — clan detail columns, for the dashboard at T3B.1.
--
-- These four values are NOT new data. The clan endpoint has returned them since
-- T2.3, clanSchema has parsed them since T2.2, and mapClan() has produced them
-- since T2.4 — Clan in types/domain.ts carries level, warLeague, memberCount and
-- isWarLogPublic. syncClanRecord() then writes name and badge_url and discards
-- the rest, because 001_core.sql has nowhere to put them.
--
-- So this migration does not add a fetch. It stops an hourly one being wasted.
--
-- All nullable, deliberately. A clan added through /admin (migration 015) exists
-- before any sync has seen it, and a NOT NULL here would make adding a clan fail
-- until the next run. Null means "not synced yet", which is exactly what T4.8's
-- freshness indicator is for.

alter table clans
  add column level             smallint,
  add column war_league        text,
  add column member_count      smallint,
  add column is_war_log_public boolean;

comment on column clans.level is
  'In-game clan level. Null until the first sync:clans run sees this clan.';

comment on column clans.war_league is
  'War league NAME, e.g. "Crystal League I" - not the numeric id. The id is '
  'Supercell''s and means nothing outside their API; the name is what a member '
  'recognises and what the dashboard shows.';

comment on column clans.member_count is
  'Members the API reports, which is authoritative over counting players rows: '
  'a player row can lag by up to an hour, and can also be a former member whose '
  'left_at has not been set yet (T3.9).';

-- ---------------------------------------------------------------------------
-- T0.1, finally persisted.
--
-- "Confirm war logs are public" is written in the spec as a manual in-game check,
-- but the clan endpoint reports it and sync:clans already reads and warns on it
-- (5e42f07). Until now that warning went only to a job log nobody reads.
--
-- It matters because a private war log is a HARD blocker for phase 6, not a
-- degradation: the API returns 403 for that clan's wars and the war module
-- cannot collect anything at all. Storing it means /admin can show the answer
-- for all three clans at a glance rather than it being discovered in phase 6.
-- ---------------------------------------------------------------------------
comment on column clans.is_war_log_public is
  'T0.1. False means the war module (phase 6) can collect nothing for this clan '
  '- the API returns 403 for its wars. Re-read on every sync rather than trusted '
  'once, because a leader can change it in game at any time.';

-- No RLS changes. The clans policies from 006 ("read own clans") and 015
-- ("platform admin adds clans") are row-level and already cover these columns;
-- Postgres has no column-level component to them. A new policy here would be
-- redundant at best and a second, divergent definition of the same rule at worst.

-- ========================================================================
-- 021_announcements.sql
-- ========================================================================

-- T5.1 — Announcements: post, pin, edit, soft delete.
--
-- The first HUMAN write in the system that is not an account decision (R11).
-- 006 deliberately shipped no insert/update policies and said each write would
-- add its own, scoped to the role allowed to perform it. This is that migration
-- for announcements.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- WHY FUNCTIONS RATHER THAN INSERT/UPDATE POLICIES
--
-- A write policy would let the page insert an announcement directly and then
-- insert its own audit_log row. Two statements, no transaction, and the audit
-- row is written by the same client that could simply not write it.
--
-- R4 says every write is recorded. An audit trail the application can forget to
-- append to — or, with an insert policy on audit_log, forge entries into — is
-- not an audit trail. 015 made this argument for approvals and 017 restated it:
-- one indivisible act, always audited, authority checked in one readable place.
--
-- So audit_log gets NO insert policy here, and never should. Every audited write
-- in this system runs inside a definer function that writes both rows or
-- neither.
-- ─────────────────────────────────────────────────────────────────────────────


-- ---------------------------------------------------------------------------
-- Who may post: leader and co-leader.
--
-- auth_leader_clan_ids() (006) is leader-only and is used by the audit_log
-- policy, where that strictness is right. Announcements are ordinary clan
-- business and co-leaders run those day to day, so this is a separate helper
-- rather than a loosening of the existing one — widening auth_leader_clan_ids()
-- would silently hand co-leaders the audit log too.
-- ---------------------------------------------------------------------------
create or replace function auth_leadership_clan_ids()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select clan_id
  from public.clan_roles
  where user_id = auth.uid()
    and role in ('leader', 'co-leader')
    and deleted_at is null
$$;

revoke execute on function auth_leadership_clan_ids() from public;
grant execute on function auth_leadership_clan_ids() to authenticated;

comment on function auth_leadership_clan_ids() is
  'Clans where the caller is leader OR co-leader. Distinct from '
  'auth_leader_clan_ids(), which is leader-only and gates the audit log (T9.6).';


-- ---------------------------------------------------------------------------
-- post_announcement — create, and record it.
-- ---------------------------------------------------------------------------
create or replace function post_announcement(
  p_clan   uuid,
  p_title  text,
  p_body   text,
  p_pinned boolean default false
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  new_id uuid;
begin
  if auth.uid() is null or p_clan is null then
    raise exception 'not signed in';
  end if;

  if p_clan not in (select public.auth_leadership_clan_ids()) then
    raise exception 'only a leader or co-leader may post to this clan';
  end if;

  -- Validated here as well as in the form. A route added later that forgets to
  -- check gets the same answer as one that remembers.
  if p_title is null or btrim(p_title) = '' then
    raise exception 'an announcement needs a title';
  end if;
  if p_body is null or btrim(p_body) = '' then
    raise exception 'an announcement needs a body';
  end if;
  if length(p_title) > 200 then
    raise exception 'title is too long (200 characters maximum)';
  end if;
  if length(p_body) > 5000 then
    raise exception 'body is too long (5000 characters maximum)';
  end if;

  insert into public.announcements (clan_id, author_id, title, body, pinned)
  values (p_clan, auth.uid(), btrim(p_title), btrim(p_body), coalesce(p_pinned, false))
  returning id into new_id;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), p_clan, 'create', 'announcements', new_id,
          jsonb_build_object('title', btrim(p_title), 'pinned', coalesce(p_pinned, false)));

  return new_id;
end;
$$;

revoke execute on function post_announcement(uuid, text, text, boolean) from public;
grant execute on function post_announcement(uuid, text, text, boolean) to authenticated;


-- ---------------------------------------------------------------------------
-- edit_announcement — change it, and record what it was.
--
-- `before` carries the old title and pinned flag, not the old body. The audit
-- table's own comment asks for the changed fields rather than whole entities,
-- and a 5,000-character body copied on every edit would grow audit_log faster
-- than the table it describes. The title is what identifies the post to a
-- reader; that is what a leader needs to see changed.
-- ---------------------------------------------------------------------------
create or replace function edit_announcement(
  p_id     uuid,
  p_title  text,
  p_body   text,
  p_pinned boolean
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  row_clan   uuid;
  old_title  text;
  old_pinned boolean;
begin
  if auth.uid() is null or p_id is null then
    return false;
  end if;

  select clan_id, title, pinned into row_clan, old_title, old_pinned
  from public.announcements
  where id = p_id and deleted_at is null;

  if not found then
    return false;
  end if;

  if row_clan not in (select public.auth_leadership_clan_ids()) then
    raise exception 'only a leader or co-leader may edit this announcement';
  end if;

  if p_title is null or btrim(p_title) = '' or p_body is null or btrim(p_body) = '' then
    raise exception 'an announcement needs a title and a body';
  end if;
  if length(p_title) > 200 or length(p_body) > 5000 then
    raise exception 'announcement is too long';
  end if;

  update public.announcements
  set title  = btrim(p_title),
      body   = btrim(p_body),
      pinned = coalesce(p_pinned, false)
  where id = p_id;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, before, after)
  values (auth.uid(), row_clan, 'update', 'announcements', p_id,
          jsonb_build_object('title', old_title, 'pinned', old_pinned),
          jsonb_build_object('title', btrim(p_title), 'pinned', coalesce(p_pinned, false)));

  return true;
end;
$$;

revoke execute on function edit_announcement(uuid, text, text, boolean) from public;
grant execute on function edit_announcement(uuid, text, text, boolean) to authenticated;


-- ---------------------------------------------------------------------------
-- remove_announcement — SOFT delete (R4).
--
-- Sets deleted_at. There is no statement anywhere in this project that removes
-- an announcement row, and the audit entry records who hid it. A member asking
-- "what happened to the message about CWL" gets an answer.
-- ---------------------------------------------------------------------------
create or replace function remove_announcement(p_id uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  row_clan  uuid;
  row_title text;
begin
  if auth.uid() is null or p_id is null then
    return false;
  end if;

  select clan_id, title into row_clan, row_title
  from public.announcements
  where id = p_id and deleted_at is null;

  if not found then
    return false;               -- already gone; not an error, and not audited twice
  end if;

  if row_clan not in (select public.auth_leadership_clan_ids()) then
    raise exception 'only a leader or co-leader may remove this announcement';
  end if;

  update public.announcements
  set deleted_at = now()
  where id = p_id;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, before)
  values (auth.uid(), row_clan, 'delete', 'announcements', p_id,
          jsonb_build_object('title', row_title));

  return true;
end;
$$;

revoke execute on function remove_announcement(uuid) from public;
grant execute on function remove_announcement(uuid) to authenticated;


-- ---------------------------------------------------------------------------
-- Verify:
--
--   -- as an ordinary member, this must RAISE rather than insert:
--   select post_announcement('<clan>', 'test', 'body');
--
--   -- as a leader, this must return an id AND leave exactly one audit row:
--   select post_announcement('<clan>', 'test', 'body');
--   select count(*) from audit_log where entity = 'announcements';   -- 1
--
--   -- and nothing may write audit_log directly:
--   insert into audit_log (action, entity) values ('x', 'y');  -- permission denied
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 022_cwl_bonus_awards.sql
-- ========================================================================

-- T4.7 / T4B.13 — recording who gets a bonus medal, in the leader's own order.
--
-- cwl_bonuses has existed since 002 and has never been writable: 006 created no
-- insert policy for it and granted only select. So the table that exists
-- specifically to record a justified human decision could not record anything.
--
-- WHY AN ORDER COLUMN
--
-- The rule for allocating bonuses is the LEADER'S FINAL DECISION ORDER, not a
-- formula. The system's job is to lay the evidence out — stars, attacks used,
-- missed days, average destruction (T4B.12) — and then record what the leader
-- decided, in the sequence they decided it.
--
-- That is why `award_order` is stored rather than derived. A ranking computed
-- from contribution can always be recomputed; a leader's judgement cannot. If
-- only the contribution numbers were kept, next season's "why did they get one
-- and I did not" would be answered by re-running a sort, which is precisely the
-- answer that starts the argument.
--
-- R11 — human decision data. No sync job may ever write here; the API does not
-- report bonus allocation at all, which is why this exists nowhere but here.


alter table cwl_bonuses
  add column award_order smallint;

comment on column cwl_bonuses.award_order is
  'The leader''s explicit allocation order (1 = first medal). Stored, not '
  'derived: a computed ranking can be recomputed, a judgement cannot (T4B.13).';

-- One position per season. Two players holding "second" is not an order.
create unique index cwl_bonuses_season_order_idx
  on cwl_bonuses (season_id, award_order)
  where deleted_at is null and award_order is not null;


-- ---------------------------------------------------------------------------
-- award_cwl_bonus(season, player, order, note)
--
-- A definer function rather than an insert policy, for the reason 015 records at
-- lines 199-207: awarding a bonus must also write audit_log (R4), and expressing
-- it as "which rows may this role write" splits one indivisible act into a
-- permission check and a separate, forgettable audit insert.
--
-- Idempotent on (season_id, player_id), which 002 already made unique — awarding
-- twice updates the order and the note rather than failing, because a leader
-- reordering their list is the normal case, not an error.
-- ---------------------------------------------------------------------------
create or replace function award_cwl_bonus(
  p_season uuid,
  p_player uuid,
  p_order  smallint default null,
  p_note   text default null
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_clan   uuid;
  v_before jsonb;
begin
  if auth.uid() is null or p_season is null or p_player is null then
    return false;
  end if;

  select clan_id into v_clan
  from public.cwl_seasons
  where id = p_season and deleted_at is null;

  if not found then
    return false;
  end if;

  -- Leadership of the clan whose season this is. Checked here, in one readable
  -- place, rather than in a WITH CHECK expression spread across two policies.
  if v_clan not in (select public.auth_leadership_clan_ids()) then
    return false;
  end if;

  select to_jsonb(b) into v_before
  from public.cwl_bonuses b
  where b.season_id = p_season and b.player_id = p_player;

  insert into public.cwl_bonuses (season_id, player_id, awarded_by, award_order, note)
  values (p_season, p_player, auth.uid(), p_order, p_note)
  on conflict (season_id, player_id) do update
    set award_order = excluded.award_order,
        note        = excluded.note,
        awarded_by  = excluded.awarded_by,
        awarded_at  = now(),
        deleted_at  = null;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, before, after)
  values (auth.uid(), v_clan, 'award-bonus', 'cwl_bonuses', p_player, v_before,
          jsonb_build_object('award_order', p_order, 'note', p_note));

  return true;
end;
$$;

revoke execute on function award_cwl_bonus(uuid, uuid, smallint, text) from public;
grant execute on function award_cwl_bonus(uuid, uuid, smallint, text) to authenticated;


-- The mirror, so withdrawing a medal is recorded rather than vanishing. Soft
-- delete (R4): the row stays, and the audit trail keeps both states.
create or replace function withdraw_cwl_bonus(p_season uuid, p_player uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_clan uuid;
begin
  if auth.uid() is null or p_season is null or p_player is null then
    return false;
  end if;

  select clan_id into v_clan
  from public.cwl_seasons
  where id = p_season and deleted_at is null;

  if not found or v_clan not in (select public.auth_leadership_clan_ids()) then
    return false;
  end if;

  update public.cwl_bonuses
  set deleted_at = now(), award_order = null
  where season_id = p_season and player_id = p_player and deleted_at is null;

  if not found then
    return false;
  end if;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), v_clan, 'withdraw-bonus', 'cwl_bonuses', p_player,
          jsonb_build_object('withdrawn', true));

  return true;
end;
$$;

revoke execute on function withdraw_cwl_bonus(uuid, uuid) from public;
grant execute on function withdraw_cwl_bonus(uuid, uuid) to authenticated;


-- Read stays as 006 left it: "read own clan cwl bonuses", via the season join.
-- No insert or update policy is added, deliberately — the functions above are
-- the only write path, so every award is audited by construction.
grant select on cwl_bonuses to anon, authenticated;


-- ---------------------------------------------------------------------------
-- Verify:
--
--   select has_table_privilege('authenticated', 'cwl_bonuses', 'insert');
--     -- expect FALSE. If true, an unaudited award is possible.
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 023_notifications.sql
-- ========================================================================

-- T5.5 / T5.9 / T5.6 — making push actually possible.
--
-- push_subscriptions has existed since 004 and has never been writable. 006 gave
-- it RLS and exactly one policy — "read own push subscriptions", for select — so
-- the table that exists to hold a member's device registration could not accept
-- one. This is the same hole 022 found in cwl_bonuses, and it is worth naming the
-- pattern: 006 enabled RLS everywhere and shipped select policies only, on the
-- stated plan that each write would add its own policy scoped to the role allowed
-- to perform it. Every table written since has had to pay that debt on arrival.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- WHY PLAIN POLICIES HERE, WHEN 021 AND 022 ARGUED FOR DEFINER FUNCTIONS
--
-- Those two write clan data — an announcement, a bonus medal — and R4 says every
-- write is recorded in audit_log. A definer function is how the write and its
-- audit row become one indivisible act.
--
-- A push subscription is not clan data. It is one member's own browser telling
-- the server where to reach it, and it has no clan_id to record against. That is
-- not a detail: audit_log's read policy is
--
--     using (clan_id in (select auth_leader_clan_ids()))
--
-- and `null in (...)` is NULL, never true. An audit row with no clan would be
-- invisible to every reader forever. Writing rows nobody can read is worse than
-- not writing them — it grows the table, and it makes the audit log look more
-- complete than it is.
--
-- So these are ordinary owner-scoped policies. The subject and the actor are the
-- same person, the row affects nobody else, and there is no decision to justify
-- to anyone later. Same reasoning for notification_preferences below.
-- ─────────────────────────────────────────────────────────────────────────────


-- ---------------------------------------------------------------------------
-- push_subscriptions — a member registers and de-registers their own devices.
-- ---------------------------------------------------------------------------

-- with check, not using: the row does not exist yet, so this constrains what may
-- be written rather than what may be read. Pinning user_id to auth.uid() is what
-- stops a member registering a device against somebody else's account and
-- receiving their notifications.
create policy "insert own push subscription" on push_subscriptions
  for insert to authenticated
  with check (user_id = auth.uid());

-- UPDATE covers three ordinary cases, all of which look like a rewrite:
--
--   * the browser rotates its keys and re-subscribes on the same endpoint —
--     004 made `endpoint` unique, so this arrives as an upsert, not an insert
--   * the member turns notifications off, which is a soft delete (R4)
--   * a subscription the push service reported as 410 Gone is revived when the
--     member re-subscribes later, by clearing deleted_at
--
-- Both clauses are needed: `using` decides which rows may be targeted, `with
-- check` decides what they may become. Without the second, a member could
-- reassign their own row's user_id to someone else.
create policy "update own push subscription" on push_subscriptions
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- A POLICY IS NOT A GRANT, and this is the third time this project has paid for
-- the difference. 006 granted `select on all tables` and nothing more; 014 had to
-- restore service_role's grants after every sync job failed with 42501 on first
-- contact with real Supabase.
--
-- Without these two lines the policies above are unreachable: Postgres checks the
-- table privilege first, so the insert fails with "permission denied for table
-- push_subscriptions" and the policy is never evaluated at all. That error looks
-- like a bug in the route rather than a missing grant, which is what makes it
-- expensive to find.
--
-- No DELETE, ever. R4, and the "grants no DELETE privilege" test in
-- migrations.test.ts enforces it.
grant insert, update on push_subscriptions to authenticated;


-- ---------------------------------------------------------------------------
-- T5.9 — notification_preferences.
--
-- Without these a member who finds the notifications annoying disables them at
-- the browser level, which is a decision they make once and never revisit. They
-- then stop receiving the CWL reminder too, which is the one that mattered. A
-- per-kind toggle is the difference between "too noisy" and "off".
--
-- ONE COLUMN PER KIND, not one row per (user, kind). The set of kinds is fixed
-- by what this system actually sends, adding one is a migration either way (a
-- row-per-kind table still needs its check constraint widened), and this shape
-- lets the default live in the column where it is impossible to overlook.
--
-- EVERY DEFAULT IS TRUE, and the absence of a row means the same thing. A member
-- who never opens the settings page must still get the CWL reminder, so the send
-- path left-joins this table and coalesces to true — see push_targets() below.
-- The opposite default is the version where the feature silently does nothing
-- for everyone who has not opted in, which is indistinguishable from broken.
-- ---------------------------------------------------------------------------
create table notification_preferences (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references users (id) on delete restrict,
  announcements   boolean not null default true,
  cwl_reminders   boolean not null default true,
  war_reminders   boolean not null default true,
  raid_reminders  boolean not null default true,
  poll_reminders  boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz,
  deleted_at      timestamptz
);

-- One live preference row per member. Partial, so a soft-deleted row does not
-- block writing a fresh one (R4 keeps the old one).
create unique index notification_preferences_user_idx
  on notification_preferences (user_id)
  where deleted_at is null;

create trigger notification_preferences_set_updated_at
  before update on notification_preferences
  for each row execute function set_updated_at();

alter table notification_preferences enable row level security;

create policy "read own notification preferences" on notification_preferences
  for select to authenticated
  using (user_id = auth.uid());

create policy "insert own notification preferences" on notification_preferences
  for insert to authenticated
  with check (user_id = auth.uid());

create policy "update own notification preferences" on notification_preferences
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- As above: the policies decide which rows, these decide who may ask at all.
-- service_role is stated explicitly rather than left to 014's default privileges,
-- because those apply only to tables created by the role that ran the ALTER, and
-- relying on that is how 006's omission survived unnoticed for twelve migrations.
grant select, insert, update on notification_preferences to authenticated;
grant select, insert, update on notification_preferences to service_role;

comment on table notification_preferences is
  'T5.9 — per-member notification toggles. Absence of a row means every kind is '
  'enabled; the send path coalesces to true so a member who never visited the '
  'settings page still receives the reminder that matters.';


-- ---------------------------------------------------------------------------
-- T5.6 — push_targets(clan, kind)
--
-- Who should receive a notification of this kind, in this clan, right now.
--
-- WHY THIS IS A DEFINER FUNCTION AND NOT A QUERY IN THE APPLICATION
--
-- Sending requires reading OTHER members' subscriptions, and "read own push
-- subscriptions" forbids exactly that — correctly, because a push endpoint is a
-- capability URL: anyone holding it can push to that device until it expires.
--
-- The service key could read them, but R6 keeps it out of Vercel, and an
-- announcement is posted from the web app. So the read is expressed once, here,
-- with the authority check attached to it: leadership of the clan being notified.
-- Members cannot call it usefully, and no route can widen it by forgetting a
-- filter, because the filter is not in the route.
--
-- R3 — the clan filter is the first thing this does, and it is not optional.
--
-- Sync jobs (T5.8, CWL reminders) run with the service key and bypass RLS, so
-- they may read the tables directly; they call this anyway, so that preference
-- handling and the clan filter have exactly one implementation.
-- ---------------------------------------------------------------------------
create or replace function push_targets(p_clan uuid, p_kind text)
returns table (
  user_id  uuid,
  endpoint text,
  p256dh   text,
  auth_key text
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    ps.user_id,
    ps.endpoint,
    ps.p256dh,
    ps.auth
  from public.push_subscriptions ps
  -- The subscription belongs to a member of this clan. clan_roles is the only
  -- statement of who is in a clan (R3); a leader who left keeps neither.
  join public.clan_roles cr
    on cr.user_id = ps.user_id
   and cr.clan_id = p_clan
   and cr.deleted_at is null
  -- Absent row = every kind enabled, which is why this is a LEFT join and every
  -- branch coalesces to true.
  left join public.notification_preferences np
    on np.user_id = ps.user_id
   and np.deleted_at is null
  where ps.deleted_at is null
    and case p_kind
          when 'announcements'  then coalesce(np.announcements,  true)
          when 'cwl_reminders'  then coalesce(np.cwl_reminders,  true)
          when 'war_reminders'  then coalesce(np.war_reminders,  true)
          when 'raid_reminders' then coalesce(np.raid_reminders, true)
          when 'poll_reminders' then coalesce(np.poll_reminders, true)
          -- An unrecognised kind sends to nobody. A typo in a call site should
          -- deliver nothing, not deliver to everyone.
          else false
        end
    -- Leadership of the clan being notified, or the service role, which is the
    -- sync jobs (T5.8) and bypasses RLS in any case.
    and (
      p_clan in (select public.auth_leadership_clan_ids())
      or current_setting('role', true) = 'service_role'
    )
$$;

revoke execute on function push_targets(uuid, text) from public;
grant execute on function push_targets(uuid, text) to authenticated, service_role;

comment on function push_targets(uuid, text) is
  'T5.6 — subscriptions to notify for one clan and one kind, with T5.9 '
  'preferences applied. Returns nothing unless the caller is leadership of that '
  'clan or the service role.';


-- ---------------------------------------------------------------------------
-- Verify:
--
--   -- as an ordinary member of the clan, this must return ZERO rows even
--   -- though their own subscription is in the table:
--   select count(*) from push_targets('<clan>', 'announcements');   -- 0
--
--   -- as a leader of that clan, it must return one row per subscribed member:
--   select count(*) from push_targets('<clan>', 'announcements');   -- n
--
--   -- opting out removes only that kind:
--   insert into notification_preferences (user_id, announcements)
--   values (auth.uid(), false);
--   select count(*) from push_targets('<clan>', 'announcements');   -- n - 1
--   select count(*) from push_targets('<clan>', 'cwl_reminders');   -- n
--
--   -- and a member may never register a device against another account:
--   insert into push_subscriptions (user_id, endpoint, p256dh, auth)
--   values ('<someone else>', 'x', 'y', 'z');   -- violates row level security
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 024_war.sql
-- ========================================================================

-- Phase 6 — everything the war module needs that does not exist yet.
--
-- Three separate holes, one migration, because none of them is useful alone and
-- T6.3 is blocked on all three.
--
--   1. war_members        the API's roster. THE 019 GAP, AGAIN.
--   2. war_lineups        the leader's intended lineup (T6.8, promised by the
--      war_lineup_members  012 stub, which was never written)
--   3. war_targets        had no write policy, so T6.4 could not assign anything
--
-- SUPERSEDES 012_war_lineups.sql, which is comment-only and was never applied
-- anywhere. Its number is retired the way 009's was — see the note in
-- test/pg-harness.ts. Keeping numeric order equal to apply order matters more
-- than keeping the number that was reserved a year earlier.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- WHY war_members HAS TO EXIST, WHICH IS THE SAME ARGUMENT 019 MADE
--
-- 003 gave war wars, war_targets and war_attacks — the plan, and what happened.
-- It did not give a way to know WHO WAS IN THE WAR, and every question worth
-- asking after a war needs that:
--
--   "who did not attack"        roster MINUS war_attacks. The people on that
--                               list have no war_attacks row, so they cannot be
--                               found by querying it.
--   "attacks used out of 2"     needs a denominator, which is membership
--   "selected but did not play" needs the API roster to compare the plan against
--
-- 019's header says the missed-attack list "had no source at all" before it.
-- Identical here. A war is 15-50 members and each gets two attacks; without this
-- table the war module can report what happened and never what did not.
--
-- R11 — a GAME FACT. Written only by scripts/sync/war.ts. Never confused with
-- war_lineup_members below, which is a HUMAN DECISION and which no sync job may
-- ever touch. R12 — T6.10 shows the difference between them, which is only
-- possible while both still exist.
-- ─────────────────────────────────────────────────────────────────────────────


-- ---------------------------------------------------------------------------
-- war_members — who the API reported in the war.
-- ---------------------------------------------------------------------------
create table war_members (
  id            uuid primary key default gen_random_uuid(),
  war_id        uuid not null references wars (id) on delete restrict,
  player_id     uuid not null references players (id) on delete restrict,
  map_position  smallint,
  th_level      smallint,
  -- Regular war gives two attacks per member; CWL gives one, which is why
  -- cwl_war_members has no such column. Stored rather than assumed: the value
  -- comes from the war the API described, and a future game change that alters
  -- it must not silently rewrite what old wars meant.
  attacks_allowed smallint not null default 2,
  created_at    timestamptz not null default now(),
  deleted_at    timestamptz,

  -- The idempotency key, exactly as 019's. Without it ON CONFLICT DO NOTHING
  -- matches nothing and every sync run duplicates the whole roster, silently.
  unique (war_id, player_id)
);

create index war_members_war_id_idx on war_members (war_id) where deleted_at is null;
create index war_members_player_id_idx on war_members (player_id) where deleted_at is null;

comment on table war_members is
  'Who the API reported in a war (a game fact, R11). Missed attacks are this '
  'minus war_attacks. Not to be confused with war_lineup_members, which is who '
  'the leader picked (R12).';

alter table war_members enable row level security;

-- One-level join: wars carries clan_id directly, unlike cwl_war_members which
-- has to reach through cwl_seasons. Simpler, and worth stating so nobody
-- "fixes" it later to match the CWL shape.
create policy "read own clan war members" on war_members
  for select to authenticated
  using (
    exists (
      select 1 from wars w
      where w.id = war_members.war_id
        and w.clan_id in (select auth_clan_ids())
    )
  );

grant select on war_members to anon, authenticated;
grant select, insert, update on war_members to service_role;


-- ---------------------------------------------------------------------------
-- T6.4 — war_targets could not be written.
--
-- 003 created the table and 006 granted select and nothing else, so "leadership
-- assigns targets" had no way to happen. This is the fourth table to arrive in
-- that state (announcements 021, cwl_bonuses 022, push_subscriptions 023).
--
-- A definer function, not an insert policy, for the reason 021 gives at length:
-- assigning a target must also write audit_log (R4), and a policy splits one
-- indivisible act into a permission check and a separate, forgettable insert.
--
-- R12 — this writes the PLAN. It never touches war_attacks, which is the
-- outcome. A single "reconcile" that wrote results back into war_targets would
-- destroy the exact comparison T6.5 and T6.10 exist to show.
-- ---------------------------------------------------------------------------
create or replace function assign_war_target(
  p_war      uuid,
  p_player   uuid,
  p_position smallint,
  p_note     text default null
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_clan   uuid;
  v_state  text;
  v_before jsonb;
begin
  if auth.uid() is null or p_war is null or p_player is null then
    return false;
  end if;

  select clan_id, state into v_clan, v_state
  from public.wars
  where id = p_war and deleted_at is null;

  if not found then
    return false;
  end if;

  -- R3 — the clan filter, and it is the authority check as well.
  if v_clan not in (select public.auth_leadership_clan_ids()) then
    raise exception 'only a leader or co-leader may assign targets in this war';
  end if;

  -- A war that has ended cannot be planned. Refused here rather than in the
  -- form: editing the plan after the outcome is known is how a "plan versus
  -- reality" report gets quietly rewritten into agreement with itself (R12).
  if v_state = 'warEnded' then
    raise exception 'this war has ended; its plan can no longer be changed';
  end if;

  -- The player must actually be in the war. Without this a leader can assign a
  -- target to somebody the API never put in the lineup, and the missed-attack
  -- list then contains a person who was never able to attack.
  if not exists (
    select 1 from public.war_members
    where war_id = p_war and player_id = p_player and deleted_at is null
  ) then
    raise exception 'that player is not in this war';
  end if;

  select to_jsonb(t) into v_before
  from public.war_targets t
  where t.war_id = p_war and t.player_id = p_player;

  -- 003 made (war_id, player_id) unique and its comment says reassigning
  -- UPDATES the row, with the change recorded in audit_log rather than by
  -- inserting a second target. This is that behaviour.
  insert into public.war_targets (war_id, player_id, target_position, note, assigned_by)
  values (p_war, p_player, p_position, p_note, auth.uid())
  on conflict (war_id, player_id) do update
    set target_position = excluded.target_position,
        note            = excluded.note,
        assigned_by     = excluded.assigned_by,
        assigned_at     = now(),
        deleted_at      = null;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, before, after)
  values (auth.uid(), v_clan, 'assign-target', 'war_targets', p_player, v_before,
          jsonb_build_object('target_position', p_position, 'note', p_note));

  return true;
end;
$$;

revoke execute on function assign_war_target(uuid, uuid, smallint, text) from public;
grant execute on function assign_war_target(uuid, uuid, smallint, text) to authenticated;


-- The mirror. Soft delete (R4): the row stays and the audit trail keeps both
-- states, so "who told me to hit base 7" has an answer after it is withdrawn.
create or replace function clear_war_target(p_war uuid, p_player uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_clan uuid;
  v_before jsonb;
begin
  if auth.uid() is null or p_war is null or p_player is null then
    return false;
  end if;

  select clan_id into v_clan from public.wars
  where id = p_war and deleted_at is null;

  if not found then
    return false;
  end if;

  if v_clan not in (select public.auth_leadership_clan_ids()) then
    raise exception 'only a leader or co-leader may clear targets in this war';
  end if;

  select to_jsonb(t) into v_before
  from public.war_targets t
  where t.war_id = p_war and t.player_id = p_player and t.deleted_at is null;

  if v_before is null then
    return false;                      -- already gone; not an error, not audited twice
  end if;

  update public.war_targets
  set deleted_at = now()
  where war_id = p_war and player_id = p_player;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, before)
  values (auth.uid(), v_clan, 'clear-target', 'war_targets', p_player, v_before);

  return true;
end;
$$;

revoke execute on function clear_war_target(uuid, uuid) from public;
grant execute on function clear_war_target(uuid, uuid) to authenticated;


-- ---------------------------------------------------------------------------
-- T6.8 — the lineup the leader intends, which the API can never tell you.
--
-- The API reports who IS in a war, never who WILL be. So this exists nowhere
-- but here (R11), and it is the entire reason the war module needs a backend
-- rather than a sync job.
--
-- Same shape as the CWL roster tables in 011, deliberately: a leader who has
-- learned one screen has learned the other.
--
-- NOT tied to a war row. A lineup is decided BEFORE the war is declared in
-- game, and until then no war exists to reference — that is the whole point.
-- It hangs off (clan_id, planned_for) instead, and T6.10 matches it to the war
-- that eventually appears.
-- ---------------------------------------------------------------------------
create table war_lineups (
  id           uuid primary key default gen_random_uuid(),
  clan_id      uuid not null references clans (id) on delete restrict,
  -- Roughly when this war is expected. Also what makes two drafts for two
  -- different wars distinguishable before either is declared.
  planned_for  timestamptz not null default now(),
  size         smallint not null check (size between 5 and 50),
  status       text not null default 'draft' check (status in ('draft', 'published')),
  -- Filled in once the war appears in game, which is what turns an intention
  -- into something T6.10 can compare against reality.
  war_id       uuid references wars (id) on delete restrict,
  created_by   uuid not null references users (id) on delete restrict,
  published_at timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz,
  deleted_at   timestamptz
);

create trigger war_lineups_set_updated_at
  before update on war_lineups
  for each row execute function set_updated_at();

create index war_lineups_clan_id_idx on war_lineups (clan_id) where deleted_at is null;

create table war_lineup_members (
  id         uuid primary key default gen_random_uuid(),
  lineup_id  uuid not null references war_lineups (id) on delete restrict,
  player_id  uuid not null references players (id) on delete restrict,
  position   smallint,
  added_by   uuid not null references users (id) on delete restrict,
  added_at   timestamptz not null default now(),
  created_at timestamptz not null default now(),
  deleted_at timestamptz,

  unique (lineup_id, player_id)
);

create index war_lineup_members_lineup_id_idx
  on war_lineup_members (lineup_id) where deleted_at is null;

comment on table war_lineup_members is
  'Who the leader picked for a war (a human decision, R11). Compared against '
  'war_members at T6.10, never replaced by it (R12). No sync job may write here.';

alter table war_lineups enable row level security;
alter table war_lineup_members enable row level security;

-- A DRAFT IS NOT VISIBLE TO MEMBERS, and the policy is what enforces that, not
-- the page. 011 makes the same argument for CWL rosters: a draft is the leader
-- thinking out loud, with people on it who will be cut, and showing it causes
-- exactly the arguments publishing is meant to prevent.
create policy "read published or own clan draft lineups" on war_lineups
  for select to authenticated
  using (
    clan_id in (select auth_clan_ids())
    and (status = 'published' or clan_id in (select auth_leadership_clan_ids()))
  );

create policy "leadership writes lineups" on war_lineups
  for insert to authenticated
  with check (clan_id in (select auth_leadership_clan_ids()));

create policy "leadership updates lineups" on war_lineups
  for update to authenticated
  using (clan_id in (select auth_leadership_clan_ids()))
  with check (clan_id in (select auth_leadership_clan_ids()));

create policy "read lineup members of readable lineups" on war_lineup_members
  for select to authenticated
  using (
    exists (
      select 1 from war_lineups l
      where l.id = war_lineup_members.lineup_id
        and l.clan_id in (select auth_clan_ids())
        and (l.status = 'published' or l.clan_id in (select auth_leadership_clan_ids()))
    )
  );

create policy "leadership writes lineup members" on war_lineup_members
  for insert to authenticated
  with check (
    exists (
      select 1 from war_lineups l
      where l.id = war_lineup_members.lineup_id
        and l.clan_id in (select auth_leadership_clan_ids())
    )
  );

create policy "leadership updates lineup members" on war_lineup_members
  for update to authenticated
  using (
    exists (
      select 1 from war_lineups l
      where l.id = war_lineup_members.lineup_id
        and l.clan_id in (select auth_leadership_clan_ids())
    )
  )
  with check (
    exists (
      select 1 from war_lineups l
      where l.id = war_lineup_members.lineup_id
        and l.clan_id in (select auth_leadership_clan_ids())
    )
  );

grant select, insert, update on war_lineups to authenticated;
grant select, insert, update on war_lineup_members to authenticated;
grant select on war_lineups, war_lineup_members to anon;

-- ---------------------------------------------------------------------------
-- R11 AS A PRIVILEGE, NOT A COMMENT.
--
-- These two tables hold the leader's decision. A sync job runs every fifteen
-- minutes and overwrites; if one could write here, a routine tick erases an
-- hour of their work, and R4 means there is no deleted row to recover.
--
-- The REVOKE is the operative line, and it is not redundant. 014 issued
--
--     alter default privileges in schema public
--       grant select, insert, update on tables to service_role;
--
-- so EVERY table created after it is born writable by the sync jobs. Granting
-- only select here changes nothing on its own — the default privilege has
-- already been applied by the time this statement runs. A test asserting the
-- sync role cannot write caught exactly that, having been written in the belief
-- that a narrow grant was a narrow permission.
--
-- Worth knowing more broadly: the same default privilege reaches cwl_rosters,
-- cwl_roster_members, polls and poll_responses. Nothing writes them today except
-- the application, and the boundary is documented at the top of
-- scripts/sync/shared.ts — but there it is discipline, and here it is enforced.
-- Tightening the others deserves its own migration and its own tests.
-- ---------------------------------------------------------------------------
revoke insert, update, delete on war_lineups from service_role;
revoke insert, update, delete on war_lineup_members from service_role;

-- Still readable, so T6.10's comparison can be computed from a job if it ever
-- moves there.
grant select on war_lineups, war_lineup_members to service_role;

-- No delete grant, for anybody. R4.


-- ---------------------------------------------------------------------------
-- Verify:
--
--   -- as an ordinary member, a draft lineup must be invisible:
--   select count(*) from war_lineups where status = 'draft';        -- 0
--
--   -- as a member, assigning a target must RAISE:
--   select assign_war_target('<war>', '<player>', 3::smallint);
--
--   -- as a leader, it must succeed AND leave exactly one audit row:
--   select assign_war_target('<war>', '<player>', 3::smallint);
--   select count(*) from audit_log where entity = 'war_targets';    -- 1
--
--   -- reassigning updates rather than duplicating:
--   select assign_war_target('<war>', '<player>', 7::smallint);
--   select count(*) from war_targets where war_id = '<war>';        -- still 1
--
--   -- and a sync job may never write the leader's plan:
--   set role service_role;
--   insert into war_lineup_members (lineup_id, player_id, added_by)
--   values (...);                                                   -- denied
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 025_war_target_claim.sql
-- ========================================================================

-- T6.4, second half — "Members may claim an unassigned target."
--
-- 024 shipped assign_war_target() and clear_war_target(), both of which raise
-- for anyone below co-leader. That is correct for assignment. It also means the
-- sentence above, which is in the task text, has no write path at all: a member
-- can read the board and change nothing on it.
--
-- This is the fifth table in this project to reach a page before it reached a
-- grant (021 announcements, 022 cwl_bonuses, 023 push_subscriptions, 024
-- war_targets for leadership, and now war_targets for members). The pattern is
-- consistent enough to state plainly: a feature is not writable because someone
-- wrote a form for it.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- WHY A CLAIM IS NOT JUST assign_war_target WITH A WEAKER ROLE CHECK
--
-- Four rules differ, and each of them is the difference between "members can
-- self-organise" and "members can quietly undo the leader's plan":
--
--   1. YOU MAY ONLY CLAIM FOR YOURSELF. The player is resolved from
--      players.user_id = auth.uid(), never passed in. A p_player argument would
--      be an authorisation decision made by the caller.
--
--   2. YOU MAY NOT TAKE A BASE SOMEONE ELSE HOLDS. Asymmetric with the leader's
--      function on purpose: 003 puts no unique constraint on
--      (war_id, target_position) because double-hitting a base is a legitimate
--      thing for a leader to order. A member helping themselves to base 3
--      because it looks easy is not the same act, and the check below is the
--      only thing that separates them.
--
--   3. YOU MAY NOT OVERWRITE AN ASSIGNMENT MADE BY SOMEBODY ELSE. Re-claiming
--      your own previous claim is fine — that is changing your mind. Replacing
--      what your co-leader told you to do is not a claim, it is a refusal, and
--      it must not look identical to one in the audit trail.
--
--   4. THE AUDIT ACTION IS DIFFERENT. 'claim-target', not 'assign-target', so
--      T9.6's viewer can answer "did the leader put me on base 7, or did I?"
--      Recording both as the same action makes that question unanswerable, and
--      it is precisely the question that gets asked after a lost war.
--
-- R12 — like 024's functions, this writes the PLAN and never touches
-- war_attacks. R4 — nothing here deletes; withdrawal is clear_war_target's soft
-- delete, which remains leadership-only by design (see the note at the end).
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function claim_war_target(
  p_war      uuid,
  p_position smallint,
  p_note     text default null
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_clan   uuid;
  v_state  text;
  v_player uuid;
  v_before jsonb;
  v_holder uuid;
  v_by     uuid;
begin
  if auth.uid() is null or p_war is null or p_position is null then
    return false;
  end if;

  select clan_id, state into v_clan, v_state
  from public.wars
  where id = p_war and deleted_at is null;

  if not found then
    return false;
  end if;

  -- R3. Membership, not leadership — that is the whole point of this function —
  -- but still a clan check: a member of clan A may not claim in clan B's war.
  if v_clan not in (select public.auth_clan_ids()) then
    raise exception 'you are not in this clan';
  end if;

  -- Same rule as 024. Editing the plan after the outcome is known is how a
  -- "plan versus reality" report quietly becomes one that agrees with itself.
  if v_state = 'warEnded' then
    raise exception 'this war has ended; its plan can no longer be changed';
  end if;

  -- Rule 1. Resolved, never supplied. An account with no linked player has not
  -- finished verification (T3.3) and has nothing to claim with — said plainly,
  -- because "nothing happened" on a button press is the most confusing possible
  -- answer to a member who has not realised they never verified.
  select id into v_player
  from public.players
  where user_id = auth.uid() and deleted_at is null
  limit 1;

  if v_player is null then
    raise exception 'no verified player is linked to your account; verify first';
  end if;

  if not exists (
    select 1 from public.war_members
    where war_id = p_war and player_id = v_player and deleted_at is null
  ) then
    raise exception 'you are not in this war';
  end if;

  -- Rule 2. Any LIVE target on that base, held by anyone else.
  select player_id into v_holder
  from public.war_targets
  where war_id = p_war
    and target_position = p_position
    and player_id <> v_player
    and deleted_at is null
  limit 1;

  if v_holder is not null then
    raise exception 'base % is already taken', p_position;
  end if;

  -- Rule 3. Your own row, whoever put it there.
  select to_jsonb(t), t.assigned_by into v_before, v_by
  from public.war_targets t
  where t.war_id = p_war and t.player_id = v_player and t.deleted_at is null;

  if v_by is not null and v_by <> auth.uid() then
    raise exception
      'leadership has already assigned you a target; ask them to change it';
  end if;

  insert into public.war_targets (war_id, player_id, target_position, note, assigned_by)
  values (p_war, v_player, p_position, p_note, auth.uid())
  on conflict (war_id, player_id) do update
    set target_position = excluded.target_position,
        note            = excluded.note,
        assigned_by     = excluded.assigned_by,
        assigned_at     = now(),
        deleted_at      = null;

  -- Rule 4.
  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, before, after)
  values (auth.uid(), v_clan, 'claim-target', 'war_targets', v_player, v_before,
          jsonb_build_object('target_position', p_position, 'note', p_note));

  return true;
end;
$$;

revoke execute on function claim_war_target(uuid, smallint, text) from public;
grant execute on function claim_war_target(uuid, smallint, text) to authenticated;


-- ---------------------------------------------------------------------------
-- The mirror, and it is narrower than clear_war_target on purpose.
--
-- A member may release a base THEY claimed. They may not release one leadership
-- assigned them — that is clear_war_target's job and it stays leadership-only,
-- because "I dropped the target you gave me" is a conversation, not a button.
--
-- Soft delete (R4): the row stays and both states are in the audit trail, so
-- "who was on base 7 an hour ago" still has an answer.
-- ---------------------------------------------------------------------------
create or replace function release_war_target(p_war uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_clan   uuid;
  v_state  text;
  v_player uuid;
  v_before jsonb;
  v_by     uuid;
begin
  if auth.uid() is null or p_war is null then
    return false;
  end if;

  select clan_id, state into v_clan, v_state
  from public.wars
  where id = p_war and deleted_at is null;

  if not found then
    return false;
  end if;

  if v_clan not in (select public.auth_clan_ids()) then
    raise exception 'you are not in this clan';
  end if;

  if v_state = 'warEnded' then
    raise exception 'this war has ended; its plan can no longer be changed';
  end if;

  select id into v_player
  from public.players
  where user_id = auth.uid() and deleted_at is null
  limit 1;

  if v_player is null then
    return false;
  end if;

  select to_jsonb(t), t.assigned_by into v_before, v_by
  from public.war_targets t
  where t.war_id = p_war and t.player_id = v_player and t.deleted_at is null;

  if v_before is null then
    return false;                      -- already gone; not an error, not audited twice
  end if;

  if v_by is distinct from auth.uid() then
    raise exception
      'leadership assigned this target; ask them to clear it';
  end if;

  update public.war_targets
  set deleted_at = now()
  where war_id = p_war and player_id = v_player;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, before)
  values (auth.uid(), v_clan, 'release-target', 'war_targets', v_player, v_before);

  return true;
end;
$$;

revoke execute on function release_war_target(uuid) from public;
grant execute on function release_war_target(uuid) to authenticated;


-- ---------------------------------------------------------------------------
-- NO NEW GRANT ON war_targets, AND THAT IS THE POINT.
--
-- 023's header is worth restating because it is the mistake this project keeps
-- almost making: a policy is not a grant, and Postgres checks the table
-- privilege first. The inverse also holds — these functions are SECURITY
-- DEFINER, so they run as the owner and need no privilege granted to
-- `authenticated` at all. Adding `grant insert on war_targets to authenticated`
-- to "make it work" would open a second, unaudited write path around every rule
-- above, and it would work, which is what makes it dangerous.
--
-- Verify:
--
--   -- as a member with a linked player, in the war:
--   select claim_war_target('<war>', 3::smallint);              -- true
--   select count(*) from audit_log where action = 'claim-target';  -- 1
--
--   -- a second member cannot take the same base:
--   select claim_war_target('<war>', 3::smallint);              -- RAISES
--
--   -- and cannot overwrite what a leader assigned them:
--   select assign_war_target('<war>', '<them>', 5::smallint);   -- as leader
--   select claim_war_target('<war>', 9::smallint);              -- RAISES
--
--   -- releasing your own claim is a soft delete, not a delete:
--   select release_war_target('<war>');
--   select count(*) from war_targets where deleted_at is not null;  -- 1
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 026_war_opponent.sql
-- ========================================================================

-- T6.3 — "War board page. BOTH ROSTERS, attack status per base."
--
-- Only one roster exists. 024 gave war_members, which references players and
-- therefore holds our side alone; the opponent arrives on the same API response
-- and is thrown away, exactly as 020 found the clan detail being thrown away
-- hourly since T2.4.
--
-- Without it the board can show base numbers and nothing else, and T6.4 — the
-- feature this whole phase is arranged around — becomes "assign your TH16 to
-- base 7" with no way to know what base 7 is. A leader who cannot see the
-- opposing lineup assigns targets by position and hope.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- WHY THIS IS NOT war_members WITH A `side` COLUMN, AND NOT players ROWS
--
-- war_members.player_id is NOT NULL and references players. Widening it to hold
-- the opposition means either a nullable FK — after which every join in the war
-- module needs a filter nobody will remember on the first day — or creating
-- players rows for them.
--
-- Creating players rows is the one that looks convenient and is not. `players`
-- is the member directory (T3B.2), the donation report (T3B.3), the inactivity
-- list (T3B.5), the cross-clan search (T3B.6) and the roster pool (T4B.7).
-- Fifty strangers per war, permanently, in all of them — and R4 means the
-- correction is a deleted_at, never a delete. A separate table costs one join
-- and cannot leak into anything.
--
-- R11 — a GAME FACT, written only by scripts/sync/war.ts.
--
-- NO TAG FORMAT CONSTRAINT, unlike players. That check exists to catch a human
-- transcribing a tag wrongly (001_core.sql:95-98). Nothing here is typed by a
-- human; it comes from the API. A war whose opponent has a tag Supercell accepts
-- and this project's regex does not would fail the whole sync, which is a far
-- worse outcome than storing an odd-looking tag.
-- ─────────────────────────────────────────────────────────────────────────────

create table war_opponent_members (
  id           uuid primary key default gen_random_uuid(),
  war_id       uuid not null references wars (id) on delete restrict,
  tag          text not null,
  name         text,
  map_position smallint,
  th_level     smallint,
  created_at   timestamptz not null default now(),
  deleted_at   timestamptz,

  -- The idempotency key. Without it ON CONFLICT DO NOTHING matches nothing and
  -- every sync run duplicates the entire opposing roster, silently — the same
  -- hole 019 and 024 each name in their headers.
  unique (war_id, tag)
);

create index war_opponent_members_war_id_idx
  on war_opponent_members (war_id) where deleted_at is null;

-- The lookup war_attacks.defender_position is resolved through, and the one the
-- board reads for every row.
create index war_opponent_members_position_idx
  on war_opponent_members (war_id, map_position) where deleted_at is null;

comment on table war_opponent_members is
  'The opposing lineup for one war (a game fact, R11). Deliberately NOT in '
  'players: they are not members of any of the three clans, and putting them '
  'there would place fifty strangers per war into the member directory, the '
  'donation report and the cross-clan search, permanently (R4).';

alter table war_opponent_members enable row level security;

-- One-level join, the same shape 024 uses for war_members: `wars` carries
-- clan_id directly.
create policy "read own clan war opponents" on war_opponent_members
  for select to authenticated
  using (
    exists (
      select 1 from wars w
      where w.id = war_opponent_members.war_id
        and w.clan_id in (select auth_clan_ids())
    )
  );

grant select on war_opponent_members to anon, authenticated;
grant select, insert, update on war_opponent_members to service_role;

-- No insert or update for `authenticated`, and no delete for anybody. This is
-- what the API said, not something a person edits (R11), and R4 forbids the
-- delete regardless.


-- ---------------------------------------------------------------------------
-- Verify:
--
--   -- as a member, the opposing lineup for your own war is visible:
--   select count(*) from war_opponent_members;         -- teamSize
--
--   -- and another clan's is not (R3):
--   select count(*) from war_opponent_members
--    where war_id = '<another clan's war>';            -- 0
--
--   -- a leader may not invent an opponent:
--   insert into war_opponent_members (war_id, tag) values ('<war>', '#X');
--                                                       -- denied
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 027_raid_detail.sql
-- ========================================================================

-- T7.1/T7.3/T7.4 — the raid and Clan Games detail 004 had nowhere to put.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- THIS IS THE FOURTH TIME, AND THE FIRST TIME IT WAS SEEN COMING
--
-- 019 found the CWL roster being fetched and dropped. 020 found the clan detail.
-- 026 found the opposing war lineup. Each time the API had already sent the data
-- and the sync had nowhere to put it, and each time the feature that needed it
-- could not be built until a table existed.
--
-- IMPLEMENTATION.md §0 then wrote the prediction down by name: "the raid and
-- Clan Games responses in Phase 7 carry more than their tables hold. Worth
-- suspecting on every remaining endpoint." It was right. This migration lands
-- BEFORE scripts/sync/raids.ts is written rather than after, which is the only
-- difference between this one and the three before it.
-- ─────────────────────────────────────────────────────────────────────────────
--
-- R11 — everything added here is a GAME FACT, written only by
-- scripts/sync/raids.ts and scripts/sync/clan-games.ts. No new policies and no
-- new grants: 006 already grants select on all four tables and 014 already
-- grants select/insert/update to service_role, so the sync can write the new
-- columns the moment they exist. A column is not a table; the existing row
-- policies cover it.


-- ---------------------------------------------------------------------------
-- raid_seasons — what the weekend actually was
--
-- 004 stored start_time, end_time and total_loot. raidSeasonSchema
-- (coc-schemas.ts:198) carries five more fields on the same response.
-- ---------------------------------------------------------------------------

alter table raid_seasons
  -- 'ongoing' | 'ended', per the API. Without it a page cannot tell a weekend
  -- still being played from one that finished, and R10's "an ongoing raid is
  -- not a failure" has nothing to read.
  add column state text,

  -- How many of the offered raids the clan actually completed, and how many
  -- attacks the whole clan spent. The denominators for T7.3's participation
  -- view — a numerator on its own is a number nobody can act on.
  add column raids_completed smallint,
  add column total_attacks smallint,

  -- RAID MEDALS. Offensive is the payout every member receives and is the one
  -- number members actually argue about after a weekend; defensive is the
  -- smaller payout from being raided. Dropping these means the page can show
  -- loot — which buys nothing — and not the reward, which buys everything.
  add column offensive_reward integer,
  add column defensive_reward integer;

comment on column raid_seasons.offensive_reward is
  'Raid medals awarded for attacking. The number members compare weekends by.';


-- ---------------------------------------------------------------------------
-- raid_participants — the denominator
--
-- 004 stored attacks_used and loot. T7.3 asks for "attacks used", and
-- "5" alone does not answer it: a member with 5 of 5 did everything asked and a
-- member with 5 of 6 did not. The limit is per-member and it VARIES — a
-- bonus attack is awarded to some members and not others — so it cannot be
-- inferred from a constant the way a regular war's two attacks can.
--
-- Same shape of mistake as CWL's boolean `missed` being wrong for a war that
-- gives two attacks (T6.9). The unit has to carry its own denominator.
-- ---------------------------------------------------------------------------

alter table raid_participants
  add column attack_limit smallint,
  add column bonus_attack_limit smallint;

comment on column raid_participants.attack_limit is
  'Attacks this member was offered, excluding the bonus. attacks_used without '
  'it is a numerator with no denominator: 5 of 5 and 5 of 6 are different '
  'answers to "did they do what was asked".';


-- ---------------------------------------------------------------------------
-- clan_games — the window, and when the season stops moving
--
-- ─────────────────────────────────────────────────────────────────────────────
-- WHY `settled_at` EXISTS
--
-- T7.4 has no API to read a score from. It snapshots each player's "Games
-- Champion" achievement at the start of the period into start_value, and again
-- at the end into end_value, and the difference is that season's points.
--
-- That end pass must UPDATE a row the start pass inserted. R5 says a historical
-- row is never rewritten, and without a marker there is no way to tell "this
-- season is still running, the end value may still move" from "this season
-- finished in March and must never be touched again". A job re-run in April
-- would happily write April's achievement total into March's end_value and
-- silently turn a real score into a wrong one — with no error, because
-- overwriting is exactly what the job does the rest of the time.
--
-- scripts/sync/war.ts:104-110 established the resolution: a live row may move
-- until it settles, and after that it is closed. This is the same rule with a
-- column behind it rather than a comment.
-- ─────────────────────────────────────────────────────────────────────────────
--
-- start_time and end_time were already here and nullable. They stay nullable
-- because the API supplies NEITHER — the window is derived from the calendar
-- (lib/coc-time.ts), never typed in by a leader. A leader-entered date in a
-- game-fact table is exactly the R11 mixing that makes a table's provenance
-- unanswerable six months later.

alter table clan_games
  add column settled_at timestamptz;

comment on column clan_games.settled_at is
  'Set once the end-of-period snapshot has been taken. After this the season is '
  'closed and no sync may write its scores again (R5). Null means the period is '
  'still open and end_value is expected to move.';

create index clan_games_open_idx
  on clan_games (clan_id) where settled_at is null and deleted_at is null;


-- ---------------------------------------------------------------------------
-- Verify:
--
--   -- the new columns exist and are readable by a member of that clan (R3):
--   select state, raids_completed, offensive_reward from raid_seasons;
--
--   -- a member still cannot invent a raid (R11 — no insert policy was added):
--   insert into raid_seasons (clan_id, start_time)
--     values ('<your clan>', now());                     -- denied
--
--   -- and the open-season index is the one T7.4 looks a season up by:
--   explain select * from clan_games
--    where clan_id = '<your clan>' and settled_at is null;
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 028_base_layouts.sql
-- ========================================================================

-- Phase 8 — everything base_layouts needs that 004 and 006 did not give it.
--
-- 004 created the table. 006 gave it a SELECT policy and stopped, so the library
-- has been readable and unwritable since the first week of this project. That is
-- now the fourth time: 021 (announcements), 022 (cwl_bonuses), 023
-- (push_subscriptions) each had to add the write path for a table that already
-- existed, and each header said the same thing. Stating it once more because the
-- pattern is the finding:
--
--   A POLICY IS NOT A GRANT. Postgres checks the table privilege first, so a
--   missing `grant insert` fails with "permission denied for table" and the
--   policy is never evaluated at all — an error that reads like a bug in the
--   route rather than a missing line in a migration (014, 023).
--
-- ─────────────────────────────────────────────────────────────────────────────
-- WHY VOTES NEED A TABLE AND NOT JUST THE COUNTER 004 ALREADY HAS
--
-- base_layouts.votes is an integer. An integer cannot answer the only question
-- voting actually has to answer, which is "have I already voted for this one?"
-- Without that, every vote button is a +1 button, one member can hold it down,
-- and the ranking becomes a measure of who cared most rather than what the clan
-- thinks. It also cannot be undone, because there is no record of who to undo.
--
-- So base_layout_votes carries one row per member per layout, with a unique
-- constraint doing the enforcing. The counter stays as a maintained cache — the
-- definer functions below move both in the same statement, so they cannot come
-- apart, and browse-by-popularity stays a sort rather than an aggregate per row.
--
-- R4 — a withdrawn vote is SOFT deleted, like everything else here. The first
-- draft of this file argued for a real DELETE, on the grounds that a retracted
-- vote is somebody changing their mind rather than history worth keeping. The
-- suite rejected it (`contains no DELETE statements`), and the suite was right:
-- 023 had already solved exactly this shape for notification_preferences with a
-- PARTIAL unique index, so a soft-deleted row does not block writing a fresh
-- one. An invariant that holds everywhere is worth more than a table-sized
-- exception, and the exception bought nothing this does not.
-- ─────────────────────────────────────────────────────────────────────────────


-- ---------------------------------------------------------------------------
-- base_layout_votes — one member, one layout, one live vote.
-- ---------------------------------------------------------------------------
create table base_layout_votes (
  id         uuid primary key default gen_random_uuid(),
  layout_id  uuid not null references base_layouts (id) on delete restrict,
  user_id    uuid not null references users (id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz,
  deleted_at timestamptz
);

-- The whole point, and PARTIAL so R4's tombstone does not block a re-vote.
-- Without the constraint the counter is a click tally; without the `where` a
-- member who unvotes can never vote again.
create unique index base_layout_votes_one_per_member_idx
  on base_layout_votes (layout_id, user_id)
  where deleted_at is null;

create index base_layout_votes_layout_idx on base_layout_votes (layout_id)
  where deleted_at is null;

create trigger base_layout_votes_set_updated_at
  before update on base_layout_votes
  for each row execute function set_updated_at();

alter table base_layout_votes enable row level security;

-- Readable by members of the clan that owns the layout, so a page can show
-- "you voted" rather than only a total. The clan check goes through the layout,
-- because a vote row has no clan of its own (R3 — the filter is still there, it
-- is one join away).
create policy "read votes on own clan layouts" on base_layout_votes
  for select to authenticated
  using (
    layout_id in (
      select id from base_layouts
      where clan_id in (select auth_clan_ids())
        and deleted_at is null
    )
  );

grant select on base_layout_votes to authenticated;
-- No insert or update grant to authenticated ANYWHERE. Voting happens only
-- through the definer functions below, which is what keeps the counter and the
-- rows in step. A member who could insert directly could add a vote row without
-- moving the counter, and nothing would ever notice.
grant select, insert, update on base_layout_votes to service_role;


-- ---------------------------------------------------------------------------
-- Writes on base_layouts itself.
--
-- Any member may upload — a good base is a good base regardless of rank, and
-- restricting this to leadership would empty the library. Editing and removing
-- are limited to the uploader or the clan's leadership.
-- ---------------------------------------------------------------------------
create policy "members add layouts to their own clan" on base_layouts
  for insert to authenticated
  with check (
    clan_id in (select auth_clan_ids())
    and uploaded_by = auth.uid()
  );

-- Update rather than delete, because R4 means removal is `deleted_at`, and that
-- is an UPDATE. Both the uploader and leadership can reach it; the WITH CHECK
-- repeats the USING clause so a row cannot be updated out of its own clan.
create policy "uploader or leadership edits a layout" on base_layouts
  for update to authenticated
  using (
    clan_id in (select auth_clan_ids())
    and (uploaded_by = auth.uid() or clan_id in (select auth_leadership_clan_ids()))
  )
  with check (
    clan_id in (select auth_clan_ids())
    and (uploaded_by = auth.uid() or clan_id in (select auth_leadership_clan_ids()))
  );

grant select, insert, update on base_layouts to authenticated;
grant select on base_layouts to anon;
grant select, insert, update on base_layouts to service_role;


-- ---------------------------------------------------------------------------
-- vote_for_layout(layout) / unvote_layout(layout)
--
-- Definer functions rather than policies, for the reason 021 gives: the vote row
-- and the counter must move together or not at all. Two statements from the
-- application is two statements that can be interrupted between, and the visible
-- symptom is a layout whose displayed score disagrees with the number of people
-- who actually voted — with nothing to say which is right.
--
-- Returns the new total so the caller can render it without a second read.
-- ---------------------------------------------------------------------------
create or replace function vote_for_layout(p_layout uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_clan  uuid;
  v_total integer;
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;

  -- R3 — the caller must be in the layout's clan, checked here rather than
  -- trusted to the page. A definer function bypasses RLS, so this IS the check.
  select clan_id into v_clan
  from public.base_layouts
  where id = p_layout and deleted_at is null;

  if v_clan is null then
    raise exception 'layout not found';
  end if;

  if v_clan not in (select public.auth_clan_ids()) then
    raise exception 'layout not found';  -- deliberately not "forbidden": see below
  end if;

  -- Already voted: a no-op returning the current total, not an error. A
  -- double-tap on a phone is not a mistake worth showing somebody.
  if exists (
    select 1 from public.base_layout_votes
    where layout_id = p_layout and user_id = auth.uid() and deleted_at is null
  ) then
    select votes into v_total from public.base_layouts where id = p_layout;
    return v_total;
  end if;

  -- Revive a withdrawn vote if there is one, otherwise record a new one. Two
  -- statements rather than an upsert because the partial index means ON CONFLICT
  -- would have to name the predicate, and a resurrection is a different event
  -- from a first vote even though both end with the same row.
  update public.base_layout_votes
  set deleted_at = null
  where layout_id = p_layout and user_id = auth.uid() and deleted_at is not null;

  if not found then
    insert into public.base_layout_votes (layout_id, user_id)
    values (p_layout, auth.uid());
  end if;

  update public.base_layouts
  set votes = votes + 1
  where id = p_layout
  returning votes into v_total;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), v_clan, 'vote', 'base_layouts', p_layout,
          jsonb_build_object('votes', v_total));

  return v_total;
end;
$$;

revoke execute on function vote_for_layout(uuid) from public;
grant execute on function vote_for_layout(uuid) to authenticated;


create or replace function unvote_layout(p_layout uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_clan  uuid;
  v_total integer;
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;

  select clan_id into v_clan
  from public.base_layouts
  where id = p_layout and deleted_at is null;

  if v_clan is null or v_clan not in (select public.auth_clan_ids()) then
    raise exception 'layout not found';
  end if;

  -- R4 — the row stays, marked. The partial unique index above is what lets the
  -- same member vote again later without colliding with this tombstone.
  update public.base_layout_votes
  set deleted_at = now()
  where layout_id = p_layout and user_id = auth.uid() and deleted_at is null;

  if found then
    -- greatest(...) rather than a bare subtraction. The counter is a cache, and
    -- a cache that can go negative renders "-1 votes" forever with no way for a
    -- member to correct it.
    update public.base_layouts
    set votes = greatest(votes - 1, 0)
    where id = p_layout
    returning votes into v_total;

    insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
    values (auth.uid(), v_clan, 'unvote', 'base_layouts', p_layout,
            jsonb_build_object('votes', v_total));
  else
    select votes into v_total from public.base_layouts where id = p_layout;
  end if;

  return v_total;
end;
$$;

revoke execute on function unvote_layout(uuid) from public;
grant execute on function unvote_layout(uuid) to authenticated;


comment on table base_layout_votes is
  'T8.5 — one live vote per member per layout. The partial unique index is the '
  'rule; base_layouts.votes is a cache the definer functions keep in step with '
  'it. Withdrawing a vote sets deleted_at (R4), and the index''s predicate is '
  'what lets the same member vote again afterwards.';

comment on function vote_for_layout(uuid) is
  'T8.5 — record a vote and bump the counter in one statement. Raises '
  '"layout not found" for a layout outside the caller''s clans, deliberately: '
  'a distinct "forbidden" would confirm that the id exists.';


-- ---------------------------------------------------------------------------
-- Verify:
--
--   -- a member of the clan can vote, once:
--   select vote_for_layout('<layout>');   -- 1
--   select vote_for_layout('<layout>');   -- 1, unchanged
--   select unvote_layout('<layout>');     -- 0
--   select unvote_layout('<layout>');     -- 0, never negative
--
--   -- a member of another clan cannot, and cannot tell it exists:
--   select vote_for_layout('<layout>');   -- ERROR: layout not found
--
--   -- and cannot reach the table directly:
--   insert into base_layout_votes (layout_id, user_id)
--   values ('<layout>', auth.uid());      -- permission denied for table
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 030_account_credentials.sql
-- ========================================================================

-- T10.1 — A username, and the flag that says a password exists.
--
-- Until now the only way in was a magic link, and the only way out was waiting
-- for the cookie to expire. That made a second account unreachable: sign in as
-- one member and you are that member until the session dies. T10 adds a real
-- sign-out and a password, so switching accounts is two clicks instead of an
-- inbox.
--
-- WHAT IS NOT HERE, AND MUST NEVER BE. There is no password column, no salt, no
-- hash. Passwords live in auth.users.encrypted_password, written only by
-- supabase.auth.updateUser({ password }) and read only by Supabase's own
-- sign-in. This project stores no credential material and adds no hashing
-- dependency; a password column here would be the single worst thing this
-- schema could grow.
--
-- The two columns below are the parts Supabase cannot hold for us: a display
-- handle, and a flag the setup gate can read (a session cannot see into
-- auth.users to ask "does this account have a password yet?").

alter table users
  add column username text
    check (username is null or username ~ '^[a-z0-9_]{3,20}$'),

  add column password_set_at timestamptz;

comment on column users.username is
  'Display handle, lowercase. NOT the sign-in identifier - Supabase Auth is keyed '
  'on email and signInWithPassword takes an email, so resolving a username to one '
  'would mean an endpoint mapping a handle to a real email address, callable by '
  'anyone holding the public anon key. Set at /account/setup (T10.5).';

comment on column users.password_set_at is
  'When the member set a password via auth.updateUser. The setup gate in '
  '(app)/layout.tsx reads this; it cannot read auth.users.encrypted_password, '
  'which is where the password itself actually lives.';

-- Case-insensitive, and only among live rows — the same shape as every other
-- uniqueness constraint in this schema, so a soft-deleted account does not hold
-- its handle hostage forever (R4: nothing is ever hard deleted).
create unique index users_username_key
  on users (lower(username))
  where deleted_at is null;


-- ---------------------------------------------------------------------------
-- No policy, and that is correct.
--
-- The next person to read this will look for a "member sets their own username"
-- policy and not find one. It already exists: 015's "own profile update" grants
-- update on users where id = auth.uid(), and 015's guard trigger
-- (guard_user_privilege_columns) blocks only is_platform_admin, status and
-- requested_clan_id. Both new columns therefore fall through as writable by
-- their owner and by nobody else, which is exactly the rule wanted.
--
-- Nor is the SELECT side widened. Usernames stay visible only to the member
-- themselves, the platform admin, and a leader reading their own pending
-- applicants — the three reads 006/013/015 already allow. Showing handles to
-- other members is a separate decision with a real disclosure surface, and
-- nothing in T10 needs it.
--
-- ONE DELIBERATE HOLE. password_set_at is writable by its owner, so a member
-- could set it without ever setting a password and skip /account/setup. That
-- harms nobody but them: the Sign in button then fails for their account and
-- they are back on the magic link. Adding it to the guard trigger would block
-- the setup action itself, which is the only thing that legitimately writes it.
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 031_own_players_policy.sql
-- ========================================================================

-- T11.1 — A member can read every base they own.
--
-- READ THE R3 ARGUMENT BELOW BEFORE CHANGING ANYTHING IN THIS FILE. It adds a
-- SELECT policy that is not filtered by clan, which is the exact shape R3 exists
-- to forbid. It is deliberate, and the reasoning is written out here rather than
-- in a commit message so that the next reader — human or assistant — finds it
-- attached to the policy instead of flagging the file and reverting it.
--
--
-- THE BUG THIS CLOSES
--
-- 016's link_verified_player() writes players.user_id for any number of tags,
-- so one account owning several villages has always worked at this level. But
-- `players` has exactly one SELECT policy, 006's
--
--     using (clan_id in (select auth_clan_ids()))
--
-- and auth_clan_ids() reads clan_roles. A member approved into clan A who then
-- verifies a second village sitting in clan B has that row's user_id set to
-- their own id, and is then forbidden to read it. They proved ownership with an
-- in-game token and the result of that write is invisible to them.
--
-- A write whose result cannot be read by the person who caused it is the same
-- defect class as the null-clan_id audit row recorded in IMPLEMENTATION.md's
-- note on definer functions: "writing rows nobody can read is worse than not
-- writing them." This is that, one table over.
--
--
-- WHY THIS IS NOT AN R3 VIOLATION
--
-- R3's substance is that a member must not see ANOTHER CLAN'S DATA. The policy
-- below returns only rows whose user_id is the caller — villages the caller
-- personally proved they own with an in-game API token (R8, T3.3). No row about
-- another person becomes visible to anybody.
--
-- The axis left unfiltered is clan; the filter that replaces it, user_id =
-- auth.uid(), is strictly NARROWER than the clan filter would have been, not
-- wider. A member of a fifty-person clan can read fifty players rows under
-- 006's policy and one or two under this one.
--
-- The codebase already names this exception in the other direction, and says so
-- in those words. repositories/members.ts's clanMovement() is "NOT filtered to
-- one clan — that is the point", and [clanTag]/player/[tag]/page.tsx calls it
-- "the deliberate exception". That read is unfiltered by clan and filtered by
-- player_id. This one is unfiltered by clan and filtered by user_id. Same
-- shape, one layer lower.
--
-- Two more properties keep the blast radius small:
--
--   Permissive SELECT policies are OR-ed by Postgres, so this only ever ADDS
--   rows. 006's "read own clan players" is untouched, and nothing that relied
--   on it changes behaviour.
--
--   It reaches `players` and nothing else. member_snapshots, wars, cwl_*,
--   war_*, base_layouts, clan_roles and clans all keep clan_id in (select
--   auth_clan_ids()). So a village in a clan the member holds no role in is
--   visible as a tag, a name and a town hall level, and nothing more — no
--   donations, no war history, not even the clan's NAME. That is precisely the
--   degraded state /account/bases/[tag] renders (T11.12), and it is why that
--   state is the honest design rather than a user-experience compromise.
--
-- REJECTED ALTERNATIVE: widening 006's policy to a join through clan_roles so
-- that owning a village in a clan implies reading that clan's players. That
-- grows the CLAN set, which is the R3 violation this is not. It would hand a
-- member the full roster of a clan nobody approved them into.
--
-- R3's discipline stays visible in application code regardless: basesForUser()
-- (T11.6) filters .eq("user_id", userId) explicitly. The policy is the net, as
-- 006's header insists — not a substitute for the filter.


-- ---------------------------------------------------------------------------
-- Which players does the current user own?
--
-- The mirror of 006's auth_clan_ids(), and security definer for the same
-- reason: the function reads `players`, and the policy below is itself a policy
-- ON `players`. Running as the definer bypasses RLS inside the body, which is
-- what stops that becoming infinite recursion — and it also means T11.3's
-- player_nicknames policies can call this without depending on which of
-- `players`' two SELECT policies happens to match.
--
-- set search_path = '' with fully qualified names, against a search_path
-- hijack, exactly as every other definer function in this schema does.
--
-- deleted_at is null, and NOT left_at is null. A member who left a clan still
-- owns the village — that is what T3.9 added left_at to record — and their own
-- history is the thing they are most likely to come here to read.
-- ---------------------------------------------------------------------------
create or replace function auth_owned_player_ids()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select id
  from public.players
  where user_id = auth.uid()
    and deleted_at is null
$$;

revoke execute on function auth_owned_player_ids() from public;
grant execute on function auth_owned_player_ids() to authenticated;


-- ---------------------------------------------------------------------------
-- The policy itself.
--
-- `to authenticated` so the anon role matches nothing, as every policy in 006
-- is. auth.uid() is null without a session, and `user_id = null` is never true,
-- so an anonymous request would read zero rows even without that clause — but
-- stating the role is the convention here and it makes the intent legible.
--
-- No new grant is needed: 006 already issued `grant select on all tables in
-- schema public to anon, authenticated`, and 014 set the default privilege for
-- tables added later. A grant is not access; RLS still decides which rows come
-- back.
-- ---------------------------------------------------------------------------
create policy "read own players" on players
  for select to authenticated
  using (user_id = auth.uid());


-- ---------------------------------------------------------------------------
-- No insert, update or delete policy on `players`, and there must never be one.
--
-- 016's header explains it at length: `players` holds GAME FACTS (R11), written
-- only by scripts/sync/ under the service role. The only member-initiated write
-- is link_verified_player(), a security definer function, precisely so that the
-- session itself keeps no write privilege. 016 documents a verification query
-- asserting has_table_privilege('authenticated', 'players', 'update') is FALSE.
-- That stays true after this file: a SELECT policy grants no writes.
--
-- The per-base nickname a member sets is a HUMAN DECISION and therefore lives
-- in its own table — see 033_player_nicknames.sql.
-- ---------------------------------------------------------------------------


-- ---------------------------------------------------------------------------
-- Sanity check after applying. As a member of clan A who owns a village in
-- clan B, with a session:
--
--   select count(*) from players;                 -- their own villages + clan A's roster
--   select count(*) from clans;                   -- clan A only, NOT clan B
--   select count(*) from clan_roles;              -- clan A only
--   select count(*) from member_snapshots;        -- clan A only
--
-- If the second query returns clan B, something else has been widened and this
-- file is not the cause. test/account-bases.test.ts asserts all four.
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 032_link_verified_player_v2.sql
-- ========================================================================

-- T11.2 — Verifying a second base must not re-route the first one's approval.
--
-- 016 is untouched. A migration that has been applied is never edited (§4), so
-- this replaces the function forward, the way 017 and 018 each replaced
-- approve_account(). Read 016's header first: everything it says about why this
-- is a definer function and why `players` stays select-only for a session is
-- still true, and none of it changes here.
--
--
-- THE BUG
--
-- 016 ends its write path with, unconditionally:
--
--     update public.users
--     set requested_clan_id = v_clan_id
--     where id = auth.uid() and deleted_at is null;
--
-- That was right when an account had one base, because it ran exactly once.
-- Phase 11 makes a second base an ordinary thing to add (Architecture.md §7.1
-- has said since the first draft that a member may own more than one player
-- account and that they may sit in different clans), and then it runs again —
-- overwriting a column whose whole purpose is to name the ONE clan whose leader
-- has been asked to approve this account.
--
-- Two distinct failures fall out of that, and each of the two new conditions
-- below prevents one of them.
--
--   requested_clan_id is null  —  A STILL-PENDING MEMBER IS SILENTLY RE-ROUTED.
--     They verify their main in clan A, and the leader of clan A now sees them
--     in the queue (013's "leaders read pending applicants to their clans"
--     filters on this column). They then verify their alt in clan B. The column
--     moves to clan B, they vanish out of clan A's queue, and the leader who
--     was already looking at them has no idea. Nothing reports it. First tag
--     wins is the only rule here that does not need a person to notice
--     something disappeared.
--
--   status = 'pending'  —  AN APPROVED ACCOUNT IS MADE TO LOOK LIKE AN
--     APPLICANT. For an approved account this column is history: approve_account()
--     requires status = 'pending' (018) and so can never run a second time, and
--     nothing else reads it. Rewriting it puts an already-approved member into
--     the pending queue of a leader of a clan they were never approved into —
--     visible to that leader, actionable by nobody, and impossible to explain
--     from the UI.
--
-- Both are `and` clauses on one statement rather than an `if` around it, so the
-- function's shape, its return contract and its audit row are all unchanged. The
-- audit row is still written on every link, which is what keeps a second base
-- an auditable event even though it moves no column on `users`.
--
--
-- WHAT IS DELIBERATELY NOT FIXED HERE
--
-- A pending member routed to the wrong clan cannot re-route themselves. That is
-- deliberate, not an oversight: self-service re-routing is exactly the
-- escalation 016's guard trigger was added to close, and re-opening it through
-- this function would hand back the same capability by a different door. With
-- one leader across the family the cost today is a message in game.
--
-- There is also NO "primary base" notion, and Phase 11 does not need one. The
-- dashboard lists every base with no privileged first, and "which clan am I
-- approved into" is answered by clan_roles, not by a base. If a default is ever
-- wanted the shape is a users.primary_player_id column — owner-writable for
-- free, like username in 030 — and not a flag on player_nicknames, which would
-- need a per-account partial unique index and a rule for what happens when the
-- primary base leaves the family.


create or replace function link_verified_player(p_tag text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player_id uuid;
  v_clan_id   uuid;
  v_owner     uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason', 'no_session');
  end if;

  if p_tag is null then
    return jsonb_build_object('ok', false, 'reason', 'not_a_member');
  end if;

  -- clan_id is not null, so a player kept for history after leaving all three
  -- clans (T3.9 sets left_at) cannot be used to gain access. left_at is checked
  -- too: a departed member must be re-approved rather than walking back in.
  select id, clan_id, user_id
    into v_player_id, v_clan_id, v_owner
  from public.players
  where tag = p_tag
    and deleted_at is null
    and left_at is null
    and clan_id is not null;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_a_member');
  end if;

  -- Tag theft. The token proved the CALLER owns this game account, so a row
  -- already pointing at somebody else means either an account changed hands or
  -- an attempt to take over a teammate's profile. Neither is resolvable here —
  -- it raises so /api/verify can surface it and a leader can look into it.
  --
  -- Re-verifying a tag the CALLER already owns is not theft and falls through:
  -- the token rotates every time it is viewed in game, so a member re-running
  -- verification on their own base is an ordinary thing to do, and the update
  -- below is idempotent for them.
  if v_owner is not null and v_owner <> auth.uid() then
    raise exception 'player already linked to another account';
  end if;

  perform set_config('clanbridge.bootstrap', 'on', true);

  update public.players
  set verified = true,
      user_id  = auth.uid()
  where id = v_player_id;

  -- THIS is what puts the applicant in front of the right leader. 013's
  -- "leaders read pending applicants to their clans" policy filters on
  -- requested_clan_id, and 016's guard trigger refuses a direct write to it — so
  -- this function is still the only way it can ever be set, and a member cannot
  -- nominate themselves into a clan they have no account in.
  --
  -- T11.2 — the two clauses after `deleted_at is null` are the whole of this
  -- migration. See the header: the first keeps a pending applicant in the queue
  -- of the leader already asked, the second stops an approved account being
  -- redressed as an applicant. Everything else in this function is 016's.
  update public.users
  set requested_clan_id = v_clan_id
  where id = auth.uid()
    and deleted_at is null
    and status = 'pending'
    and requested_clan_id is null;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), v_clan_id, 'verify', 'players', v_player_id,
          jsonb_build_object('verified', true, 'tag', p_tag));

  return jsonb_build_object(
    'ok', true,
    'player_id', v_player_id,
    'clan_id', v_clan_id);
end;
$$;

-- Re-stated because create or replace does not re-run 016's grants if the
-- signature ever changes, and because a reader of this file should not have to
-- open 016 to learn who may call it.
revoke execute on function link_verified_player(text) from public;
grant execute on function link_verified_player(text) to authenticated;

comment on function link_verified_player(text) is
  'T3.3/T11.2 - links a verified player tag to auth.uid(). Routes the account to '
  'that clan''s leader for approval on the FIRST link only, so adding a second '
  'base neither re-routes a pending applicant nor redresses an approved account '
  'as one. The only write path to players from a session (R11).';

-- ========================================================================
-- 033_player_nicknames.sql
-- ========================================================================

-- T11.3 — A member names their own base.
--
-- A member with two villages sees two rows that differ only by tag and town hall
-- level. The in-game names are often near-identical ("Shashi" and "Shashi2"),
-- and the tag is the thing nobody remembers. So the member gets to write a label
-- on each: "main", "alt", "the rushed one".
--
--
-- WHY THIS IS A TABLE AND NOT A COLUMN ON `players`
--
-- R11. `players` holds GAME FACTS, written only by scripts/sync/, and a session
-- has SELECT on it and nothing else — 016's header explains why at length, and
-- 016 ships a verification query asserting that
-- has_table_privilege('authenticated', 'players', 'update') is FALSE. A nickname
-- is the opposite kind of data: a HUMAN DECISION, written only through the
-- application, never touched by a job. The two kinds live in separate tables
-- with exactly one writer each, which is the whole of R11.
--
-- The rejected version is a `nickname` column on `players` plus an update policy
-- with a WITH CHECK narrowing it to one column. That hands a session write
-- access to the game-fact table and then relies on an expression to keep it away
-- from name, clan_id and th_level. 016 already refused that trade for
-- verification, which needed two columns rather than one.
--
--
-- WHY PLAIN POLICIES AND NOT A DEFINER FUNCTION
--
-- The audited-write convention in src/repositories/README.md is for writes with
-- a clan. This one has no clan, and the recorded exception applies: rows a
-- member owns, with no clan, use plain policies, because audit_log's read policy
-- is `clan_id in (select auth_leader_clan_ids())` and `null in (...)` is never
-- true. Writing rows nobody can read is worse than not writing them. 023's
-- notification_preferences is the precedent and this table follows it exactly.
--
-- WOULD A DENORMALISED clan_id MAKE THE AUDIT ROW READABLE? Yes, and it is still
-- the wrong trade, for three reasons in descending order of weight:
--
--   1. A base's clan CHANGES. That is what players.clan_id and left_at exist
--      for. A clan_id copied onto a human-decision row is either stale, or kept
--      fresh by a sync job writing a human-decision table — which is precisely
--      the R11 bug. There is no third option.
--   2. audit_log earns its value by being short. Its other entries are
--      approvals, bonus awards and target assignments. "A member renamed their
--      own base from main to alt" is noise in that log.
--   3. The base may sit in a clan with NO leader on this platform — the
--      cross-clan case this whole feature exists for (031) — so the audit row
--      would be unreadable anyway.
--
-- RECORDED HOLE: nickname changes are not audited. Nobody but the owner can read
-- or write one, so the blast radius is a label on their own village. If it ever
-- matters, the fix is widening audit_log's read policy — not a clan_id here.


-- ---------------------------------------------------------------------------
-- player_nicknames
--
-- set_by, NOT user_id, and the distinction is load-bearing. Ownership lives on
-- players.user_id and is the single source of truth; this column records who
-- wrote the label. A second copy of ownership is a second thing that can be
-- wrong, and 016 raises rather than reassigning a linked base, so the copy could
-- only ever drift away from the truth.
--
-- The check constraint pairs with nicknameProblem() in src/lib/nickname.ts. The
-- constraint is the one that is actually enforced; the TypeScript is the one
-- that produces a sentence a member can act on. src/lib/account.ts's header
-- states that division and this follows it.
--
-- 24 characters because it sits beside an in-game name in a list, and the game
-- itself caps a player name at 15. Anything longer is a sentence, not a label.
-- ---------------------------------------------------------------------------
create table player_nicknames (
  id         uuid primary key default gen_random_uuid(),
  player_id  uuid not null references players (id) on delete restrict,
  nickname   text not null,
  set_by     uuid not null references users (id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz,
  deleted_at timestamptz,

  constraint player_nicknames_shape check (
    nickname = btrim(nickname)
    and char_length(nickname) between 1 and 24
    and nickname !~ '[\n\r\t]'
  )
);

-- ---------------------------------------------------------------------------
-- ONE NICKNAME PER BASE, AND THE INDEX IS FULL RATHER THAN PARTIAL.
--
-- This is the opposite of base_layout_votes (028) and notification_preferences
-- (023), which both use `where deleted_at is null`, so it needs justifying.
--
-- A partial unique index cannot be inferred by ON CONFLICT unless the statement
-- names the predicate, and an INSERT has no WHERE to name it with. 028 hit
-- exactly this and worked around it with two statements inside a definer
-- function, saying so at its lines 173-175. There is no definer function here to
-- hide two statements inside, and two statements issued from a Server Action is
-- a race that the unique index would then reject — the member sees a constraint
-- violation for pressing Save twice.
--
-- With a FULL index, setting a nickname is one idempotent statement that also
-- revives a cleared one:
--
--     upsert({ player_id, nickname, set_by, deleted_at: null },
--            { onConflict: "player_id" })
--
-- and clearing it is `update ... set deleted_at = now()` (R4 — the row stays).
-- The cost is that the tombstone occupies the slot, which is exactly what makes
-- the revival possible. There is one row per base for the life of the base and
-- its history is the row's own updated_at, not a pile of superseded rows.
-- ---------------------------------------------------------------------------
create unique index player_nicknames_player_key on player_nicknames (player_id);

create trigger player_nicknames_set_updated_at
  before update on player_nicknames
  for each row execute function set_updated_at();


-- ---------------------------------------------------------------------------
-- RLS. Owner-scoped through 031's auth_owned_player_ids(), never by clan.
--
-- A nickname is private to the member who wrote it. Clanmates do not see it, and
-- that is deliberate rather than unfinished: showing one member's label for
-- their own village to the rest of the clan is a separate decision with its own
-- disclosure question, and 030 makes the identical argument about not widening
-- username visibility. Recorded as a hole, not half-closed.
--
-- `set_by = auth.uid()` on both write policies, so a member cannot attribute a
-- label to somebody else. The player_id clause already restricts which base;
-- this restricts who the row claims wrote it.
-- ---------------------------------------------------------------------------
alter table player_nicknames enable row level security;

create policy "read own base nicknames" on player_nicknames
  for select to authenticated
  using (player_id in (select auth_owned_player_ids()));

create policy "name your own base" on player_nicknames
  for insert to authenticated
  with check (
    player_id in (select auth_owned_player_ids())
    and set_by = auth.uid()
  );

create policy "rename your own base" on player_nicknames
  for update to authenticated
  using (player_id in (select auth_owned_player_ids()))
  with check (
    player_id in (select auth_owned_player_ids())
    and set_by = auth.uid()
  );

-- No delete policy. R4, and migrations.test.ts asserts globally that no table
-- anywhere has one.


-- ---------------------------------------------------------------------------
-- R11 AS A PRIVILEGE, NOT A COMMENT.
--
-- THE REVOKE BELOW IS THE OPERATIVE LINE AND IT IS NOT REDUNDANT. 014 issued
--
--     alter default privileges in schema public
--       grant select, insert, update on tables to service_role;
--
-- so every table created after it is BORN WRITABLE by the sync jobs. Granting
-- only select here would change nothing at all — the default privilege has
-- already been applied by the time this statement runs. 024 records the same
-- finding in its own words, having been written in the belief that a narrow
-- grant was a narrow permission; a test caught it.
--
-- Still readable by service_role, deliberately: a future job that needs to know
-- what a member called their base (a notification addressed to "your alt", say)
-- can read it, and the read grant is also what keeps migrations.test.ts's "can
-- read every table" assertion true.
-- ---------------------------------------------------------------------------
grant select, insert, update on player_nicknames to authenticated;  -- never delete (R4)
grant select on player_nicknames to service_role;
revoke insert, update on player_nicknames from service_role;

comment on table player_nicknames is
  'T11.3 - the member''s own label for one of their villages, so an account with '
  'two bases can tell them apart. A HUMAN DECISION (R11): written only through '
  'the application by the owner, never by a sync job. Defaults to nothing, and '
  'the UI falls back to players.name.';

-- ========================================================================
-- 034_user_avatar.sql
-- ========================================================================

-- T11.4 — One profile picture per account.
--
-- The shell has always labelled a member by their username, and 030 added that
-- handle so somebody with two accounts could tell which one they were signed in
-- as. A picture is the same problem one step further: it is the thing a member
-- recognises before they have read anything.
--
-- PER ACCOUNT, NOT PER BASE, and that is a decision rather than a simplification.
-- A member with three villages is still one person, and a face repeated three
-- times down a list carries no information. What distinguishes the villages is
-- the label in 033; what distinguishes the ACCOUNT is this.
--
-- The column holds a PATH inside the `avatars` Storage bucket, never a URL. The
-- bucket is private, so a usable address is a signed URL minted per request and
-- valid for an hour — storing one would mean storing something that stops
-- working. 035 creates the bucket and its policies.
--
-- NAMED avatar_path, NOT avatar_url, on purpose. base_layouts.image_url holds a
-- path and is named url, and the consequence is that
-- [clanTag]/layouts/page.tsx has to open with a paragraph explaining that its
-- image_url is not a URL. Fixing forward means not repeating the name. If both
-- ever need to be read together, this is the one that is telling the truth.

alter table users
  add column avatar_path text
    check (avatar_path is null or avatar_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.jpg$');

comment on column users.avatar_path is
  'Object path inside the private `avatars` bucket (035), NOT a URL - the bucket '
  'is private, so an address is a signed URL minted per request. Shaped '
  '<user_id>/<uuid>.jpg, and the leading segment is load-bearing: the storage '
  'policies check (storage.foldername(name))[1] against auth.uid(). One picture '
  'per account, never per base; the per-base label is player_nicknames (033).';


-- ---------------------------------------------------------------------------
-- No policy, and that is correct — the same answer 030 gives, for the same
-- reason, restated because the next reader will look for one and not find it.
--
-- 015 granted `insert, update on users to authenticated` and added "own profile
-- update" (using/with check id = auth.uid()). 016's guard trigger
-- (guard_user_privilege_columns) raises only for is_platform_admin, status and
-- requested_clan_id. So this column is writable by its owner and by nobody else,
-- which is exactly the rule wanted, and adding a policy for it would be adding a
-- second expression that has to agree with the first.
--
-- The SELECT side is not widened either. An avatar_path is visible to the member
-- themselves, the platform admin, and a leader reading their own pending
-- applicants — the three reads 006/013/015 already allow. Showing a member's
-- picture to their clanmates is a SEPARATE decision, and a bigger one than
-- showing a handle: it needs a storage read policy letting one member sign
-- another member's object, which is a real disclosure surface. 035 therefore
-- keeps the bucket owner-only. Recorded as a hole, not half-closed.
--
-- ONE DELIBERATE HOLE, in 030's exact shape. A member can write any
-- correctly-shaped string into their own avatar_path, including a path belonging
-- to another user. It buys them nothing: the signed URL is minted under THEIR
-- session, and 035's storage policy refuses to sign a path whose first segment
-- is not their own id. The only outcome is a broken image on their own page.
-- Adding the column to the guard trigger would block the action that
-- legitimately writes it, which is 030's identical argument about
-- password_set_at.
--
-- The check constraint is shape, not authorisation. It exists so a malformed
-- value fails at the write rather than becoming a broken image discovered later,
-- and because a column that can hold anything eventually holds a full URL. The
-- authorisation is the storage policy, and it is enforced where the bytes are.
-- ---------------------------------------------------------------------------


-- ---------------------------------------------------------------------------
-- Sanity check after applying:
--
--   select avatar_path from users where id = auth.uid();
--
--   -- refused by the constraint, all four:
--   update users set avatar_path = 'https://example.com/a.jpg' where id = auth.uid();
--   update users set avatar_path = 'a.jpg'                     where id = auth.uid();
--   update users set avatar_path = '../secrets/a.jpg'          where id = auth.uid();
--   update users set avatar_path = '<uuid>/<uuid>.png'         where id = auth.uid();
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 036_player_progress.sql
-- ========================================================================

-- T11B.4 — player_progress: how far along each village is, one row a day.
--
-- Written by scripts/sync/players.ts from /players/{tag}. A GAME FACT (R11):
-- only the sync job writes it and no person ever edits it.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- ONE ROW PER PLAYER PER DAY, WITH THE UNITS AS JSONB
--
-- A tall table — one row per unit per player per day — is rejected on
-- arithmetic: about 150 units x 150 players x 365 days is over 8 M rows a year
-- against a 500 MB tier. That is the same calculation 007 used to justify its
-- hourly bucket. Nothing queries a single unit across players, so the tall shape
-- buys nothing it would cost.
--
-- `captured_day` needs `at time zone 'UTC'` for the reason 007 records:
-- date_trunc() over a timestamptz depends on the session TimeZone, so it is not
-- immutable, and PostgreSQL refuses it in a generated column.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- THE CAP IS STORED, NOT RECOMPUTED — THE NON-OBVIOUS PART
--
-- Each element of `units` is
--
--   { name, village, group, level, apiMax, cap, capKnown }
--
-- where `cap` is the Town Hall cap from src/data/game/ AT THE TIME OF CAPTURE.
-- Supercell raises caps with every update. Storing only levels would make every
-- historical row silently re-score itself against today's caps the moment the
-- game data is refreshed, so a base that was maxed for its Town Hall in March
-- would read as behind in June. Nothing would report it, because both numbers
-- look plausible. That is the same class of bug writeStart()'s ignoreDuplicates
-- note in scripts/sync/clan-games.ts describes.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- R3 — TWO READ POLICIES, OR-ED
--
-- `clan_id` is the clan the village was in WHEN CAPTURED, and the clan policy
-- is 006's shape: a leader reads the progress of villages captured while they
-- were in the leader's clan.
--
-- The owner policy goes through 031's auth_owned_player_ids() and inherits 031's
-- R3 argument in full: it returns only rows about villages whose user_id is the
-- caller, which is strictly NARROWER than a clan filter, and permissive policies
-- only ever add rows. It is what lets a member see the details of a village that
-- sits in a clan they hold no role in, or in no platform clan at all — which is
-- why `clan_id` is nullable. players.ts snapshots owned villages that have left
-- every platform clan, so their owner's page keeps filling in.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- R5 — APPEND-ONLY AS A PRIVILEGE, NOT A CONVENTION
--
-- The sync job inserts with ON CONFLICT DO NOTHING against the unique key. 014
-- set default privileges that give service_role INSERT and UPDATE on every table
-- created after it, so the REVOKE below is the line that makes a historical row
-- impossible to rewrite, rather than merely unusual. 024 and 033 record the same
-- finding.

create table player_progress (
  id               uuid primary key default gen_random_uuid(),
  player_id        uuid not null references players (id) on delete restrict,
  clan_id          uuid references clans (id) on delete restrict,
  captured_at      timestamptz not null default now(),

  th_level         smallint,
  th_weapon_level  smallint,
  bh_level         smallint,
  units            jsonb not null default '[]'::jsonb,

  created_at       timestamptz not null default now(),
  deleted_at       timestamptz,

  captured_day     timestamp generated always as
                     (date_trunc('day', captured_at at time zone 'UTC')) stored,

  constraint player_progress_units_array check (jsonb_typeof(units) = 'array'),

  unique (player_id, captured_day)
);

-- Every read is "this player, newest first" (latestProgress) or "this player
-- over a window" (progressHistory).
create index player_progress_player_idx
  on player_progress (player_id, captured_at desc)
  where deleted_at is null;

alter table player_progress enable row level security;

create policy "read own clan player progress" on player_progress
  for select to authenticated
  using (clan_id in (select auth_clan_ids()));

create policy "read own base progress" on player_progress
  for select to authenticated
  using (player_id in (select auth_owned_player_ids()));

grant select on player_progress to anon, authenticated;
grant select, insert on player_progress to service_role;
revoke update, delete on player_progress from service_role;

comment on table player_progress is
  'T11B.4 - one daily reading per village of its hero, equipment, pet, troop, '
  'siege and spell levels, each with the Town Hall cap applied at capture. A GAME '
  'FACT (R11): written only by scripts/sync/players.ts, append-only (R5).';


-- ---------------------------------------------------------------------------
-- sync_log learns the new job type (R9).
--
-- 005's check was declared inline and unnamed, so PostgreSQL named it
-- sync_log_job_type_check. Dropped and re-added in one migration, so there is
-- no window in which job_type is unconstrained.
-- ---------------------------------------------------------------------------
alter table sync_log drop constraint sync_log_job_type_check;
alter table sync_log add constraint sync_log_job_type_check
  check (job_type in ('clans', 'cwl', 'war', 'raids', 'clan-games', 'players', 'backup'));

-- ========================================================================
-- 037_family_cwl_history.sql
-- ========================================================================

-- T11C.1 — family_cwl_history(): a village's CWL record from EVERY platform clan.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- THE PROBLEM, AS FOUND
--
-- SK FLASH (#GJUUGRVCU) played 14 CWL wars across 2026-08 and 2026-09 in DH CWL
-- ONLY, the family's CWL clan, then returned to Dark Hell. Its report said "No
-- CWL record for this member in Dark Hell yet", for two independent reasons:
--
--   1. The report asked only the CURRENT clan. seasonHistoryForClan() walked
--      one clan's cwl_seasons, so a season played anywhere else was never read.
--      The data was intact: players.tag is unique, so cwl_war_members.player_id
--      still points at the same row after a move.
--
--   2. RLS would have hidden it anyway. 006's and 019's CWL policies admit a
--      season only to a viewer holding a role in the clan that OWNS it, and the
--      owner's only clan_roles row was Dark Hell.
--
-- Members moving between the family's clans is the ordinary case here, not an
-- edge: DH CWL ONLY exists to play CWL for the others. A CWL record that
-- disappears when a member goes home is wrong on every page that shows one.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- R3 — A DELIBERATE, NARROW EXCEPTION. READ THIS BEFORE TOUCHING IT.
--
-- The decision (Phase 11C) is FAMILY-WIDE visibility: anyone holding a role in
-- any platform clan may see any village's CWL season totals from every platform
-- clan. That is a loosening of R3, and it is made here, in one function, rather
-- than by widening four tables' policies, because of what each would expose.
--
-- Widening the policies on cwl_seasons, cwl_wars, cwl_war_members and
-- cwl_attacks would hand every member every clan's entire CWL tree: opponents,
-- results, destruction, every attack by every player. None of the pages need it.
--
-- THIS RETURNS, per requested player, per clan, per season:
--   clan id, tag and name (public in game), the season, wars rostered, attacks
--   used, stars.
--
-- IT DOES NOT RETURN: opponents, war results, destruction, map positions, attack
-- order, defenders, or anything about any player who was not asked for. The four
-- tables' own policies are untouched, so a direct select of another clan's
-- cwl_attacks still returns zero rows — test/family-cwl-history.test.ts asserts
-- exactly that, beside the totals it asserts are visible.
--
-- WHO IS ANSWERED:
--   - a caller holding at least one live clan_roles row — a family member;
--   - for their OWN villages, a caller with no role at all, through 031's
--     auth_owned_player_ids() (a pending member linking a base);
--   - the service role, so a sync job or an operator can check it.
-- Anyone else — anon, a signed-in account with no role and no village — gets
-- zero rows, not an error, which is how every read in this project says no.
--
-- Precedents: 031, which widened `players` by owner, and clanMovement() in
-- repositories/members.ts, the other read deliberately not confined to one clan.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- SEMANTICS MATCH THE FUNCTION IT REPLACES
--
-- seasonHistoryForClan() in repositories/cwl.ts, pinned by
-- test/cwl-history-repo.test.ts:
--   - driven from the ROSTER (cwl_war_members), never from the attacks — a player
--     who was in a war and did nothing is exactly who a leader is looking for;
--   - an attack by somebody not on that war's roster is not counted;
--   - soft-deleted rows at every level are ignored (R4);
--   - newest season first.
--
-- plpgsql rather than sql only for the input cap, which needs RAISE. 500 is far
-- above the largest real caller (the roster builder's pool) and bounds a crafted
-- call from a signed-in session.

create or replace function family_cwl_history(p_player_ids uuid[])
returns table (
  player_id     uuid,
  clan_id       uuid,
  clan_tag      text,
  clan_name     text,
  season        text,
  wars_rostered integer,
  attacks_used  integer,
  stars         integer
)
language plpgsql
stable
security definer
set search_path = ''
as $$
#variable_conflict use_column
begin
  if coalesce(cardinality(p_player_ids), 0) > 500 then
    raise exception 'family_cwl_history: at most 500 players per call, got %',
      cardinality(p_player_ids)
      using errcode = '22023';
  end if;

  return query
  with allowed as (
    -- The guard. Family members see every requested player; anyone else only
    -- their own villages; the service role sees all.
    select requested.id
    from unnest(coalesce(p_player_ids, '{}'::uuid[])) as requested(id)
    where exists (select 1 from public.auth_clan_ids())
       or current_setting('role', true) = 'service_role'
       or requested.id in (select public.auth_owned_player_ids())
  ),
  rostered as (
    select m.player_id, m.war_id, s.clan_id, s.season
    from public.cwl_war_members m
    join public.cwl_wars w
      on w.id = m.war_id and w.deleted_at is null
    join public.cwl_seasons s
      on s.id = w.season_id and s.deleted_at is null
    where m.deleted_at is null
      and m.player_id in (select id from allowed)
    group by m.player_id, m.war_id, s.clan_id, s.season
  ),
  per_war as (
    select
      r.player_id,
      r.clan_id,
      r.season,
      r.war_id,
      count(a.id)                 as attacks,
      coalesce(sum(a.stars), 0)   as stars
    from rostered r
    left join public.cwl_attacks a
      on a.war_id = r.war_id
     and a.player_id = r.player_id
     and a.deleted_at is null
    group by r.player_id, r.clan_id, r.season, r.war_id
  )
  select
    pw.player_id,
    pw.clan_id,
    c.tag,
    c.name,
    pw.season,
    count(*)::integer            as wars_rostered,
    sum(pw.attacks)::integer     as attacks_used,
    sum(pw.stars)::integer       as stars
  from per_war pw
  join public.clans c on c.id = pw.clan_id
  group by pw.player_id, pw.clan_id, c.tag, c.name, pw.season
  order by pw.season desc, c.name;
end;
$$;

revoke execute on function family_cwl_history(uuid[]) from public;
grant execute on function family_cwl_history(uuid[]) to authenticated, service_role;

comment on function family_cwl_history(uuid[]) is
  'T11C.1 - per-player CWL season totals from every platform clan (family-wide, '
  'a deliberate R3 exception). Totals and clan name only; the CWL tables'' own '
  'policies are unchanged. Returns nothing to a caller with no clan role, except '
  'for their own villages.';


-- ---------------------------------------------------------------------------
-- Verify:
--
--   -- as a member of clan A, for a village that played CWL in clan B:
--   select * from family_cwl_history(array['<player>']::uuid[]);  -- clan B rows
--   select count(*) from cwl_attacks;  -- still ONLY clan A's attacks
--
--   -- as a signed-in account with no clan role and no village:
--   select count(*) from family_cwl_history(array['<player>']::uuid[]);  -- 0
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 038_family_directory.sql
-- ========================================================================

-- T12.1 — the VISITOR tier: every platform clan's overview and its roster,
-- readable by anyone holding a role in any platform clan.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- R3 — THE SECOND DELIBERATE EXCEPTION. 037 IS THE FIRST. READ BOTH.
--
-- The decision: an approved account may READ every platform clan's overview and
-- its member roster, and search that roster, even in a clan it holds no role in.
-- Everything else about another clan — war, CWL, raids, clan games, polls,
-- notices, layouts, donations, snapshots, audit — stays exactly as private as it
-- is today.
--
-- Made HERE, in two functions, and NOT by widening the SELECT policies on
-- `clans` and `players`. Three reasons, in order of weight:
--
--   1. Architecture.md §7.3 says so in as many words, about 037's exception:
--      "Widen that function's output, not the tables' policies, if more is ever
--      needed." This is the "more".
--
--   2. Widening `players` would hand every member every clan's `verified` flag
--      and `user_id` — the link between a village and a person — and would
--      silently widen everything that joins through players. These functions
--      return seven columns and six columns respectively, and nothing else.
--
--   3. test/authorisation.test.ts and test/migrations.test.ts both assert that a
--      bare `select from clans` and `select from players` return ONE clan's
--      rows. Those assertions ARE the T3.7 net. They stay green after this file,
--      and test/family-directory.test.ts asserts that fact beside the new
--      access, exactly as test/family-cwl-history.test.ts does for 037.
--
-- WHAT IS RETURNED:
--   family_clans()          id, tag, name, badge_url, level, war_league, member_count
--   family_clan_roster()    clan_id, player_id, tag, name, th_level, clan_role, left_at
--
-- WHAT IS NOT: donations, trophies, snapshots, verified, user_id, wars, CWL,
-- raids, clan games, polls, notices, layouts, and anything at all about a clan
-- that has been soft-deleted.
--
-- WHO IS ANSWERED — the same guard 037 uses, verbatim:
--   * a caller holding at least one live clan_roles row (a family member), or
--   * the service role.
-- Anyone else gets zero rows rather than an error, which is how every read in
-- this schema says no. A PENDING account therefore still sees nothing: it has no
-- clan_roles row, so T3.8's gate is enforced here by the same mechanism that
-- enforces it everywhere else, without this file knowing about `status`.
--
-- WHY ONE ROSTER FUNCTION AND NOT TWO. The member directory asks for one clan
-- with no term; /search asks for every clan with a term. Those are the same
-- question — searchPlayers() (repositories/members.ts) already treats a search
-- as the roster filtered — and splitting them would mean two places that must
-- agree about which six columns a visitor may see.
--
-- NOT ADDED HERE: auth_elder_clan_ids(). See the closing note.
-- ─────────────────────────────────────────────────────────────────────────────


-- ---------------------------------------------------------------------------
-- Every platform clan, as the clan directory and a visitor's overview need it.
--
-- `order by tag` matches visibleClans() (lib/clans.ts), so the two lists read in
-- the same order wherever they are shown near each other.
--
-- level and member_count are smallint on the table (020) and are cast to integer
-- so the declared result type cannot drift from the column type. A mismatch
-- there is a runtime "structure of query does not match function result type",
-- which is a 500 on a page rather than anything a build would catch.
--
-- `language sql` and not plpgsql: there is no input to cap and no branch. 037 is
-- plpgsql only because it needs RAISE.
-- ---------------------------------------------------------------------------
create or replace function family_clans()
returns table (
  id           uuid,
  tag          text,
  name         text,
  badge_url    text,
  level        integer,
  war_league   text,
  member_count integer
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    c.id,
    c.tag,
    c.name,
    c.badge_url,
    c.level::integer,
    c.war_league,
    c.member_count::integer
  from public.clans c
  where c.deleted_at is null
    and (
      exists (select 1 from public.auth_clan_ids())
      or current_setting('role', true) = 'service_role'
    )
  order by c.tag
$$;

revoke execute on function family_clans() from public;
grant execute on function family_clans() to authenticated, service_role;

comment on function family_clans() is
  'T12.1 - every platform clan''s overview (family-wide, a deliberate R3 '
  'exception alongside 037). Seven columns, no member data. Returns nothing to '
  'a caller holding no clan role anywhere. The clans table''s own policies are '
  'unchanged: a direct select still returns only the caller''s own clans.';


-- ---------------------------------------------------------------------------
-- The rosters of the named clans, optionally filtered by name or tag.
--
-- p_clan_ids IS REQUIRED AND HAS NO "null means every clan" SPELLING. R3 says
-- the query is the mechanism and the policy is the net, and a call with no clan
-- in it has no mechanism at all — the argument repositories/members.ts makes at
-- length about why searchPlayers() issues one query per clan rather than one
-- unscoped one. The caller gets its list from family_clans(), never from tags
-- written down somewhere.
--
-- plpgsql rather than sql, for the cardinality cap and the tag branch. Same
-- shape as 037.
-- ---------------------------------------------------------------------------
create or replace function family_clan_roster(
  p_clan_ids         uuid[],
  p_term             text    default null,
  p_include_departed boolean default false
)
returns table (
  clan_id   uuid,
  player_id uuid,
  tag       text,
  name      text,
  th_level  integer,
  clan_role text,
  left_at   timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_term text := nullif(btrim(coalesce(p_term, '')), '');
  v_tag  text := null;
begin
  -- Far above the largest real caller — the family is a handful of clans — and
  -- it bounds a crafted call from a signed-in session. 037 caps the same way.
  if coalesce(cardinality(p_clan_ids), 0) > 20 then
    raise exception 'family_clan_roster: at most 20 clans per call, got %',
      cardinality(p_clan_ids)
      using errcode = '22023';
  end if;

  -- The guard, before any row is touched. Zero rows, not an error.
  if not (
    exists (select 1 from public.auth_clan_ids())
    or current_setting('role', true) = 'service_role'
  ) then
    return;
  end if;

  -- A TAG IS MATCHED EXACTLY AND NEVER BY PREFIX, and it matters more here than
  -- in searchPlayers(): this function answers for clans the caller holds no role
  -- in, so a prefix match would be a way to enumerate the family's player tags a
  -- page at a time. A partial tag is not a meaningful query in any case.
  if v_term like '#%' then
    v_tag := upper(v_term);
  end if;

  return query
  select
    p.clan_id,
    p.id,
    p.tag,
    p.name,
    p.th_level::integer,
    p.clan_role,
    p.left_at
  from public.players p
  where p.clan_id = any (coalesce(p_clan_ids, '{}'::uuid[]))
    and p.deleted_at is null
    -- R4 keeps a departed member's every row; the directory simply does not list
    -- them unless asked (T0.11).
    and (p_include_departed or p.left_at is null)
    -- A soft-deleted clan's roster must not reappear through this door.
    and exists (
      select 1 from public.clans c
      where c.id = p.clan_id and c.deleted_at is null
    )
    and (
      v_term is null
      or (v_tag is not null and p.tag = v_tag)
      -- %, _ and \ are LIKE metacharacters. Somebody searching for a name that
      -- contains one wants a literal match, and a bare '%' must not become
      -- "list the whole clan". Backslash is LIKE's default escape character, so
      -- escaping it first is what keeps the other two escapes intact.
      or (
        v_tag is null
        and p.name ilike
          '%' ||
          replace(replace(replace(v_term, '\', '\\'), '%', '\%'), '_', '\_') ||
          '%'
      )
    )
  order by p.name
  -- A ceiling, not a page. The family is a few hundred players; this exists so a
  -- crafted call cannot ask for every row in the table at once.
  limit 2000;
end;
$$;

revoke execute on function family_clan_roster(uuid[], text, boolean) from public;
grant execute on function family_clan_roster(uuid[], text, boolean)
  to authenticated, service_role;

comment on function family_clan_roster(uuid[], text, boolean) is
  'T12.1 - name, tag, town hall and in-game role for the members of the named '
  'platform clans, optionally filtered (family-wide, a deliberate R3 exception '
  'alongside 037). No donations, snapshots, verified flag or user_id. Tags match '
  'exactly, never by prefix. Returns nothing to a caller holding no clan role.';


-- ---------------------------------------------------------------------------
-- WHAT IS DELIBERATELY NOT IN THIS FILE: auth_elder_clan_ids().
--
-- Migrations 010 and 021 set the convention that a new tier gets a NEW helper
-- rather than a widened old one — widening auth_leader_clan_ids() would silently
-- hand co-leaders the audit log. By that convention an elder tier would get its
-- helper here. It does not, and the reason is not that it was forgotten.
--
--   The helper alone changes nothing. To have teeth it would have to REPLACE
--   auth_clan_ids() in the SELECT policies on cwl_seasons, cwl_wars,
--   cwl_attacks, cwl_bonuses, cwl_war_members, raid_seasons, raid_participants,
--   clan_games and clan_games_scores. That is a NARROWING, and permissive
--   policies are OR-ed together — so a stricter second policy grants nothing and
--   the existing one has to be dropped. No migration in this tree has ever
--   contained DROP POLICY or ALTER POLICY; all thirty-seven are additive. A
--   narrowing that fails OPEN when the drop is forgotten is the worst available
--   failure mode for a permission change.
--
--   And the narrowing would be wrong for this product's own pages.
--   repositories/player-report.ts reads clan_games_scores and raid_participants
--   to build the player profile, which the member tier is explicitly meant to
--   keep. An elder-only policy on those tables blanks two panels of a page every
--   member is supposed to see.
--
-- So elder is equal to member in SQL today, deliberately and on the record. The
-- elder tier is a routing and rendering decision in src/lib/visibility.ts, in the
-- same way "Worth a look" is: advice computed from rows the member may already
-- read. test/family-directory.test.ts asserts that equality, so that nobody
-- later assumes a net which is not there.
--
-- IF IT IS EVER WANTED, the order is: move the profile's raid and clan-games
-- reads behind definer functions first, then add the helper, then drop and
-- recreate those nine policies. Not the other way round.
-- ---------------------------------------------------------------------------


-- ---------------------------------------------------------------------------
-- Verify by hand, as a member of clan A:
--
--   select count(*) from family_clans();                          -- every clan
--   select count(*) from clans;                                   -- still ONLY A
--   select * from family_clan_roster(array['<clan B id>']::uuid[]);  -- B's roster
--   select count(*) from players;                                 -- still ONLY A's
--
-- As a signed-in account holding no clan role at all:
--
--   select count(*) from family_clans();                          -- 0
-- ---------------------------------------------------------------------------

-- ========================================================================
-- 039_account_administration.sql
-- ========================================================================

-- T12.2 — administering the accounts that already got in.
--
-- ─────────────────────────────────────────────────────────────────────────────
-- THE GAP THIS CLOSES
--
-- /admin/members reads `status = 'pending'` and nothing else, so an account
-- disappears from the only screen that ever showed it at the exact moment it is
-- approved. From then on there is no list of who holds an account, no way to
-- open one, no way to contact the person behind it, and no way to take access
-- away again. Approval was a one-way door with no handle on the other side.
--
-- Three capabilities, therefore, and they are deliberately the same three:
--
--   SEE    admin_accounts()        every account the caller may administer
--   SAY    send_account_message()  a message to one of them, kept, not just pushed
--   STOP   remove_account()        take access away — and restore_account() to undo
--
-- WHO MAY DO ANY OF IT — the platform admin, or a LEADER of a clan the target
-- holds a role in. Leader and not co-leader, because every one of these reads or
-- writes an email address and 013 already drew that line for exactly this data:
--
--     "Scoped to auth_leader_clan_ids(), not auth_clan_ids(): an elder should
--      not be reading strangers' email addresses."
--
-- WHY FUNCTIONS RATHER THAN A WIDER POLICY ON `users`
--
-- A policy would have to grant a leader SELECT on other people's `users` rows,
-- and `users` carries email, username, password_set_at and is_platform_admin.
-- Every future join through that table would silently inherit the widening —
-- which is 038's argument about `players`, restated for the one table where it
-- matters most. These functions return the eleven columns the admin screen
-- needs and nothing else, and RLS on `users` is left exactly as 006, 013 and 015
-- left it.
--
-- The writes are definer functions for the older reason: R4 says every write is
-- recorded, and an audit row the application appends afterwards is one it can
-- forget or forge (021). Row and audit entry, or neither.
-- ─────────────────────────────────────────────────────────────────────────────


-- ---------------------------------------------------------------------------
-- account_messages — leadership to one member, kept rather than only pushed.
--
-- WHY A TABLE AND NOT JUST A PUSH NOTIFICATION. push is best-effort by nature:
-- pushConfigured() is false in every environment with no VAPID keys, a member
-- who never granted permission has no subscription row, and lib/push.ts treats
-- every one of those as a no-op rather than an error. That is right for "the
-- roster is published" and wrong for "stop doing this or you lose your account"
-- — a warning nobody can prove was delivered is not a warning.
--
-- So the row is the message and the push is the doorbell. Same reasoning 021
-- used for announcements; this is the one-recipient case.
--
-- clan_id is the AUTHORITY the message was sent under, not a recipient filter:
-- the clan whose leadership the sender used. null means the platform admin sent
-- it platform-wide. It is here so the audit row below has a clan to be filed
-- against — see the read-policy widening at the end of this file for the case
-- where it is null.
-- ---------------------------------------------------------------------------
create table account_messages (
  id           uuid primary key default gen_random_uuid(),
  recipient_id uuid not null references users (id) on delete restrict,
  sender_id    uuid not null references users (id) on delete restrict,
  clan_id      uuid references clans (id) on delete restrict,
  subject      text not null,
  body         text not null,
  -- When the recipient opened it. Null is unread, and that is the whole state
  -- machine — a message is not a conversation and has no reply.
  read_at      timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz,
  deleted_at   timestamptz,

  -- Bounded here rather than only in the form. A Server Action is independently
  -- addressable, so the length that actually holds is the one the database
  -- enforces; the form's maxLength is the courtesy on top of it.
  constraint account_messages_subject_length check (char_length(subject) between 1 and 120),
  constraint account_messages_body_length    check (char_length(body) between 1 and 2000)
);

-- The inbox read: one member's messages, newest first.
create index account_messages_recipient_idx
  on account_messages (recipient_id, created_at desc)
  where deleted_at is null;

-- The badge count in the app shell, which runs on every navigation (T10.9) and
-- must therefore be an index-only answer rather than a scan.
create index account_messages_unread_idx
  on account_messages (recipient_id)
  where read_at is null and deleted_at is null;

create trigger account_messages_set_updated_at
  before update on account_messages
  for each row execute function set_updated_at();

alter table account_messages enable row level security;

-- Both ends of the message, and nobody else. The sender is included so the
-- admin screen can show what was already said to this person before saying it
-- again — without it, the only record of a warning is invisible to the person
-- who issued it.
create policy "read own account messages" on account_messages
  for select to authenticated
  using (recipient_id = auth.uid() or sender_id = auth.uid());

-- SELECT only. No insert policy, because send_account_message() below writes the
-- row and its audit entry together; no update policy, because a recipient with
-- UPDATE on this table could rewrite the subject and body of a warning they
-- received and then produce it as evidence of something else. Marking one read
-- is mark_message_read() for that reason alone.
grant select on account_messages to authenticated;

comment on table account_messages is
  'T12.2 — a message from leadership to one account. Written only by '
  'send_account_message(); read by its two ends. The row is the message and the '
  'push notification is the doorbell, because push is best-effort.';


-- ---------------------------------------------------------------------------
-- May the caller administer this account?
--
-- One place, called by all four functions below, so "who may do this" cannot
-- drift between seeing an account and removing one.
--
-- THE SECOND ARM OF THE clan_roles CHECK IS NOT REDUNDANT. remove_account()
-- retires the target's clan_roles rows, which is what actually takes access
-- away. If this function required a LIVE role, removing someone would put them
-- beyond the reach of the leader who just removed them — they would vanish from
-- that leader's list and only the platform admin could ever restore them. So a
-- retired role still counts, but only while the account itself is removed.
-- ---------------------------------------------------------------------------
create or replace function auth_may_administer_account(p_target uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select
    p_target is not null
    and auth.uid() is not null
    and (
      public.auth_is_platform_admin()

      -- A member of a clan this caller leads.
      or exists (
        select 1
        from public.clan_roles cr
        join public.users u on u.id = cr.user_id
        where cr.user_id = p_target
          and cr.clan_id in (select public.auth_leader_clan_ids())
          and (cr.deleted_at is null or u.deleted_at is not null)
      )

      -- An applicant who verified into one. The same audience 013's policy
      -- already shows this caller, restated here so the admin screen and the
      -- approval queue answer to one rule.
      or exists (
        select 1
        from public.users u
        where u.id = p_target
          and u.status = 'pending'
          and u.requested_clan_id in (select public.auth_leader_clan_ids())
      )
    )
$$;

revoke execute on function auth_may_administer_account(uuid) from public;
grant execute on function auth_may_administer_account(uuid) to authenticated;

comment on function auth_may_administer_account(uuid) is
  'T12.2 — platform admin, or LEADER of a clan the target belongs to. Leader '
  'and not co-leader because everything gated by this reads an email (013).';


-- ---------------------------------------------------------------------------
-- admin_accounts(search) — the directory.
--
-- Every account the caller may administer, in every status, including the ones
-- already removed. Showing removed accounts is the point of restore_account()
-- existing at all: R4 keeps the row, so the screen has to keep the row too or
-- the undo is unreachable.
--
-- memberships and players are jsonb rather than parallel text[] columns. Two
-- arrays that must line up by index is a shape that breaks silently the first
-- time one of them is filtered, and both of these are genuinely nested.
--
-- auth_may_administer_account() is called per row. That is a handful of index
-- lookups against a table this deployment measures in dozens of rows — three
-- clans, one account each — and stating the rule once is worth more here than
-- inlining it would save. Revisit if `users` ever reaches five figures.
-- ---------------------------------------------------------------------------
create or replace function admin_accounts(p_search text default null)
returns table (
  id                uuid,
  email             text,
  username          text,
  display_name      text,
  status            text,
  is_platform_admin boolean,
  created_at        timestamptz,
  approved_at       timestamptz,
  removed_at        timestamptz,
  requested_clan    text,
  memberships       jsonb,
  players           jsonb,
  unread_messages   integer
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    u.id,
    u.email,
    u.username,
    u.display_name,
    u.status,
    u.is_platform_admin,
    u.created_at,
    u.approved_at,
    -- Named removed_at, not deleted_at. R4 means the row is never gone, and a
    -- column called deleted_at on a screen that also offers Restore reads as a
    -- contradiction to everyone who did not write this file.
    u.deleted_at as removed_at,
    rc.name as requested_clan,
    coalesce(m.memberships, '[]'::jsonb),
    coalesce(p.players, '[]'::jsonb),
    coalesce(msg.unread, 0)
  from public.users u
  left join public.clans rc
    on rc.id = u.requested_clan_id

  left join lateral (
    select jsonb_agg(
             jsonb_build_object('clanId', c.id, 'clan', c.name, 'tag', c.tag, 'role', cr.role)
             order by c.tag
           ) as memberships
    from public.clan_roles cr
    join public.clans c on c.id = cr.clan_id
    where cr.user_id = u.id
      and cr.deleted_at is null
  ) m on true

  left join lateral (
    select jsonb_agg(
             jsonb_build_object('tag', pl.tag, 'name', pl.name, 'thLevel', pl.th_level)
             order by pl.tag
           ) as players
    from public.players pl
    where pl.user_id = u.id
      and pl.deleted_at is null
  ) p on true

  left join lateral (
    select count(*)::integer as unread
    from public.account_messages am
    where am.recipient_id = u.id
      and am.read_at is null
      and am.deleted_at is null
  ) msg on true

  where public.auth_may_administer_account(u.id)
    and (
      p_search is null
      or btrim(p_search) = ''
      or u.email        ilike '%' || btrim(p_search) || '%'
      or u.username     ilike '%' || btrim(p_search) || '%'
      or u.display_name ilike '%' || btrim(p_search) || '%'
      or exists (
        select 1 from public.players pl
        where pl.user_id = u.id
          and pl.deleted_at is null
          and (pl.tag ilike '%' || btrim(p_search) || '%'
            or pl.name ilike '%' || btrim(p_search) || '%')
      )
    )

  -- Waiting first, removed last. The approval queue is the thing with a
  -- deadline attached, so widening this screen from "pending only" must not
  -- push the pending accounts below a hundred approved ones.
  order by
    case
      when u.deleted_at is not null then 2
      when u.status = 'pending'     then 0
      else 1
    end,
    u.created_at desc
$$;

revoke execute on function admin_accounts(text) from public;
grant execute on function admin_accounts(text) to authenticated;

comment on function admin_accounts(text) is
  'T12.2 — every account the caller may administer, in every status. Returns '
  'zero rows rather than an error to a caller with no authority, which is how '
  'every read in this schema says no.';


-- ---------------------------------------------------------------------------
-- send_account_message — say something to one account, and keep it.
--
-- Returns the new id, or null when the caller has no authority over the target.
-- Null rather than an exception, matching approve_account(): the page turns it
-- into "the database refused that", and a raised message would name the
-- function and its checks to whoever is probing.
--
-- The PUSH is not sent here. A notification is an HTTPS round trip to a third
-- party and this is a transaction holding a write — lib/push.ts sends it after
-- this returns, and a push that fails must never roll back the message it was
-- announcing.
-- ---------------------------------------------------------------------------
create or replace function send_account_message(
  p_target  uuid,
  p_subject text,
  p_body    text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  authority uuid;
  new_id    uuid;
begin
  if auth.uid() is null or p_target is null then
    return null;
  end if;

  -- Messaging yourself is not a feature, and allowing it would put a row in the
  -- inbox that the admin screen would then offer to warn you about.
  if p_target = auth.uid() then
    return null;
  end if;

  if not public.auth_may_administer_account(p_target) then
    return null;
  end if;

  -- Which clan's leadership this was sent under. The first clan the caller
  -- leads that the target belongs to; null for a platform admin acting with no
  -- clan authority, which is a real state rather than a missing value.
  select cr.clan_id into authority
  from public.clan_roles cr
  where cr.user_id = p_target
    and cr.deleted_at is null
    and cr.clan_id in (select public.auth_leader_clan_ids())
  order by cr.clan_id
  limit 1;

  insert into public.account_messages (recipient_id, sender_id, clan_id, subject, body)
  values (p_target, auth.uid(), authority, btrim(p_subject), btrim(p_body))
  returning id into new_id;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), authority, 'message', 'account_messages', new_id,
          -- The subject, never the body. audit_log is read by every leader of
          -- the clan it is filed against, and a private warning to one member
          -- should not become clan-wide reading because it was recorded.
          jsonb_build_object('recipient', p_target, 'subject', btrim(p_subject)));

  return new_id;
end;
$$;

revoke execute on function send_account_message(uuid, text, text) from public;
grant execute on function send_account_message(uuid, text, text) to authenticated;


-- ---------------------------------------------------------------------------
-- mark_message_read — the recipient opened it.
--
-- A function rather than an UPDATE policy, and this is the one place in the
-- schema where that choice is NOT about the audit log. An update policy on
-- account_messages is necessarily `using (recipient_id = auth.uid())`, and that
-- grants the whole row: a member who received "final warning about your
-- attacks" could rewrite it to say anything and the table would keep no trace.
-- One column, changed one way, by the one person entitled to.
--
-- Not audited, for 023's reason: the subject and the actor are the same person
-- and there is no decision to justify to anyone later.
-- ---------------------------------------------------------------------------
create or replace function mark_message_read(p_message uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null or p_message is null then
    return false;
  end if;

  update public.account_messages
  set read_at = now()
  where id = p_message
    and recipient_id = auth.uid()
    and read_at is null
    and deleted_at is null;

  return found;
end;
$$;

revoke execute on function mark_message_read(uuid) from public;
grant execute on function mark_message_read(uuid) to authenticated;

-- set_updated_at fires on this update as it does on every other, and the
-- trigger is `security invoker` — but account_messages has no privilege guard
-- of its own to trip, so nothing here needs the bootstrap GUC. Stated because
-- the next function does need it, and the difference is not obvious.


-- ---------------------------------------------------------------------------
-- remove_account — take access away, reversibly.
--
-- WHAT "DELETE THIS ACCOUNT" MEANS HERE, since R4 says nothing ever is:
--
--   users.deleted_at   set          the account is removed
--   users.status       'rejected'   so the gate explains itself (T3.8)
--   clan_roles         retired      this is what actually revokes access —
--                                   auth_clan_ids() reads clan_roles, and every
--                                   RLS policy in the system reads that
--   audit_log          'remove'     with the reason the leader typed
--
-- What is NOT touched: players.user_id. The verified village stays claimed by
-- this account, so somebody removed for cause cannot simply sign up again on a
-- fresh email address and re-verify the same tag. That is the entire point of
-- removing them, and it is why this is not the mirror image of restore.
--
-- TWO ACCOUNTS CAN NEVER BE REMOVED: your own, and the platform admin's.
-- Removing your own is how a leader locks themselves out of the screen they did
-- it from; removing the admin's is how a clan leader takes the platform. 015
-- made the same argument about approve_account() refusing self-approval.
-- ---------------------------------------------------------------------------
create or replace function remove_account(p_target uuid, p_reason text default null)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  authority   uuid;
  target_row  record;
begin
  if auth.uid() is null or p_target is null or p_target = auth.uid() then
    return false;
  end if;

  -- AUTHORITY FIRST, and the order is the point. Every check below this line
  -- tells the caller something about an account — that it exists, that it is
  -- already removed, that it belongs to the platform admin. An earlier draft
  -- raised the platform-admin exception before this, which turned the function
  -- into an oracle: any signed-in member could ask "is this uuid the owner?"
  -- and read the answer off the error. A caller with no authority now learns
  -- nothing except false.
  if not public.auth_may_administer_account(p_target) then
    return false;
  end if;

  select id, is_platform_admin, deleted_at
    into target_row
  from public.users
  where id = p_target;

  if not found or target_row.deleted_at is not null then
    return false;
  end if;

  -- Raised by name rather than returned as false: this one is not "you lack
  -- authority", it is "this account is structurally not removable", and a
  -- silent false would read to the leader as a permissions problem they could
  -- ask someone to fix. Safe to raise here, because reaching this line already
  -- required authority over the account.
  if target_row.is_platform_admin then
    raise exception 'the platform admin account cannot be removed';
  end if;

  -- Resolved BEFORE the roles are retired, or the audit row lands with no clan
  -- and becomes invisible to every leader of the clan it concerns.
  select cr.clan_id into authority
  from public.clan_roles cr
  where cr.user_id = p_target
    and cr.deleted_at is null
    and cr.clan_id in (select public.auth_leader_clan_ids())
  order by cr.clan_id
  limit 1;

  -- 015's guard trigger refuses a session write to `status`. This is the
  -- sanctioned path, and the GUC is transaction-local so it cannot leak.
  perform set_config('clanbridge.bootstrap', 'on', true);

  update public.users
  set status     = 'rejected',
      deleted_at = now()
  where id = p_target;

  update public.clan_roles
  set deleted_at = now()
  where user_id = p_target
    and deleted_at is null;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), authority, 'remove', 'users', p_target,
          jsonb_build_object(
            'status', 'rejected',
            'removed', true,
            'reason', nullif(btrim(coalesce(p_reason, '')), '')));

  return true;
end;
$$;

revoke execute on function remove_account(uuid, text) from public;
grant execute on function remove_account(uuid, text) to authenticated;


-- ---------------------------------------------------------------------------
-- restore_account — the undo.
--
-- Clears deleted_at and puts the account back to 'pending'. NOT back to
-- 'approved', and not by reviving the clan_roles rows: approve_account() (017)
-- is the one thing that grants membership, and a restore that re-granted it
-- directly would be a second, quieter way into a clan that writes a different
-- audit trail. So a restored account lands exactly where a new one does — in
-- the approval queue, in front of a leader, one deliberate click from access.
--
-- That also makes the round trip honest: removing someone is reversible, but
-- letting them back in is still a decision somebody has to make on the record.
-- ---------------------------------------------------------------------------
create or replace function restore_account(p_target uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  authority uuid;
begin
  if auth.uid() is null or p_target is null then
    return false;
  end if;

  if not public.auth_may_administer_account(p_target) then
    return false;
  end if;

  -- Retired roles, so the removing leader can still find them — the second arm
  -- of auth_may_administer_account()'s clan_roles check is what makes this
  -- readable at all, and this is its one caller that depends on it.
  select cr.clan_id into authority
  from public.clan_roles cr
  where cr.user_id = p_target
    and cr.clan_id in (select public.auth_leader_clan_ids())
  order by cr.clan_id
  limit 1;

  perform set_config('clanbridge.bootstrap', 'on', true);

  update public.users
  set status      = 'pending',
      deleted_at  = null,
      approved_by = null,
      approved_at = null
  where id = p_target
    and deleted_at is not null;

  if not found then
    return false;
  end if;

  insert into public.audit_log (user_id, clan_id, action, entity, entity_id, after)
  values (auth.uid(), authority, 'restore', 'users', p_target,
          jsonb_build_object('status', 'pending', 'removed', false));

  return true;
end;
$$;

revoke execute on function restore_account(uuid) from public;
grant execute on function restore_account(uuid) to authenticated;


-- ---------------------------------------------------------------------------
-- A message to one person is its own notification kind.
--
-- The alternative was to ring the doorbell as 'announcements', and that is
-- wrong in a way that only shows up when it matters: a member who muted clan
-- notices because they were noisy would silently stop being told that their
-- leader had written to them personally. The one notification in this system
-- that is ABOUT them would be the one they never saw.
--
-- Default true, like every other column in 023, and absence of a row still
-- means every kind is enabled — push_targets() below coalesces, unchanged.
-- ---------------------------------------------------------------------------
alter table notification_preferences
  add column direct_messages boolean not null default true;

-- 023's function, restated with one branch added. `create or replace` rather
-- than an ALTER because a plpgsql body cannot be patched in place; the rest of
-- it is byte-for-byte 023 and must stay that way, so the diff between the two
-- files is exactly the line that changed.
create or replace function push_targets(p_clan uuid, p_kind text)
returns table (
  user_id  uuid,
  endpoint text,
  p256dh   text,
  auth_key text
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    ps.user_id,
    ps.endpoint,
    ps.p256dh,
    ps.auth
  from public.push_subscriptions ps
  join public.clan_roles cr
    on cr.user_id = ps.user_id
   and cr.clan_id = p_clan
   and cr.deleted_at is null
  left join public.notification_preferences np
    on np.user_id = ps.user_id
   and np.deleted_at is null
  where ps.deleted_at is null
    and case p_kind
          when 'announcements'   then coalesce(np.announcements,   true)
          when 'cwl_reminders'   then coalesce(np.cwl_reminders,   true)
          when 'war_reminders'   then coalesce(np.war_reminders,   true)
          when 'raid_reminders'  then coalesce(np.raid_reminders,  true)
          when 'poll_reminders'  then coalesce(np.poll_reminders,  true)
          when 'direct_messages' then coalesce(np.direct_messages, true)
          else false
        end
    and (
      p_clan in (select public.auth_leadership_clan_ids())
      or current_setting('role', true) = 'service_role'
    )
$$;


-- ---------------------------------------------------------------------------
-- The platform admin may read the audit log.
--
-- 006 gave audit_log exactly one read policy — `clan_id in (select
-- auth_leader_clan_ids())` — and 023 spelled out the consequence: `null in
-- (...)` is NULL, never true, so a row filed against no clan is invisible to
-- everybody, forever.
--
-- Every function above can legitimately write such a row. A platform admin
-- messaging or removing an account that belongs to no clan yet — which is
-- precisely 018's reason for the admin existing — has no clan to file it
-- against. Before this policy those were the only audited acts in the system
-- that nobody could ever read back.
--
-- 033 named this fix in advance: "if it matters, the fix is widening
-- audit_log's read policy — not a clan_id here." It matters now.
--
-- Still SELECT only. audit_log has no insert policy and must never get one.
-- ---------------------------------------------------------------------------
create policy "platform admin reads all audit log" on audit_log
  for select to authenticated
  using (auth_is_platform_admin());


-- ---------------------------------------------------------------------------
-- Verify by hand.
--
-- As a LEADER of clan A:
--
--   select count(*) from admin_accounts();          -- clan A's accounts only
--   select email from users;                        -- still your own row alone
--   select remove_account('<a member of clan B>');  -- false
--
-- As an ORDINARY member:
--
--   select count(*) from admin_accounts();          -- 0
--   select send_account_message('<anyone>', 'x', 'y');  -- null
--
-- The round trip, as the leader:
--
--   select remove_account('<member of A>', 'kept skipping war attacks');  -- true
--   select count(*) from clan_roles
--    where user_id = '<member>' and deleted_at is null;                   -- 0
--   select removed_at from admin_accounts() where id = '<member>';        -- set
--   select restore_account('<member>');                                   -- true
--   select status from admin_accounts() where id = '<member>';            -- pending
--
-- And the two that must always refuse:
--
--   select remove_account(auth.uid());              -- false
--   select remove_account('<the platform admin>');  -- raises
-- ---------------------------------------------------------------------------

commit;

-- Verify from your terminal afterwards:  npm run supabase:check
-- Expect: 21/21 tables returning zero rows to the anon key (T1.9).
